<#
.SYNOPSIS
    Unified Azure Automation runbook for the Defender vulnerability dashboard pipeline.

.DESCRIPTION
    This runbook performs the complete dashboard pipeline in a single execution:

    1. Authenticates via Managed Identity
    2. Downloads historical export data and templates from Azure Blob Storage
    3. Exports fresh vulnerability, machine, and Advanced Hunting data from MDE APIs
    4. Generates the dashboard in self-contained, hosted split-assets, or dual-output form
    5. Uploads results back to Blob Storage (compressed)

    The published runbook is generated by build/azure/Build-Runbook.ps1 from this
    source file plus the manifest-driven shared helper bundle generated by build/Build-SharedHelpers.ps1 so the distributed artifact remains
    fully self-contained with no external script dependencies.

    Export files are stored as .json.gz (GZip compressed) in blob storage to minimize
    storage costs and download bandwidth. They are decompressed in the ephemeral sandbox
    for processing and recompressed before upload.

.PARAMETER StorageAccountName
    Name of the Azure Storage account containing the exports, templates, and dashboards containers.
    If not provided, reads from the 'StorageAccountName' Automation variable.

.PARAMETER DashboardDeliveryMode
    Dashboard packaging mode. If not provided, reads from the 'DashboardDeliveryMode'
    Automation variable and defaults to SelfContained when that variable is absent.
    Options: SelfContained, Hosted, Dual

.PARAMETER IncludeAdvancedHunting
    Include Advanced Hunting data for CVE enrichment (PublishedDate, Description, EPSS).
    Requires AdvancedQuery.Read.All permission on the Managed Identity. Default: true

.PARAMETER Export
    Export target for the generated dashboard. Default: BlobStorage
    Options: BlobStorage, SharePoint, StaticWebApp

.NOTES
    Author: Nathan McNulty
    Runtime: PowerShell 7.4 (Azure Automation - custom runtime environment)

    Prerequisites:
    - System-assigned Managed Identity with:
      - Storage Blob Data Contributor on the Storage Account
      - MDE app roles: Machine.Read.All, Vulnerability.Read.All, AdvancedQuery.Read.All
    - Templates uploaded to the 'templates' blob container via Upload-Templates.ps1
#>

#Requires -Version 7.0

[CmdletBinding()]
param(
    [Parameter(Mandatory = $false)]
    [string]$StorageAccountName,

    [Parameter(Mandatory = $false)]
    [ValidateSet('SelfContained', 'Hosted', 'Dual')]
    [string]$DashboardDeliveryMode,

    [Parameter(Mandatory = $false)]
    [bool]$IncludeAdvancedHunting = $true,

    [Parameter(Mandatory = $false)]
    [bool]$UseExistingExportsOnly = $false,

    [Parameter(Mandatory = $false)]
    [ValidateSet('BlobStorage', 'SharePoint', 'StaticWebApp')]
    [string]$Export = 'BlobStorage'
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

function Resolve-PipelineExecutionHostDescriptor {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param()

    foreach ($environmentVariableName in @(
        'WEBSITE_INSTANCE_ID'
        'WEBSITE_HOSTNAME'
        'WEBSITE_SITE_NAME'
        'FUNCTIONS_WORKER_RUNTIME'
        'FUNCTIONS_EXTENSION_VERSION'
        'FUNCTIONS_WORKER_DIRECTORY'
        'FUNCTIONS_APPLICATION_DIRECTORY'
    )) {
        $environmentValue = [System.Environment]::GetEnvironmentVariable($environmentVariableName)
        if (-not [string]::IsNullOrWhiteSpace([string]$environmentValue)) {
            return [PSCustomObject]@{
                Name = 'FunctionApp'
                Evidence = $environmentVariableName
            }
        }
    }

    foreach ($environmentVariableName in @(
        'AUTOMATION_ASSET_ACCOUNTID'
        'AZUREPS_HOST_ENVIRONMENT'
    )) {
        $environmentValue = [System.Environment]::GetEnvironmentVariable($environmentVariableName)
        if (-not [string]::IsNullOrWhiteSpace([string]$environmentValue)) {
            return [PSCustomObject]@{
                Name = 'Automation'
                Evidence = $environmentVariableName
            }
        }
    }

    $psPrivateMetadataVariable = Get-Variable -Name PSPrivateMetadata -Scope Global -ErrorAction SilentlyContinue
    if ($null -ne $psPrivateMetadataVariable) {
        $psPrivateMetadata = $psPrivateMetadataVariable.Value
        $jobIdProperty = if ($null -ne $psPrivateMetadata) { $psPrivateMetadata.PSObject.Properties['JobId'] } else { $null }
        $jobId = if ($null -ne $jobIdProperty) { [string]$jobIdProperty.Value } else { '' }
        if (-not [string]::IsNullOrWhiteSpace($jobId)) {
            return [PSCustomObject]@{
                Name = 'Automation'
                Evidence = 'PSPrivateMetadata.JobId'
            }
        }
    }

    return [PSCustomObject]@{
        Name = 'Unknown'
        Evidence = $null
    }
}

