                                }
                                elseif ($propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Null -and $propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Undefined) {
                                    $cveBatchUrl = [string](Convert-JsonElementToScalarValue -Element $propertyValue)
                                }
                            }
                            'Id' {
                                if ($propertyValue.ValueKind -eq [System.Text.Json.JsonValueKind]::String) {
                                    $id = $propertyValue.GetString()
                                }
                                elseif ($propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Null -and $propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Undefined) {
                                    $id = [string](Convert-JsonElementToScalarValue -Element $propertyValue)
                                }
                            }
                            'FirstSeenTimestamp' {
                                if ($propertyValue.ValueKind -eq [System.Text.Json.JsonValueKind]::String) {
                                    $firstSeenTimestamp = $propertyValue.GetString()
                                }
                                elseif ($propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Null -and $propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Undefined) {
                                    $firstSeenTimestamp = [string](Convert-JsonElementToScalarValue -Element $propertyValue)
                                }
                            }
                            'LastSeenTimestamp' {
                                if ($propertyValue.ValueKind -eq [System.Text.Json.JsonValueKind]::String) {
                                    $lastSeenTimestamp = $propertyValue.GetString()
                                }
                                elseif ($propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Null -and $propertyValue.ValueKind -ne [System.Text.Json.JsonValueKind]::Undefined) {
                                    $lastSeenTimestamp = [string](Convert-JsonElementToScalarValue -Element $propertyValue)
                                }
                            }
                        }
                    }

                    if (-not [string]::IsNullOrWhiteSpace($deviceId)) {
                        $deviceSignature = $deviceId
                    }
                    else {
                        $deviceSignature = @(
                            $deviceId
                            $deviceName
                            $groupName
                            $osPlatform
                            $osVersion
                            ($machineTags -join $listDelimiter)
                            [string]$isOnboarded
                        ) -join $valueDelimiter
                    }
                    if (-not $deviceProfileIndex.ContainsKey($deviceSignature)) {
                        $deviceProfileIndex[$deviceSignature] = $deviceProfiles.Count
                        [void]$deviceProfiles.Add([PSCustomObject]@{
                            id = $deviceId
                            n = $deviceName
                            g = $groupName
                            o = $osPlatform
                            ov = $osVersion
                            t = $machineTags
                            ob = $isOnboarded
                        })
                    }
                    $deviceIndexValue = [int]$deviceProfileIndex[$deviceSignature]

                    $contentSignature = @(
                        $cveId
                        $softwareVendor
                        $softwareName
                        $softwareVersion
                        $severityLevel
                        [string]$cvssScore
                        $exploitabilityLevel
                        $recommendationReference
                        $recommendedSecurityUpdate
                        $recommendedSecurityUpdateId
                        $recommendedSecurityUpdateUrl
                        [string]$securityUpdateAvailable
                        ($diskPaths -join $listDelimiter)
                        ($registryPaths -join $listDelimiter)
                        $cveBatchTitle
                        $cveBatchUrl
                    ) -join $valueDelimiter
                    if (-not $contentTemplateIndex.ContainsKey($contentSignature)) {
                        $contentTemplateIndex[$contentSignature] = $contentTemplates.Count
                        [void]$contentTemplates.Add([PSCustomObject]@{
                            c = $cveId
                            sv = $softwareVendor
                            sn = $softwareName
                            ver = $softwareVersion
                            sev = $severityLevel
                            sc = $cvssScore
                            ex = $exploitabilityLevel
                            rr = $recommendationReference
                            ru = $recommendedSecurityUpdate
                            rid = $recommendedSecurityUpdateId
                            url = $recommendedSecurityUpdateUrl
                            ua = $securityUpdateAvailable
                            dp = $diskPaths
                            rp = $registryPaths
                            bt = $cveBatchTitle
                            bu = $cveBatchUrl
                        })
                    }
                    $contentIndexValue = [int]$contentTemplateIndex[$contentSignature]
                    $writer.WriteLine((
                        '[' +
                        (Convert-ToJsonStringLiteral -Value $id) + ',' +
                        $deviceIndexValue + ',' +
                        $contentIndexValue + ',' +
                        (Convert-ToJsonStringLiteral -Value $firstSeenTimestamp) + ',' +
                        (Convert-ToJsonStringLiteral -Value $lastSeenTimestamp) +
                        ']'
                    ))
                }
            }
            finally {
                if ($writer) { $writer.Dispose() }
                elseif ($gzipStream) { $gzipStream.Dispose() }
                elseif ($fileStream) { $fileStream.Dispose() }
            }
        }

        $currentPath = Get-VulnCurrentPath -BasePath $BasePath
        if (Test-Path -LiteralPath $currentPath -PathType Leaf) {
            $stagedCurrentRefsPath = Get-VulnCurrentRefsPath -BasePath $stageRoot
            & $writeObservationRefs $currentPath $stagedCurrentRefsPath
            [void]$filesToPublish.Add([PSCustomObject]@{
                StagePath = $stagedCurrentRefsPath
                TargetPath = Get-VulnCurrentRefsPath -BasePath $BasePath
            })
        }

        $periodKeys = [System.Collections.Generic.List[string]]::new()
        foreach ($historyRowsFile in @(Get-ChildItem -Path $BasePath -Filter 'VulnHistoryRows_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
            $match = [regex]::Match($historyRowsFile.Name, '^VulnHistoryRows_(?<period>\d{4}Q[1-4]|\d{4})\.json\.gz$')
            if (-not $match.Success) { continue }

            $periodKey = [string]$match.Groups['period'].Value
            [void]$periodKeys.Add($periodKey)
            $stagedHistoryRefsPath = Get-VulnHistoryRefsPath -BasePath $stageRoot -PeriodKey $periodKey
            & $writeObservationRefs $historyRowsFile.FullName $stagedHistoryRefsPath
            [void]$filesToPublish.Add([PSCustomObject]@{
                StagePath = $stagedHistoryRefsPath
                TargetPath = Get-VulnHistoryRefsPath -BasePath $BasePath -PeriodKey $periodKey
            })
        }

        $dictionaryPath = Get-VulnContentDictionaryPath -BasePath $stageRoot
        $dictionaryFileStream = $null
        $dictionaryGzipStream = $null
        $dictionaryWriter = $null
        try {
            $dictionaryFileStream = [System.IO.File]::Create($dictionaryPath)
            $dictionaryGzipStream = [System.IO.Compression.GZipStream]::new($dictionaryFileStream, [System.IO.Compression.CompressionMode]::Compress)
            $dictionaryWriter = [System.IO.StreamWriter]::new($dictionaryGzipStream, [System.Text.UTF8Encoding]::new($false))
            $dictionaryWriter.Write('{"version":"content-dictionary-v1","deviceProfiles":[')
            for ($index = 0; $index -lt $deviceProfiles.Count; $index++) {
                if ($index -gt 0) { $dictionaryWriter.Write(',') }
                $dictionaryWriter.Write((ConvertTo-Json -InputObject $deviceProfiles[$index] -Compress -Depth 20))
            }
            $dictionaryWriter.Write('],"contentTemplates":[')
            for ($index = 0; $index -lt $contentTemplates.Count; $index++) {
                if ($index -gt 0) { $dictionaryWriter.Write(',') }
                $dictionaryWriter.Write((ConvertTo-Json -InputObject $contentTemplates[$index] -Compress -Depth 20))
            }
            $dictionaryWriter.Write(']}')
        }
        finally {
            if ($dictionaryWriter) { $dictionaryWriter.Dispose() }
            elseif ($dictionaryGzipStream) { $dictionaryGzipStream.Dispose() }
            elseif ($dictionaryFileStream) { $dictionaryFileStream.Dispose() }
        }
        $deviceProfiles.Clear()
        $contentTemplates.Clear()
        [void]$filesToPublish.Add([PSCustomObject]@{
            StagePath = $dictionaryPath
            TargetPath = Get-VulnContentDictionaryPath -BasePath $BasePath
        })

        $publishedHistoryNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($periodKey in @($periodKeys | Sort-Object -Unique)) {
            if ([string]::IsNullOrWhiteSpace($periodKey)) { continue }
            [void]$publishedHistoryNames.Add([string]::Format($Script:VulnHistoryFileNamePattern, $periodKey))
            [void]$publishedHistoryNames.Add([string]::Format($Script:VulnHistoryRowsFileNamePattern, $periodKey))
            [void]$publishedHistoryNames.Add([string]::Format($Script:VulnHistoryRefsFileNamePattern, $periodKey))
        }
        [void]$publishedHistoryNames.Add($Script:VulnCurrentRefsFileName)
        [void]$publishedHistoryNames.Add($Script:VulnContentDictionaryFileName)
        $removePaths = Get-VulnHistoryRemovePaths -BasePath $BasePath -PublishedHistoryNames $publishedHistoryNames
        if ((Test-Path -LiteralPath (Get-VulnCurrentRefsPath -BasePath $BasePath) -PathType Leaf) -and -not (Test-Path -LiteralPath $currentPath -PathType Leaf)) {
            $removePaths = @($removePaths) + (Get-VulnCurrentRefsPath -BasePath $BasePath)
        }

        Publish-StoreFilesTransactional -BasePath $BasePath -StoreName 'vuln' -Files @($filesToPublish) -RemovePaths @($removePaths)
    }
    finally {
        if (Test-Path -LiteralPath $stageRoot) {
            Remove-Item -LiteralPath $stageRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}


# Canonical vulnerability store readers and validators used by generation,
# export refresh, and regression tests.

function Read-VulnStoreRow {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    Invoke-WithStoreLock -BasePath $BasePath -StoreName 'vuln' -ScriptBlock {
        Restore-StoreTransaction -BasePath $BasePath -StoreName 'vuln'

        if (-not (Test-VulnContentStoreExistence -BasePath $BasePath)) {
            try {
                Publish-VulnContentStoreUnlocked -BasePath $BasePath
            }
            catch {
                Write-Verbose "Vulnerability content sidecar rebuild failed; falling back to raw row files. $_"
            }
        }

        if (Test-VulnContentStoreExistence -BasePath $BasePath) {
            Read-VulnContentStoreRow -BasePath $BasePath
            return
        }

        $currentPath = Get-VulnCurrentPath -BasePath $BasePath
        if (Test-Path -Path $currentPath) {
            Read-VulnNdjsonRecordsFromPath -Path $currentPath
        }

        $historyFiles = @(Get-ChildItem -Path $BasePath -Filter 'VulnHistory_*.json.gz' -File | Sort-Object Name)
        foreach ($file in $historyFiles) {
            $periodMatch = [regex]::Match($file.Name, '^VulnHistory_(?<period>\d{4}Q[1-4]|\d{4})\.json\.gz$')
            $rowsPath = if ($periodMatch.Success) {
                Get-VulnHistoryRowsPath -BasePath $BasePath -PeriodKey $periodMatch.Groups['period'].Value
            }
            else {
                $null
            }
            $rowsReadPath = if (-not [string]::IsNullOrWhiteSpace($rowsPath) -and (Test-Path -LiteralPath $rowsPath -PathType Leaf)) {
                $rowsPath
            }
            elseif (-not [string]::IsNullOrWhiteSpace($rowsPath)) {
                $legacyRowsPath = $rowsPath -replace '\.gz$', ''
                if (Test-Path -LiteralPath $legacyRowsPath -PathType Leaf) { $legacyRowsPath } else { $null }
            }
            else {
                $null
            }

            if (-not [string]::IsNullOrWhiteSpace($rowsReadPath)) {
                Read-VulnNdjsonRecordsFromPath -Path $rowsReadPath
                continue
            }

            Read-VulnHistoryRowsFromPath -Path $file.FullName
        }
    } | Write-Output
}

function Test-VulnCurrentFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $validationPartitionRoot = Join-Path ([System.IO.Path]::GetTempPath()) ('vuln-current-validation-' + [guid]::NewGuid().ToString('N'))
    $partitionCount = if ($Script:VulnDiskPartitionCount -gt 0) { [int]$Script:VulnDiskPartitionCount } else { 128 }
    $partitionWriters = @{}
    $rowCount = 0

    [void](New-Item -Path $validationPartitionRoot -ItemType Directory -Force)
    try {
        try {
            Read-VulnNdjsonRecordsFromPath -Path $Path | ForEach-Object {
                $id = [string](Get-VulnPropertyValue -InputObject $_ -Name 'Id')
                if ([string]::IsNullOrWhiteSpace($id)) {
                    throw 'Current vulnerability store contains a row without Id.'
                }

                $partitionIndex = Get-VulnPartitionIndex -Id $id -PartitionCount $partitionCount
                if (-not $partitionWriters.ContainsKey($partitionIndex)) {
                    $partitionPath = Get-VulnPartitionFilePath -Root $validationPartitionRoot -Prefix 'id' -Index $partitionIndex
                    $partitionWriters[$partitionIndex] = [System.IO.StreamWriter]::new($partitionPath, $true, [System.Text.UTF8Encoding]::new($false))
                }

                $partitionWriters[$partitionIndex].WriteLine($id)
                $rowCount++
            }
        }
        finally {
            foreach ($writer in @($partitionWriters.Values)) {
                if ($null -ne $writer) {
                    $writer.Dispose()
                }
            }
        }

        for ($partitionIndex = 0; $partitionIndex -lt $partitionCount; $partitionIndex++) {
            $partitionPath = Get-VulnPartitionFilePath -Root $validationPartitionRoot -Prefix 'id' -Index $partitionIndex
            if (-not (Test-Path -LiteralPath $partitionPath -PathType Leaf)) {
                continue
            }

            $idSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            $reader = [System.IO.StreamReader]::new($partitionPath, [System.Text.UTF8Encoding]::new($false))
            try {
                while (-not $reader.EndOfStream) {
                    $id = $reader.ReadLine()
                    if ([string]::IsNullOrWhiteSpace($id)) {
                        throw 'Current vulnerability store contains a row without Id.'
                    }

                    if (-not $idSet.Add($id)) {
                        throw "Current vulnerability store contains duplicate Id '$id'."
                    }
                }
            }
            finally {
                $reader.Dispose()
            }
        }
    }
    finally {
        if (Test-Path -LiteralPath $validationPartitionRoot -PathType Container) {
            Remove-Item -LiteralPath $validationPartitionRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    return $rowCount
}

function Get-VulnRowStreamFingerprint {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [scriptblock]$RowSource,

        [Parameter(Mandatory = $true)]
        [string]$Label
    )

    $hash = [System.Security.Cryptography.IncrementalHash]::CreateHash([System.Security.Cryptography.HashAlgorithmName]::SHA256)
    $rowCount = 0

    try {
        & $RowSource | ForEach-Object {
            $row = $_
            if ($null -ne $row) {
                $id = [string](Get-VulnPropertyValue -InputObject $row -Name 'Id')
                if ([string]::IsNullOrWhiteSpace($id)) {
                    throw "$Label contains a row without Id."
                }

                $rowJson = Convert-VulnObjectToCompactJson -InputObject $row -Depth 20
                $rowBytes = [System.Text.Encoding]::UTF8.GetBytes($rowJson)
                $hash.AppendData($rowBytes)
                $hash.AppendData([byte[]]@(0x0a))
                $rowCount++
            }
        }

        $hashBytes = $hash.GetHashAndReset()
        return [PSCustomObject]@{
            RowCount = $rowCount
            Sha256 = ([System.BitConverter]::ToString($hashBytes)).Replace('-', '').ToLowerInvariant()
        }
    }
    finally {
        $hash.Dispose()
    }
}

function Test-VulnHistoryRowSidecarMatch {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HistoryPath,

        [Parameter(Mandatory = $true)]
        [string]$RowsPath
    )

    if (-not (Test-Path -LiteralPath $RowsPath -PathType Leaf)) {
        throw "History rows sidecar '$RowsPath' is missing."
    }

    $historyFingerprint = Get-VulnRowStreamFingerprint -Label "History file '$HistoryPath'" -RowSource {
        Read-VulnHistoryRowsFromPath -Path $HistoryPath
    }
    $sidecarFingerprint = Get-VulnRowStreamFingerprint -Label "History rows sidecar '$RowsPath'" -RowSource {
        Read-VulnNdjsonRecordsFromPath -Path $RowsPath
    }

    if ($historyFingerprint.RowCount -ne $sidecarFingerprint.RowCount) {
        throw "History rows sidecar '$RowsPath' row count '$($sidecarFingerprint.RowCount)' does not match history file '$HistoryPath' row count '$($historyFingerprint.RowCount)'."
    }

    if ($historyFingerprint.Sha256 -ne $sidecarFingerprint.Sha256) {
        throw "History rows sidecar '$RowsPath' content does not match history file '$HistoryPath'."
    }

    return [int]$sidecarFingerprint.RowCount
}

function Get-VulnHistoryLayoutState {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $true)]
        [System.IO.FileInfo]$HistoryFile
    )

    $periodKey = Get-VulnHistoryPeriodKeyFromFileName -Name $HistoryFile.Name
    $isQuarterly = (-not [string]::IsNullOrWhiteSpace($periodKey)) -and ($periodKey -match '^\d{4}Q[1-4]$')
    $rowsPath = if ($isQuarterly) { Get-VulnHistoryRowsPath -BasePath $BasePath -PeriodKey $periodKey } else { $null }
    $historyFileValid = $false
    $rowsSidecarValid = $false
    $rowCount = 0
    $validationMessage = $null

    if ($isQuarterly) {
        try {
            [void](Test-VulnHistoryFileLightweight -Path $HistoryFile.FullName)
            $historyFileValid = $true
        }
        catch {
            $validationMessage = $_.Exception.Message
        }

        if ($historyFileValid) {
            try {
                $rowCount = Test-VulnHistoryRowSidecarMatch -HistoryPath $HistoryFile.FullName -RowsPath $rowsPath
                $rowsSidecarValid = $true
            }
            catch {
                $validationMessage = $_.Exception.Message
            }
        }
    }

    return [PSCustomObject]@{
        PeriodKey = $periodKey
        IsQuarterly = $isQuarterly
        HistoryFileValid = $historyFileValid
        RowsPath = $rowsPath
        RowsSidecarValid = $rowsSidecarValid
        RowCount = [int]$rowCount
        RequiresRepair = ((-not $isQuarterly) -or (-not $historyFileValid) -or (-not $rowsSidecarValid))
        ValidationMessage = $validationMessage
    }
}

function Test-VulnHistoryFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $document = Read-VulnHistoryDocument -Path $Path
    $hasYear = Test-VulnPropertyPresence -InputObject $document -Name 'year'
    $hasPeriod = Test-VulnPropertyPresence -InputObject $document -Name 'period'
    $hasQuarter = Test-VulnPropertyPresence -InputObject $document -Name 'quarter'
    if ((-not $hasYear) -or (($hasPeriod -or $hasQuarter) -and -not ($hasPeriod -and $hasQuarter))) {
        throw "History file '$Path' is missing required partition metadata."
    }
    if (-not (Test-VulnPropertyPresence -InputObject $document -Name 'snapshots')) {
        throw "History file '$Path' is missing 'snapshots'."
    }

    $snapshotItems = [System.Collections.Generic.List[object]]::new()
    foreach ($snapshot in (Get-VulnPropertyValue -InputObject $document -Name 'snapshots')) {
        if ($null -eq $snapshot) { continue }
        $snapshotItems.Add($snapshot)
    }

    $snapshotDates = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::Ordinal)
    foreach ($snapshot in $snapshotItems) {
        if ($null -eq $snapshot) { continue }
        $date = [string](Get-VulnPropertyValue -InputObject $snapshot -Name 'date')
        if ([string]::IsNullOrWhiteSpace($date)) {
            throw "History file '$Path' contains a snapshot without date."
        }
        if (-not $snapshotDates.Add($date)) {
            throw "History file '$Path' contains duplicate snapshot date '$date'."
        }

        $closedEntryItems = [System.Collections.Generic.List[object]]::new()
        foreach ($entry in (Get-VulnPropertyValue -InputObject $snapshot -Name 'closed')) {
            if ($null -eq $entry) { continue }
            $closedEntryItems.Add($entry)
        }
        foreach ($entry in $closedEntryItems) {
            if ($null -eq $entry) { continue }
            $reason = [string](Get-VulnPropertyValue -InputObject $entry -Name 'reason')
            if ($reason -notin @('removed', 'changed')) {
                throw "History file '$Path' contains invalid close reason '$reason'."
            }
            $row = Get-VulnPropertyValue -InputObject $entry -Name 'row'
            if ($null -eq $row) {
                throw "History file '$Path' contains a closed entry without row payload."
            }
            $id = [string](Get-VulnPropertyValue -InputObject $row -Name 'Id')
            if ([string]::IsNullOrWhiteSpace($id)) {
                throw "History file '$Path' contains a closed row without Id."
            }
        }
    }

    $storedLatestDate = [string](Get-VulnPropertyValue -InputObject $document -Name 'latestDate')
    if (-not [string]::IsNullOrWhiteSpace($storedLatestDate) -and $snapshotDates.Count -gt 0) {
        $maxSnapshotDate = @($snapshotDates | Sort-Object)[-1]
        if ($storedLatestDate -ne $maxSnapshotDate) {
            throw "History file '$Path' latestDate '$storedLatestDate' does not match max snapshot date '$maxSnapshotDate'."
        }
    }

    return $snapshotItems.Count
}

function Test-VulnHistoryFileLightweight {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $fileStream = [System.IO.File]::OpenRead($Path)
    try {
        $header = New-Object byte[] 2
        $bytesRead = $fileStream.Read($header, 0, $header.Length)
        $fileStream.Position = 0

        $contentStream = if (($bytesRead -eq 2) -and $header[0] -eq 0x1f -and $header[1] -eq 0x8b) {
            [System.IO.Compression.GZipStream]::new($fileStream, [System.IO.Compression.CompressionMode]::Decompress)
        }
        else {
            $fileStream
        }

        try {
            $reader = [System.IO.StreamReader]::new($contentStream, [System.Text.UTF8Encoding]::new($false))
            try {
                $prefixBuilder = [System.Text.StringBuilder]::new()
                $buffer = New-Object char[] 8192
                $totalChars = 0

                while (($charsRead = $reader.Read($buffer, 0, $buffer.Length)) -gt 0) {
                    if ($prefixBuilder.Length -lt 4096) {
                        $charsToKeep = [Math]::Min(4096 - $prefixBuilder.Length, $charsRead)
                        [void]$prefixBuilder.Append($buffer, 0, $charsToKeep)
                    }
                    $totalChars += $charsRead
                }

                if ($totalChars -eq 0) {
                    throw "History file '$Path' is empty."
                }

                $prefix = $prefixBuilder.ToString()
                if ($prefix -notmatch '^\s*\{') {
                    throw "History file '$Path' does not begin with a JSON object."
                }
                if ($prefix -notmatch '"year"\s*:') {
                    throw "History file '$Path' is missing 'year'."
                }
                if ($prefix -notmatch '"latestDate"\s*:') {
                    throw "History file '$Path' is missing 'latestDate'."
                }
                if ($prefix -notmatch '"snapshots"\s*:') {
                    throw "History file '$Path' is missing 'snapshots'."
                }
                $hasPeriod = $prefix -match '"period"\s*:'
                $hasQuarter = $prefix -match '"quarter"\s*:'
                if ($hasPeriod -xor $hasQuarter) {
                    throw "History file '$Path' has incomplete quarter partition metadata."
                }

                return $totalChars
            }
            finally {
                $reader.Dispose()
            }
        }
        finally {
            if ($contentStream -ne $fileStream) {
                $contentStream.Dispose()
            }
        }
    }
    finally {
        $fileStream.Dispose()
    }
}

function Get-VulnHistoryDocumentList {
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    $documents = [System.Collections.Generic.List[object]]::new()
    foreach ($file in Get-ChildItem -Path $BasePath -Filter 'VulnHistory_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name) {
        foreach ($document in Convert-VulnHistoryDocumentToQuarterlyDocuments -HistoryDocument (Read-VulnHistoryDocument -Path $file.FullName)) {
            $documents.Add($document)
        }
    }

    return @($documents)
}

function Get-VulnStoreLatestSnapshotDate {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    $maxDate = $null

    $currentPath = Get-VulnCurrentPath -BasePath $BasePath
    if (Test-Path -Path $currentPath) {
        Read-VulnNdjsonRecordsFromPath -Path $currentPath | ForEach-Object {
            $lastSeen = Convert-VulnToYmdDate -DateValue (Get-VulnPropertyValue -InputObject $_ -Name 'LastSeenTimestamp')
            if (-not [string]::IsNullOrWhiteSpace($lastSeen)) {
                $maxDate = Get-MaxVulnDate -Primary $maxDate -Secondary $lastSeen
            }
        }
    }

    foreach ($file in Get-ChildItem -Path $BasePath -Filter 'VulnHistory_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name) {
        $docLatest = Get-VulnHistoryFileLatestDate -Path $file.FullName
        if (-not [string]::IsNullOrWhiteSpace($docLatest)) {
            $maxDate = Get-MaxVulnDate -Primary $maxDate -Secondary $docLatest
        }
    }

    return $maxDate
}


# Bulk snapshot import helpers. The downloaded file names retain the historic
# VulnExport_* shape, but local normalization no longer supports that format as
# a first-class input.

function Test-VulnStoreRequiresCanonicalRepair {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    $historyFiles = @(Get-ChildItem -Path $BasePath -Filter 'VulnHistory_*.json.gz' -File -ErrorAction SilentlyContinue)
    foreach ($historyFile in $historyFiles) {
        $historyLayoutState = Get-VulnHistoryLayoutState -BasePath $BasePath -HistoryFile $historyFile
        if ($historyLayoutState.RequiresRepair) {
            return $true
        }
    }

    return $false
}

function Publish-VulnStoreExistingCanonicalState {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [string]$LatestSnapshotDate
    )

    $currentPath = Get-VulnCurrentPath -BasePath $BasePath
    $requiresCanonicalRepair = Test-VulnStoreRequiresCanonicalRepair -BasePath $BasePath
    if ($requiresCanonicalRepair) {
        $historyPeriodCount = Repair-VulnHistoryLayout -BasePath $BasePath
    }
    else {
        $historyPeriodCount = @(Get-ChildItem -Path $BasePath -Filter 'VulnHistory_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name).Count
    }

    $currentRows = if (Test-Path -LiteralPath $currentPath -PathType Leaf) { Test-VulnCurrentFile -Path $currentPath } else { 0 }
    Publish-VulnContentStoreUnlocked -BasePath $BasePath

    return [PSCustomObject]@{
        CurrentRows = $currentRows
        HistoryYears = $historyPeriodCount
        LatestSnapshotDate = $LatestSnapshotDate
        CanonicalRepairPerformed = $requiresCanonicalRepair
    }
}

function Publish-VulnerabilityHistoryStore {
    <#
    .SYNOPSIS
        Converts downloaded vulnerability snapshots into the canonical gzip store.

    .DESCRIPTION
        The MDE bulk export arrives as dated snapshot files, so this function upgrades them
        immediately into VulnExport_current.json.gz plus quarterly VulnHistory_YYYYQn.json.gz /
        VulnHistoryRows_YYYYQn.json.gz files and removes the temporary raw snapshot files after
        successful publication.
    #>
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $false)]
        [string[]]$DownloadedFiles
    )

    $legacyFiles = if ($null -ne $DownloadedFiles -and $DownloadedFiles.Count -gt 0) {
        @(
            $DownloadedFiles |
                ForEach-Object {
                    if (Test-Path -Path $_ -PathType Leaf) {
                        Get-Item -LiteralPath $_
                    }
                } |
                Where-Object { $null -ne $_ -and (Test-IsLegacyVulnSnapshotFileName -Name $_.Name) } |
                Sort-Object Name
        )
    }
    else {
        @(Get-ChildItem -Path $OutputPath -File | Where-Object { Test-IsLegacyVulnSnapshotFileName -Name $_.Name } | Sort-Object Name)
    }

    if ($legacyFiles.Count -eq 0) {
        if (Test-VulnStoreExistence -BasePath $OutputPath) {
            return [PSCustomObject]@{
                DownloadedFiles = 0
                CurrentRows = @(
                    Read-NormalizedVulnStoreRow -BasePath $OutputPath | Where-Object {
                        (Get-VulnPropertyValue -InputObject $_ -Name 'FirstSeenTimestamp') -and
                        (Get-VulnPropertyValue -InputObject $_ -Name 'LastSeenTimestamp')
                    }
                ).Count
                HistoryYears = @(Get-ChildItem -Path $OutputPath -Filter 'VulnHistory_*.json.gz' -File -ErrorAction SilentlyContinue).Count
                LatestSnapshotDate = Get-VulnStoreLatestSnapshotDate -BasePath $OutputPath
                MigratedLegacy = $false
                RemovedLegacyFiles = $false
            }
        }

        throw 'No vulnerability export files were downloaded and no canonical vulnerability store exists.'
    }

    $publishResult = Publish-VulnStoreFromBulkSnapshot -BasePath $OutputPath -SnapshotFilePaths $legacyFiles.FullName -RemoveSnapshotFiles
    Write-Host "  Canonical vulnerability store updated: $($publishResult.CurrentRows) current row(s), $($publishResult.HistoryYears) history period file(s)" -ForegroundColor Green
    return $publishResult
}

function Get-VulnSnapshotFilesBySnapshotDate {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [System.IO.FileInfo[]]$SnapshotFiles,

        [Parameter(Mandatory = $true)]
        [string[]]$SnapshotDates
    )

    $filesByDate = @{}
    foreach ($file in @($SnapshotFiles)) {
        $date = Get-VulnSnapshotDateFromName -Name $file.Name
        if ($date -notin $SnapshotDates) { continue }
        if (-not $filesByDate.ContainsKey($date)) {
            $filesByDate[$date] = [System.Collections.Generic.List[object]]::new()
        }
        $filesByDate[$date].Add($file)
    }

    return $filesByDate
}

function Publish-VulnStoreFromBulkSnapshot {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSAvoidUsingWriteHost', '')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [string[]]$SnapshotFilePaths,

        [Parameter(Mandatory = $false)]
        [switch]$RemoveSnapshotFiles
    )

    $snapshotFiles = @(Get-VulnLegacySnapshotFile -BasePath $BasePath -LegacyFilePaths $SnapshotFilePaths)

    if ($snapshotFiles.Count -eq 0) {
        if (-not (Test-VulnStoreExistence -BasePath $BasePath)) {
            throw "No downloaded vulnerability snapshot files were found in '$BasePath'."
        }

        $canonicalState = Publish-VulnStoreExistingCanonicalState -BasePath $BasePath -LatestSnapshotDate (Get-VulnStoreLatestSnapshotDate -BasePath $BasePath)
        return [PSCustomObject]@{
            DownloadedFiles = 0
            CurrentRows = $canonicalState.CurrentRows
            HistoryYears = $canonicalState.HistoryYears
            LatestSnapshotDate = $canonicalState.LatestSnapshotDate
            CanonicalRepairPerformed = $canonicalState.CanonicalRepairPerformed
            RemovedSnapshotFiles = $false
        }
    }

    $publishOutput = @(Invoke-WithStoreLock -BasePath $BasePath -StoreName 'vuln' -ScriptBlock {
        Restore-StoreTransaction -BasePath $BasePath -StoreName 'vuln'

        $storeExists = Test-VulnStoreExistence -BasePath $BasePath
        $partitionCount = $Script:VulnDiskPartitionCount
        $latestKnownSnapshot = if ($storeExists) { Get-VulnStoreLatestSnapshotDate -BasePath $BasePath } else { $null }
        $snapshotDates = @($snapshotFiles | ForEach-Object { Get-VulnSnapshotDateFromName -Name $_.Name } | Sort-Object -Unique)

        if (-not [string]::IsNullOrWhiteSpace($latestKnownSnapshot)) {
            $duplicateLatestDates = @($snapshotDates | Where-Object { ([datetime]$_) -eq ([datetime]$latestKnownSnapshot) })
            if ($duplicateLatestDates.Count -gt 0) {
                Write-Verbose "Skipping snapshot dates already represented by the current store latest snapshot date. StoreLatest=$latestKnownSnapshot Incoming=$($duplicateLatestDates -join ', ')"
                $snapshotDates = @($snapshotDates | Where-Object { ([datetime]$_) -ne ([datetime]$latestKnownSnapshot) })
            }

            $backfillDates = @($snapshotDates | Where-Object { ([datetime]$_) -lt ([datetime]$latestKnownSnapshot) })
            if ($backfillDates.Count -gt 0) {
                throw ("Snapshot date(s) {0} are older than the current store latest snapshot date {1}. Rebuild the vulnerability store from the full snapshot set before importing backfilled history." -f ($backfillDates -join ', '), $latestKnownSnapshot)
            }
        }

        if ($snapshotDates.Count -eq 0 -and $storeExists) {
            $canonicalState = Publish-VulnStoreExistingCanonicalState -BasePath $BasePath -LatestSnapshotDate $latestKnownSnapshot
            return [PSCustomObject]@{
                DownloadedFiles = $snapshotFiles.Count
                CurrentRows = $canonicalState.CurrentRows
                HistoryYears = $canonicalState.HistoryYears
                LatestSnapshotDate = $canonicalState.LatestSnapshotDate
                CanonicalRepairPerformed = $canonicalState.CanonicalRepairPerformed
                RemovedSnapshotFiles = $false
            }
        }

        $filesByDate = Get-VulnSnapshotFilesBySnapshotDate -SnapshotFiles $snapshotFiles -SnapshotDates $snapshotDates

        $stageRoot = Join-Path $BasePath ('.vuln-store-staging-' + [guid]::NewGuid().ToString('N'))
        [void](New-Item -Path $stageRoot -ItemType Directory -Force)

        $historyAppendState = @{}
        try {
            $currentPath = Get-VulnCurrentPath -BasePath $BasePath
            $currentPartitionRoot = Join-Path $stageRoot 'current-partitions'
            [void](New-Item -Path $currentPartitionRoot -ItemType Directory -Force)
            if ($storeExists -and (Test-Path -LiteralPath $currentPath -PathType Leaf)) {
                [void](Split-VulnJsonPartition -InputPaths @($currentPath) -OutputRoot $currentPartitionRoot -Prefix 'current' -PartitionCount $partitionCount)
            }

            Write-Output ("  Canonicalizing {0} new snapshot date(s) across {1} file(s) using {2} disk partition(s)..." -f $snapshotDates.Count, $snapshotFiles.Count, $partitionCount)
            foreach ($snapshotDate in $snapshotDates) {
                $closedOn = Get-VulnPreviousDay -Date $snapshotDate
                $snapshotPartitionRoot = Join-Path $stageRoot ('snapshot-' + $snapshotDate)
                [void](New-Item -Path $snapshotPartitionRoot -ItemType Directory -Force)
                $snapshotFilesForDate = @($filesByDate[$snapshotDate] ?? @())
                $snapshotIndex = [array]::IndexOf($snapshotDates, $snapshotDate) + 1
                Write-Output ("  [{0}/{1}] Processing snapshot date {2} from {3} file(s)..." -f $snapshotIndex, $snapshotDates.Count, $snapshotDate, $snapshotFilesForDate.Count)
                if (Get-Command -Name Write-MemoryUsage -ErrorAction SilentlyContinue) {
                    Write-MemoryUsage -Label ("VulnStore " + $snapshotDate + ' Start')
                }

                try {
                    [void](Split-VulnJsonPartition `
                        -InputPaths @($snapshotFilesForDate | ForEach-Object { $_.FullName }) `
                        -OutputRoot $snapshotPartitionRoot `
                        -Prefix 'snapshot' `
                        -OnboardedOnly `
                        -PartitionCount $partitionCount)

                    for ($partitionIndex = 0; $partitionIndex -lt $partitionCount; $partitionIndex++) {
                        $currentPartitionPath = Get-VulnPartitionFilePath -Root $currentPartitionRoot -Prefix 'current' -Index $partitionIndex
                        $snapshotPartitionPath = Get-VulnPartitionFilePath -Root $snapshotPartitionRoot -Prefix 'snapshot' -Index $partitionIndex

                        if (-not (Test-Path -LiteralPath $currentPartitionPath -PathType Leaf) -and -not (Test-Path -LiteralPath $snapshotPartitionPath -PathType Leaf)) {
                            continue
                        }

                        $currentMap = Read-VulnPartitionMapFile -Path $currentPartitionPath
                        $snapshotRows = Read-VulnPartitionMapFile -Path $snapshotPartitionPath

                        foreach ($id in @($currentMap.Keys)) {
                            if ($snapshotRows.ContainsKey($id)) { continue }

                            $closedEntry = New-ClosedVulnEntry -Record ($currentMap[$id].Json | ConvertFrom-Json -Depth 20) -Reason 'removed' -ClosedOn $closedOn
                            Add-VulnHistoryEntryToAppendStore -AppendStateByPeriod $historyAppendState -ScratchRoot $stageRoot -SnapshotDate $snapshotDate -ClosedOn $closedOn -Entry $closedEntry
                        }

                        foreach ($id in @($snapshotRows.Keys)) {
                            $incomingVersion = $snapshotRows[$id]
                            $incomingRecord = $incomingVersion.Json | ConvertFrom-Json -Depth 20
                            $existing = $currentMap[$id]
                            $versionStartDate = if ($null -eq $existing -or [string]::IsNullOrWhiteSpace([string]$existing.VersionStartDate)) {
                                $snapshotDate
                            }
                            else {
                                [string]$existing.VersionStartDate
                            }

                            if ($null -ne $existing -and [string]$existing.Signature -ne [string]$incomingVersion.Signature) {
                                $closedEntry = New-ClosedVulnEntry -Record ($existing.Json | ConvertFrom-Json -Depth 20) -Reason 'changed' -ClosedOn $closedOn -ReplacementId $id
                                Add-VulnHistoryEntryToAppendStore -AppendStateByPeriod $historyAppendState -ScratchRoot $stageRoot -SnapshotDate $snapshotDate -ClosedOn $closedOn -Entry $closedEntry
                                $versionStartDate = $snapshotDate
                            }

                            $openRecord = New-OpenVulnRecord -Record $incomingRecord -VersionStartDate $versionStartDate
                            $snapshotRows[$id] = [PSCustomObject]@{
                                Json = $openRecord | ConvertTo-Json -Compress -Depth 20
                                Signature = [string]$incomingVersion.Signature
                                VersionStartDate = $versionStartDate
                            }
                        }

                        [void](Write-VulnPartitionMapFile -Path $currentPartitionPath -RowsById $snapshotRows)
                    }
                }
                finally {
                    if (Get-Command -Name Write-MemoryUsage -ErrorAction SilentlyContinue) {
                        Write-MemoryUsage -Label ("VulnStore " + $snapshotDate + ' End')
                    }
                    if (Test-Path -LiteralPath $snapshotPartitionRoot) {
                        Remove-Item -LiteralPath $snapshotPartitionRoot -Recurse -Force -ErrorAction SilentlyContinue
                    }
                }
            }

            Close-VulnHistoryAppendStore -AppendStateByPeriod $historyAppendState

            $stagedCurrentPath = Get-VulnCurrentPath -BasePath $stageRoot
            [void](Write-VulnCurrentFileFromPartition -PartitionRoot $currentPartitionRoot -PartitionPrefix 'current' -OutputPath $stagedCurrentPath -PartitionCount $partitionCount)
            $currentCount = Test-VulnCurrentFile -Path $stagedCurrentPath

            $filesToPublish = [System.Collections.Generic.List[object]]::new()
            $filesToPublish.Add([PSCustomObject]@{
                StagePath = $stagedCurrentPath
                TargetPath = Get-VulnCurrentPath -BasePath $BasePath
            })

            $touchedPeriods = @($historyAppendState.Keys | Sort-Object)
            foreach ($periodKey in $touchedPeriods) {
                $appendState = $historyAppendState[$periodKey]
                $existingDocument = Read-VulnHistoryDocumentIfPresent -BasePath $BasePath -PeriodKey $periodKey
                $existingLatestDate = if ($null -ne $existingDocument) {
                    Get-VulnHistoryDocumentLatestDate -HistoryDocument $existingDocument
                }
                else {
                    $null
                }

                $finalLatestDate = Get-MaxVulnDate `
                    -Primary $existingLatestDate `
                    -Secondary ([string]$appendState.LatestDate)
                $historyStagePath = Get-VulnHistoryPath -BasePath $stageRoot -PeriodKey $periodKey
                Write-VulnHistoryDocumentFromAppendFile `
                    -Path $historyStagePath `
                    -PeriodKey $periodKey `
                    -ExistingDocument $existingDocument `
                    -AppendPath ([string]$appendState.AppendPath) `
                    -LatestDate $finalLatestDate
                [void](Test-VulnHistoryFileLightweight -Path $historyStagePath)
                $historyRowsStagePath = Get-VulnHistoryRowsPath -BasePath $stageRoot -PeriodKey $periodKey
                Write-VulnHistoryRowsFileFromAppendFile `
                    -Path $historyRowsStagePath `
                    -ExistingDocument $existingDocument `
                    -AppendPath ([string]$appendState.AppendPath)

                $filesToPublish.Add([PSCustomObject]@{
                    StagePath = $historyStagePath
                    TargetPath = Get-VulnHistoryPath -BasePath $BasePath -PeriodKey $periodKey
                })
                $filesToPublish.Add([PSCustomObject]@{
                    StagePath = $historyRowsStagePath
                    TargetPath = Get-VulnHistoryRowsPath -BasePath $BasePath -PeriodKey $periodKey
                })

                $existingDocument = $null
            }

            $existingHistoryFiles = @(Get-ChildItem -Path $BasePath -Filter 'VulnHistory_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name)
            foreach ($historyFile in $existingHistoryFiles) {
                $periodKey = Get-VulnHistoryPeriodKeyFromFileName -Name $historyFile.Name
                if ([string]::IsNullOrWhiteSpace($periodKey)) { continue }
                if ($periodKey -in $touchedPeriods) { continue }

                $historyRowsTargetPath = Get-VulnHistoryRowsPath -BasePath $BasePath -PeriodKey $periodKey
                if (Test-Path -LiteralPath $historyRowsTargetPath -PathType Leaf) { continue }

                $historyRowsStagePath = Get-VulnHistoryRowsPath -BasePath $stageRoot -PeriodKey $periodKey
                Write-VulnHistoryRowsFileFromHistoryPath -HistoryPath $historyFile.FullName -OutputPath $historyRowsStagePath
                $filesToPublish.Add([PSCustomObject]@{
                    StagePath = $historyRowsStagePath
                    TargetPath = $historyRowsTargetPath
                })
            }

            $finalHistoryPeriods = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            foreach ($historyFile in $existingHistoryFiles) {
                $periodKey = Get-VulnHistoryPeriodKeyFromFileName -Name $historyFile.Name
                if (-not [string]::IsNullOrWhiteSpace($periodKey)) {
                    [void]$finalHistoryPeriods.Add([string]$periodKey)
                }
            }
            foreach ($periodKey in $touchedPeriods) { [void]$finalHistoryPeriods.Add([string]$periodKey) }

            $publishedHistoryNames = if ($finalHistoryPeriods.Count -gt 0) {
                Get-VulnHistoryPublishedNameSet -PeriodKeys @($finalHistoryPeriods)
            }
            else {
                [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            }
            $historyFilesToRemove = Get-VulnHistoryRemovePaths -BasePath $BasePath -PublishedHistoryNames $publishedHistoryNames
            Publish-StoreFilesTransactional -BasePath $BasePath -StoreName 'vuln' -Files @($filesToPublish) -RemovePaths $historyFilesToRemove
            Publish-VulnContentStoreUnlocked -BasePath $BasePath

            return [PSCustomObject]@{
                DownloadedFiles = $snapshotFiles.Count
                CurrentRows = $currentCount
                HistoryYears = $finalHistoryPeriods.Count
                LatestSnapshotDate = if ($snapshotDates.Count -gt 0) { $snapshotDates[-1] } else { $latestKnownSnapshot }
                CanonicalRepairPerformed = $false
                RemovedSnapshotFiles = $false
            }
        }
        finally {
            Close-VulnHistoryAppendStore -AppendStateByPeriod $historyAppendState
            if (Test-Path -LiteralPath $stageRoot) {
                Remove-Item -LiteralPath $stageRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    })

    $publishResult = $null
    foreach ($item in $publishOutput) {
        if ($null -ne $item -and $item.PSObject.Properties.Match('CurrentRows').Count -gt 0 -and $item.PSObject.Properties.Match('HistoryYears').Count -gt 0) {
            $publishResult = $item
            continue
        }

        if ($null -ne $item) {
            Write-Host ([string]$item)
        }
    }

    if ($null -eq $publishResult) {
        throw 'Publish-VulnStoreFromBulkSnapshot did not return a publish result.'
    }

    if ($RemoveSnapshotFiles) {
        foreach ($snapshotFile in @(Get-VulnLegacySnapshotFile -BasePath $BasePath)) {
            Remove-Item -Path $snapshotFile.FullName -Force
        }
    }

    return [PSCustomObject]@{
        DownloadedFiles = $publishResult.DownloadedFiles
        CurrentRows = $publishResult.CurrentRows
        HistoryYears = $publishResult.HistoryYears
        LatestSnapshotDate = $publishResult.LatestSnapshotDate
        CanonicalRepairPerformed = ($publishResult.PSObject.Properties['CanonicalRepairPerformed']?.Value -eq $true)
        RemovedSnapshotFiles = ($RemoveSnapshotFiles -eq $true)
    }
}


# Shared machine storage helpers used by export, generator, and the Azure runbook.

function ConvertTo-CompactMachineRecord {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$Machine
    )

    return [PSCustomObject]@{
        id                    = $Machine.PSObject.Properties['id']?.Value
        computerDnsName       = $Machine.PSObject.Properties['computerDnsName']?.Value
        rbacGroupName         = $Machine.PSObject.Properties['rbacGroupName']?.Value
        osPlatform            = $Machine.PSObject.Properties['osPlatform']?.Value
        osVersion             = $Machine.PSObject.Properties['osVersion']?.Value
        machineTags           = Get-NormalizedMachineTag -Tags $Machine.PSObject.Properties['machineTags']?.Value
        lastIpAddress         = $Machine.PSObject.Properties['lastIpAddress']?.Value
        lastExternalIpAddress = $Machine.PSObject.Properties['lastExternalIpAddress']?.Value
        healthStatus          = $Machine.PSObject.Properties['healthStatus']?.Value
        riskScore             = $Machine.PSObject.Properties['riskScore']?.Value
        exposureLevel         = $Machine.PSObject.Properties['exposureLevel']?.Value
        deviceValue           = $Machine.PSObject.Properties['deviceValue']?.Value
        managedBy             = $Machine.PSObject.Properties['managedBy']?.Value
        isAadJoined           = $Machine.PSObject.Properties['isAadJoined']?.Value
        lastSeen              = $Machine.PSObject.Properties['lastSeen']?.Value
        firstSeen             = $Machine.PSObject.Properties['firstSeen']?.Value
    }
}

function ConvertTo-NormalizationMachineTuple {
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Machine
    )

    if ($null -eq $Machine) {
        return $null
    }

    if ($Machine -is [System.Array]) {
        $tuple = [object[]]$Machine
        if ($tuple.Length -ge 15) {
            return $tuple
        }

        if ($tuple.Length -ge 10) {
            $extendedTuple = [System.Collections.Generic.List[object]]::new()
            foreach ($value in $tuple) {
                $extendedTuple.Add($value) | Out-Null
            }

            while ($extendedTuple.Count -lt 15) {
                $extendedTuple.Add($null) | Out-Null
            }

            return $extendedTuple.ToArray()
        }
    }

    $ip = $Machine.PSObject.Properties['lastIpAddress']?.Value
    $externalIp = $Machine.PSObject.Properties['lastExternalIpAddress']?.Value
    $healthStatus = $Machine.PSObject.Properties['healthStatus']?.Value
    $riskScore = $Machine.PSObject.Properties['riskScore']?.Value
    $exposureLevel = $Machine.PSObject.Properties['exposureLevel']?.Value
    $deviceValue = $Machine.PSObject.Properties['deviceValue']?.Value
    $managedBy = $Machine.PSObject.Properties['managedBy']?.Value
    $isAadJoined = $Machine.PSObject.Properties['isAadJoined']?.Value
    $lastSeen = $Machine.PSObject.Properties['lastSeen']?.Value
    $firstSeen = $Machine.PSObject.Properties['firstSeen']?.Value
    $osVersion = $Machine.PSObject.Properties['osVersion']?.Value
    $computerDnsName = $Machine.PSObject.Properties['computerDnsName']?.Value
    $rbacGroupName = $Machine.PSObject.Properties['rbacGroupName']?.Value
    $osPlatform = $Machine.PSObject.Properties['osPlatform']?.Value
    $machineTags = @(Get-NormalizedMachineTag -Tags $Machine.PSObject.Properties['machineTags']?.Value)

    if (
        $null -eq $ip -and
        $null -eq $externalIp -and
        $null -eq $healthStatus -and
        $null -eq $riskScore -and
        $null -eq $exposureLevel -and
        $null -eq $deviceValue -and
        $null -eq $managedBy -and
        $null -eq $isAadJoined -and
        $null -eq $lastSeen -and
        $null -eq $firstSeen -and
        $null -eq $osVersion -and
        $null -eq $computerDnsName -and
        $null -eq $rbacGroupName -and
        $null -eq $osPlatform -and
        @($machineTags).Count -eq 0
    ) {
        return $null
    }

    return [object[]]@(
        $ip,
        $externalIp,
        $healthStatus,
        $riskScore,
        $exposureLevel,
        $deviceValue,
        $managedBy,
        $isAadJoined,
        $lastSeen,
        $firstSeen,
        $osVersion,
        $computerDnsName,
        $rbacGroupName,
        $osPlatform,
        @($machineTags)
    )
}

function Get-MachineJsonElementScalarValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [System.Text.Json.JsonElement]$Element,

        [Parameter(Mandatory = $true)]
        [string]$Name
    )

    $property = [System.Text.Json.JsonElement]::new()
    if (-not $Element.TryGetProperty($Name, [ref]$property)) {
        return $null
    }

    switch ($property.ValueKind) {
        ([System.Text.Json.JsonValueKind]::Undefined) { return $null }
        ([System.Text.Json.JsonValueKind]::Null) { return $null }
        ([System.Text.Json.JsonValueKind]::String) { return $property.GetString() }
        ([System.Text.Json.JsonValueKind]::True) { return $true }
        ([System.Text.Json.JsonValueKind]::False) { return $false }
        ([System.Text.Json.JsonValueKind]::Number) {
            $int64Value = 0L
            if ($property.TryGetInt64([ref]$int64Value)) {
                return $int64Value
            }

            $doubleValue = 0.0
            if ($property.TryGetDouble([ref]$doubleValue)) {
                return $doubleValue
            }

            return $property.GetRawText()
        }
        default { return $property.GetRawText() }
    }
}

function Get-MachineJsonElementStringArrayValue {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $true)]
        [System.Text.Json.JsonElement]$Element,

        [Parameter(Mandatory = $true)]
        [string]$Name
    )

    $property = [System.Text.Json.JsonElement]::new()
    if (-not $Element.TryGetProperty($Name, [ref]$property)) {
        return [string[]]@()
    }

    switch ($property.ValueKind) {
        ([System.Text.Json.JsonValueKind]::Undefined) { return [string[]]@() }
        ([System.Text.Json.JsonValueKind]::Null) { return [string[]]@() }
        ([System.Text.Json.JsonValueKind]::String) { return (Get-NormalizedMachineTag -Tags $property.GetString()) }
        ([System.Text.Json.JsonValueKind]::Array) {
            $tagList = [System.Collections.Generic.List[string]]::new()
            foreach ($item in $property.EnumerateArray()) {
                $tagValue = switch ($item.ValueKind) {
                    ([System.Text.Json.JsonValueKind]::String) { $item.GetString() }
                    ([System.Text.Json.JsonValueKind]::Null) { $null }
                    ([System.Text.Json.JsonValueKind]::Undefined) { $null }
                    default { $item.GetRawText() }
                }

                if (-not [string]::IsNullOrWhiteSpace([string]$tagValue)) {
                    $tagList.Add([string]$tagValue) | Out-Null
                }
            }

            return (Get-NormalizedMachineTag -Tags @($tagList))
        }
        default { return (Get-NormalizedMachineTag -Tags (Get-MachineJsonElementScalarValue -Element $Element -Name $Name)) }
    }
}

function ConvertFrom-MachineJsonElementToCompactMachineRecord {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [System.Text.Json.JsonElement]$MachineElement
    )

    $machineId = [string](Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'id')
    if ([string]::IsNullOrWhiteSpace($machineId)) {
        return $null
    }

    $observedOn = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'observedOn'
    $stateHash = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'stateHash'
    if ((Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'removed') -eq $true) {
        return [PSCustomObject]@{
            id = $machineId
            observedOn = $observedOn
            removed = $true
            stateHash = $stateHash
        }
    }

    $record = [PSCustomObject]@{
        id                    = $machineId
        computerDnsName       = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'computerDnsName'
        rbacGroupName         = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'rbacGroupName'
        osPlatform            = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'osPlatform'
        osVersion             = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'osVersion'
        machineTags           = Get-MachineJsonElementStringArrayValue -Element $MachineElement -Name 'machineTags'
        lastIpAddress         = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'lastIpAddress'
        lastExternalIpAddress = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'lastExternalIpAddress'
        healthStatus          = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'healthStatus'
        riskScore             = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'riskScore'
        exposureLevel         = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'exposureLevel'
        deviceValue           = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'deviceValue'
        managedBy             = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'managedBy'
        isAadJoined           = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'isAadJoined'
        lastSeen              = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'lastSeen'
        firstSeen             = Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'firstSeen'
    }

    if (-not [string]::IsNullOrWhiteSpace([string]$stateHash)) {
        Add-Member -InputObject $record -NotePropertyName stateHash -NotePropertyValue $stateHash
    }

    if (-not [string]::IsNullOrWhiteSpace([string]$observedOn)) {
        Add-Member -InputObject $record -NotePropertyName observedOn -NotePropertyValue $observedOn
    }

    return $record
}

function ConvertFrom-MachineJsonElementToNormalizationEntry {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [System.Text.Json.JsonElement]$MachineElement
    )

    $machineId = [string](Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'id')
    if ([string]::IsNullOrWhiteSpace($machineId)) {
        return $null
    }

    if ((Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'removed') -eq $true) {
        return [PSCustomObject]@{
            id = $machineId
            removed = $true
        }
    }

    $tuple = [object[]]@(
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'lastIpAddress'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'lastExternalIpAddress'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'healthStatus'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'riskScore'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'exposureLevel'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'deviceValue'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'managedBy'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'isAadJoined'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'lastSeen'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'firstSeen'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'osVersion'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'computerDnsName'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'rbacGroupName'),
        (Get-MachineJsonElementScalarValue -Element $MachineElement -Name 'osPlatform'),
        @(Get-MachineJsonElementStringArrayValue -Element $MachineElement -Name 'machineTags')
    )

    $hasTupleValue = $false
    foreach ($value in $tuple) {
        if ($null -ne $value) {
            $hasTupleValue = $true
            break
        }
    }

    return [PSCustomObject]@{
        id = $machineId
        removed = $false
        tuple = if ($hasTupleValue) { $tuple } else { $null }
    }
}

function Read-MachineNormalizationEntriesFromFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $readContext = Open-JsonFileReadContext -Path $Path
    try {
        if ($readContext.Mode -eq 'Empty') {
            return
        }

        if ($readContext.Mode -eq 'Array') {
            $rawContent = Read-JsonFileRemainingContent -Context $readContext
            if ([string]::IsNullOrWhiteSpace($rawContent)) {
                return
            }

            $jsonDocument = [System.Text.Json.JsonDocument]::Parse($rawContent)
            $rawContent = $null
            try {
                if ($jsonDocument.RootElement.ValueKind -ne [System.Text.Json.JsonValueKind]::Array) {
                    return
                }

                foreach ($machineElement in $jsonDocument.RootElement.EnumerateArray()) {
                    $entry = ConvertFrom-MachineJsonElementToNormalizationEntry -MachineElement $machineElement
                    if ($null -ne $entry) {
                        $entry
                    }
                }
            }
            finally {
                $jsonDocument.Dispose()
            }

            return
        }

        $isFirstLine = [ref]$true
        while (-not $readContext.Reader.EndOfStream) {
            $line = Read-JsonFileLine -Context $readContext -IsFirstLine $isFirstLine
            if ([string]::IsNullOrWhiteSpace($line)) { continue }

            $jsonDocument = $null
            try {
                $jsonDocument = [System.Text.Json.JsonDocument]::Parse($line)
            }
            catch {
                Write-Warning "Failed to parse machine line in $(Split-Path -Leaf $Path): $_"
                continue
            }

            try {
                $entry = ConvertFrom-MachineJsonElementToNormalizationEntry -MachineElement $jsonDocument.RootElement
                if ($null -ne $entry) {
                    $entry
                }
            }
            finally {
                if ($null -ne $jsonDocument) {
                    $jsonDocument.Dispose()
                }
            }
        }
    }
    finally {
        Close-JsonFileReadContext -Context $readContext
    }
}

function Get-NormalizedMachineTag {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Tags
    )

    $tagList = [System.Collections.Generic.List[string]]::new()

    if ($null -eq $Tags) {
        return [string[]]@()
    }

    if ($Tags -is [string]) {
        if (-not [string]::IsNullOrWhiteSpace($Tags)) {
            $tagList.Add($Tags)
        }
    }
    elseif ($Tags -is [System.Collections.IEnumerable]) {
        foreach ($tag in $Tags) {
            if (-not [string]::IsNullOrWhiteSpace([string]$tag)) {
                $tagList.Add([string]$tag)
            }
        }
    }
    else {
        $tagValue = [string]$Tags
        if (-not [string]::IsNullOrWhiteSpace($tagValue)) {
            $tagList.Add($tagValue)
        }
    }

    if ($tagList.Count -eq 0) {
        return [string[]]@()
    }

    return [string[]]@($tagList | Sort-Object -Unique)
}

