        observedOn = $ObservedOn
        removed = $true
        stateHash = 'removed'
    }
}

function Write-NdjsonRecordsFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [System.Collections.IEnumerable]$Records
    )

    $fileStream = $null
    $gzipStream = $null
    $writer = $null
    $jsonWriter = $null
    try {
        if ($Path.EndsWith('.gz', [System.StringComparison]::OrdinalIgnoreCase)) {
            $fileStream = [System.IO.File]::Create($Path)
            $gzipStream = [System.IO.Compression.GZipStream]::new($fileStream, [System.IO.Compression.CompressionMode]::Compress)
            $writer = [System.IO.StreamWriter]::new($gzipStream, [System.Text.UTF8Encoding]::new($false))
        }
        else {
            $writer = [System.IO.StreamWriter]::new($Path, $false, [System.Text.UTF8Encoding]::new($false))
        }

        $jsonWriter = [Newtonsoft.Json.JsonTextWriter]::new($writer)
        $jsonWriter.Formatting = [Newtonsoft.Json.Formatting]::None

        foreach ($record in $Records) {
            if ($null -eq $record) { continue }

            Write-JsonValueToWriter -Writer $jsonWriter -Value $record
            $jsonWriter.Flush()
            $writer.WriteLine()
        }
    }
    finally {
        if ($jsonWriter) { $jsonWriter.Close() }
        elseif ($writer) { $writer.Dispose() }
        elseif ($gzipStream) { $gzipStream.Dispose() }
        elseif ($fileStream) { $fileStream.Dispose() }
    }
}

function Get-MachineHistoryRecordKey {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        $Record
    )

    $id = [string]$Record.PSObject.Properties['id']?.Value
    $observedOn = Convert-ToYmdDate -DateValue $Record.PSObject.Properties['observedOn']?.Value
    $removed = if ($Record.PSObject.Properties['removed']?.Value -eq $true) { '1' } else { '0' }
    $stateHash = [string]$Record.PSObject.Properties['stateHash']?.Value
    return ($id + '|' + $observedOn + '|' + $removed + '|' + $stateHash)
}

function Add-MachineHistoryRecordToPeriodMap {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$HistoryRecordsByPeriod,

        [Parameter(Mandatory = $true)]
        $RecordKeys,

        [Parameter(Mandatory = $true)]
        $Record
    )

    if ($null -eq $Record) { return }

    $id = [string]$Record.PSObject.Properties['id']?.Value
    if ([string]::IsNullOrWhiteSpace($id)) { return }

    $observedOn = Convert-ToYmdDate -DateValue $Record.PSObject.Properties['observedOn']?.Value
    if ([string]::IsNullOrWhiteSpace($observedOn)) { return }

    if (($Record.PSObject.Properties['removed']?.Value -ne $true) -and -not $Record.PSObject.Properties['stateHash']) {
        Add-Member -InputObject $Record -NotePropertyName stateHash -NotePropertyValue (Get-MachineStateHash -Machine $Record) -Force
    }

    if (-not $Record.PSObject.Properties['observedOn']) {
        Add-Member -InputObject $Record -NotePropertyName observedOn -NotePropertyValue $observedOn -Force
    }

    $recordKey = Get-MachineHistoryRecordKey -Record $Record
    if (-not $RecordKeys.Add($recordKey)) { return }

    $periodKey = Get-QuarterPeriodKeyFromDate -Date $observedOn
    if (-not $HistoryRecordsByPeriod.ContainsKey($periodKey)) {
        $HistoryRecordsByPeriod[$periodKey] = [System.Collections.Generic.List[object]]::new()
    }

    $HistoryRecordsByPeriod[$periodKey].Add($Record)
}

function Get-MachineHistoryRemovePaths {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '')]
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [AllowEmptyCollection()]
        [System.Collections.Generic.HashSet[string]]$PublishedHistoryNames
    )

    if ($null -eq $PublishedHistoryNames) {
        $PublishedHistoryNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    }

    $removePaths = [System.Collections.Generic.List[string]]::new()
    foreach ($path in @(
        Get-ChildItem -Path $BasePath -Filter 'Machines_History*.json.gz' -File -ErrorAction SilentlyContinue |
            Where-Object { -not $PublishedHistoryNames.Contains($_.Name) } |
            ForEach-Object { $_.FullName }
    )) {
        $removePaths.Add($path)
    }

    $legacyHistoryJsonPath = Get-MachineHistoryPath -BasePath $BasePath
    $legacyHistoryGzipPath = Get-LegacyCanonicalPath -Path $legacyHistoryJsonPath
    foreach ($path in @($legacyHistoryJsonPath, $legacyHistoryGzipPath)) {
        if ([string]::IsNullOrWhiteSpace($path)) { continue }
        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { continue }
        if ($removePaths -contains $path) { continue }
        $removePaths.Add($path)
    }

    return [string[]]@($removePaths)
}

function Add-InitializedMachineRecordToCurrentMap {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$CurrentRecords,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [psobject]$Record,

        [Parameter(Mandatory = $true)]
        [string]$DefaultObservedOn
    )

    if ($null -eq $Record) { return }

    $properties = $Record.PSObject.Properties
    $machineId = [string]$properties['id']?.Value
    if ([string]::IsNullOrWhiteSpace($machineId)) { return }

    if ($properties['removed']?.Value -eq $true) {
        $CurrentRecords.Remove($machineId)
        return
    }

    if ($null -eq $properties['stateHash']) {
        $properties.Add([System.Management.Automation.PSNoteProperty]::new('stateHash', (Get-MachineStateHash -Machine $Record)))
    }

    if ($null -eq $properties['observedOn']) {
        $properties.Add([System.Management.Automation.PSNoteProperty]::new('observedOn', $DefaultObservedOn))
    }

    $CurrentRecords[$machineId] = $Record
}

function Initialize-MachineHistoryStore {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $false)]
        [switch]$RemoveLegacyFiles
    )

    $currentPath = Get-MachineCurrentPath -BasePath $Path
    $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath
    $currentReadPath = if (Test-Path -Path $currentPath) { $currentPath } elseif (Test-Path -Path $legacyCurrentPath) { $legacyCurrentPath } else { $null }
    $historySourcePaths = @(Get-MachineHistoryAllSourcePaths -BasePath $Path)
    $legacyFiles = @(Get-ChildItem -Path $Path -Filter 'Machines_*.json' -File | Where-Object { Test-IsLegacyMachineSnapshotFileName -Name $_.Name } | Sort-Object Name)
    $currentRecords = @{}
    $migratedLegacy = $false
    $historyRecordsByPeriod = @{}
    $historyRecordKeys = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $defaultObservedOn = Get-Date -Format 'yyyy-MM-dd'

    foreach ($sourcePath in $historySourcePaths) {
        foreach ($record in Read-MachineRecordsFromFile -Path $sourcePath) {
            Add-MachineHistoryRecordToPeriodMap -HistoryRecordsByPeriod $historyRecordsByPeriod -RecordKeys $historyRecordKeys -Record $record
        }
    }

    if ($null -ne $currentReadPath) {
        foreach ($record in Read-MachineRecordsFromFile -Path $currentReadPath) {
            Add-InitializedMachineRecordToCurrentMap -CurrentRecords $currentRecords -Record $record -DefaultObservedOn $defaultObservedOn
        }
    } elseif ($historySourcePaths.Count -gt 0) {
        foreach ($sourcePath in $historySourcePaths) {
            foreach ($record in Read-MachineRecordsFromFile -Path $sourcePath) {
                Add-InitializedMachineRecordToCurrentMap -CurrentRecords $currentRecords -Record $record -DefaultObservedOn $defaultObservedOn
            }
        }
    }

    if ($legacyFiles.Count -gt 0) {
        foreach ($file in $legacyFiles) {
            $observedOn = [regex]::Match($file.Name, '\d{4}-\d{2}-\d{2}').Value
            foreach ($record in Read-MachineRecordsFromFile -Path $file.FullName) {
                if (-not $record.id) { continue }
                $snapshot = New-MachineSnapshotRecord -Machine $record -ObservedOn $observedOn
                $existing = $currentRecords[$snapshot.id]
                if (($null -eq $existing) -or ($existing.stateHash -ne $snapshot.stateHash)) {
                    Add-MachineHistoryRecordToPeriodMap -HistoryRecordsByPeriod $historyRecordsByPeriod -RecordKeys $historyRecordKeys -Record $snapshot
                }
                $currentRecords[$snapshot.id] = $snapshot
            }
        }
        if ($RemoveLegacyFiles) {
            Remove-Item -Path $legacyFiles.FullName -Force -ErrorAction SilentlyContinue
        }
        $migratedLegacy = $true
    }

    if (($historyRecordsByPeriod.Count -eq 0) -and $currentRecords.Count -gt 0) {
        foreach ($record in $currentRecords.Values) {
            Add-MachineHistoryRecordToPeriodMap -HistoryRecordsByPeriod $historyRecordsByPeriod -RecordKeys $historyRecordKeys -Record $record
        }
    }

    if ($migratedLegacy -and (Test-Path -Path $legacyCurrentPath)) {
        Remove-Item -Path $legacyCurrentPath -Force -ErrorAction SilentlyContinue
    }

    return @{
        CurrentPath           = $currentPath
        CurrentRecords        = $currentRecords
        HistoryRecordsByPeriod = $historyRecordsByPeriod
        MigratedLegacy        = $migratedLegacy
    }
}

function Convert-ToYmdDate {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$DateValue
    )

    if ($null -eq $DateValue) {
        return $null
    }

    $raw = $DateValue.ToString().Trim()
    if ([string]::IsNullOrWhiteSpace($raw)) {
        return $null
    }

    if ($raw -match '^\d{4}-\d{2}-\d{2}$') {
        return $raw
    }

    if ($raw.Length -ge 10 -and $raw[4] -eq '-' -and $raw[7] -eq '-') {
        return $raw.Substring(0, 10)
    }

    if ($raw -match '^(\d{1,2})/(\d{1,2})/(\d{4})') {
        $month = [int]$Matches[1]
        $day = [int]$Matches[2]
        $year = [int]$Matches[3]
        if ($month -ge 1 -and $month -le 12 -and $day -ge 1 -and $day -le 31) {
            return ('{0:D4}-{1:D2}-{2:D2}' -f $year, $month, $day)
        }
    }

    try {
        return ([datetime]$raw).ToString('yyyy-MM-dd')
    }
    catch {
        return $null
    }
}

function Get-VendorMatchKey {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$Vendor
    )

    if ([string]::IsNullOrWhiteSpace($Vendor)) {
        return ''
    }

    $trimmed = $Vendor.Trim()
    if ($env:DEFENDER_REPORTING_NORMALIZE_VENDOR_MATCH -ne '1') {
        return $trimmed
    }

    $normalized = $trimmed.ToLowerInvariant()
    $normalized = [regex]::Replace($normalized, '[^a-z0-9]+', ' ')
    $normalized = [regex]::Replace($normalized, '\b(corporation|corp|incorporated|inc|llc|ltd|limited|company|co|gmbh|ag|plc|pte)\b', ' ')
    $normalized = [regex]::Replace($normalized, '\s+', ' ').Trim()
    return $normalized
}

function Get-AdvancedHuntingLastModifiedKey {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$LastModifiedTime,

        [Parameter(Mandatory = $false)]
        [string]$FallbackDate = ''
    )

    if ($null -ne $LastModifiedTime) {
        $rawValue = $LastModifiedTime.ToString().Trim()
        if (-not [string]::IsNullOrWhiteSpace($rawValue)) {
            try {
                return ([datetimeoffset]$rawValue).UtcDateTime.ToString('o')
            }
            catch {
                $normalized = Convert-ToYmdDate -DateValue $rawValue
                if ($normalized) {
                    return $normalized
                }

                return $rawValue
            }
        }
    }

    return $FallbackDate
}

function Get-AdvancedHuntingInventoryMatchKey {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$DeviceId,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$SoftwareVendor,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$SoftwareName,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$SoftwareVersion
    )

    if ([string]::IsNullOrWhiteSpace($DeviceId) -or [string]::IsNullOrWhiteSpace($SoftwareName)) {
        return $null
    }

    return @(
        [string]$DeviceId
        [string]($SoftwareVendor ?? '')
        [string]$SoftwareName
        [string]($SoftwareVersion ?? '')
    ) -join '|'
}

function Get-AdvancedHuntingRecordType {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$Record
    )

    $explicitRecordType = [string]$Record.PSObject.Properties['RecordType']?.Value
    switch ($explicitRecordType) {
        'Cve' { return 'Cve' }
        'DeviceUsers' { return 'DeviceUsers' }
        'Inventory' { return 'Inventory' }
    }

    $cveId = [string]$Record.PSObject.Properties['CveId']?.Value
    if (-not [string]::IsNullOrWhiteSpace($cveId)) {
        return 'Cve'
    }

    $deviceId = [string]$Record.PSObject.Properties['DeviceId']?.Value
    if (-not [string]::IsNullOrWhiteSpace($deviceId) -and $null -ne $Record.PSObject.Properties['LoggedOnUsers']) {
        return 'DeviceUsers'
    }

    if (
        -not [string]::IsNullOrWhiteSpace($deviceId) -and
        -not [string]::IsNullOrWhiteSpace([string]$Record.PSObject.Properties['SoftwareName']?.Value) -and
        (
            -not [string]::IsNullOrWhiteSpace([string]$Record.PSObject.Properties['ProductCodeCpe']?.Value) -or
            -not [string]::IsNullOrWhiteSpace([string]$Record.PSObject.Properties['EndOfSupportStatus']?.Value) -or
            -not [string]::IsNullOrWhiteSpace([string]$Record.PSObject.Properties['EndOfSupportDate']?.Value)
        )
    ) {
        return 'Inventory'
    }

    return $null
}

function Get-AdvancedHuntingStoreKey {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$Record
    )

    $recordType = Get-AdvancedHuntingRecordType -Record $Record
    switch ($recordType) {
        'Cve' {
            $cveId = [string]$Record.PSObject.Properties['CveId']?.Value
            if (-not [string]::IsNullOrWhiteSpace($cveId)) {
                return ('Cve|' + $cveId)
            }
        }
        'DeviceUsers' {
            $deviceId = [string]$Record.PSObject.Properties['DeviceId']?.Value
            if (-not [string]::IsNullOrWhiteSpace($deviceId)) {
                return ('DeviceUsers|' + $deviceId)
            }
        }
        'Inventory' {
            $inventoryKey = Get-AdvancedHuntingInventoryMatchKey `
                -DeviceId ([string]$Record.PSObject.Properties['DeviceId']?.Value) `
                -SoftwareVendor ([string]$Record.PSObject.Properties['SoftwareVendor']?.Value) `
                -SoftwareName ([string]$Record.PSObject.Properties['SoftwareName']?.Value) `
                -SoftwareVersion ([string]$Record.PSObject.Properties['SoftwareVersion']?.Value)
            if (-not [string]::IsNullOrWhiteSpace($inventoryKey)) {
                return ('Inventory|' + $inventoryKey)
            }
        }
    }

    return $null
}

function Read-AdvancedHuntingRecordsFromFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $readContext = Open-JsonFileReadContext -Path $Path
    try {
        if ($readContext.Mode -eq 'Empty') {
            return
        }

        if ($readContext.Mode -eq 'Array') {
            $rawContent = Read-JsonFileRemainingContent -Context $readContext
            if ([string]::IsNullOrWhiteSpace($rawContent)) {
                return
            }

            $records = $rawContent | ConvertFrom-Json
            $rawContent = $null
            if ($null -eq $records) { return }
            if ($records -isnot [System.Array]) { $records = @($records) }

            foreach ($record in $records) {
                if ($null -ne $record) {
                    $record
                }
            }

            return
        }

        $isFirstLine = [ref]$true
        while (-not $readContext.Reader.EndOfStream) {
            $line = Read-JsonFileLine -Context $readContext -IsFirstLine $isFirstLine
            if ([string]::IsNullOrWhiteSpace($line)) { continue }
            try {
                $record = $line | ConvertFrom-Json
                if ($null -ne $record) { $record }
            }
            catch {
                Write-Warning "Failed to parse Advanced Hunting line in $(Split-Path -Leaf $Path): $_"
            }
        }
    }
    finally {
        Close-JsonFileReadContext -Context $readContext
    }
}

function Initialize-AdvancedHuntingStore {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $false)]
        [switch]$RemoveLegacyFiles
    )

    $currentPath = Get-AdvancedHuntingCurrentPath -BasePath $Path
    $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath
    $currentRecords = @{}
    $migratedLegacy = $false
    $legacyFiles = @(Get-ChildItem -Path $Path -Filter 'AdvancedHunting_*.json' -File | Where-Object { Test-IsLegacyAdvancedHuntingSnapshotFileName -Name $_.Name } | Sort-Object Name)

    if (Test-Path -Path $currentPath) {
        foreach ($record in Read-AdvancedHuntingRecordsFromFile -Path $currentPath) {
            $storeKey = Get-AdvancedHuntingStoreKey -Record $record
            if ($storeKey) {
                $currentRecords[$storeKey] = $record
            }
        }
    }
    elseif (Test-Path -Path $legacyCurrentPath) {
        foreach ($record in Read-AdvancedHuntingRecordsFromFile -Path $legacyCurrentPath) {
            $storeKey = Get-AdvancedHuntingStoreKey -Record $record
            if ($storeKey) {
                $currentRecords[$storeKey] = $record
            }
        }
        $migratedLegacy = $true
    }

    if ($legacyFiles.Count -gt 0) {
        foreach ($file in $legacyFiles) {
            $fallbackDate = [regex]::Match($file.Name, '\d{4}-\d{2}-\d{2}').Value
            foreach ($record in Read-AdvancedHuntingRecordsFromFile -Path $file.FullName) {
                $storeKey = Get-AdvancedHuntingStoreKey -Record $record
                if (-not $storeKey) { continue }

                $incomingKey = Get-AdvancedHuntingLastModifiedKey -LastModifiedTime $record.PSObject.Properties['LastModifiedTime']?.Value -FallbackDate $fallbackDate
                $existing = $currentRecords[$storeKey]

                if ($null -eq $existing) {
                    $currentRecords[$storeKey] = $record
                    $migratedLegacy = $true
                    continue
                }

                $existingKey = Get-AdvancedHuntingLastModifiedKey -LastModifiedTime $existing.PSObject.Properties['LastModifiedTime']?.Value -FallbackDate ''
                if ([string]::CompareOrdinal($incomingKey, $existingKey) -gt 0) {
                    $currentRecords[$storeKey] = $record
                    $migratedLegacy = $true
                }
            }
        }

        if ($migratedLegacy) {
            $stageRoot = Join-Path $Path ('.advancedhunting-store-staging-' + [guid]::NewGuid().ToString('N'))
            [void](New-Item -Path $stageRoot -ItemType Directory -Force)
            try {
                $stagedCurrentPath = Join-Path $stageRoot (Split-Path -Leaf $currentPath)
                Write-NdjsonRecordsFile -Path $stagedCurrentPath -Records $currentRecords.Values
                $removePaths = if ($RemoveLegacyFiles -and $currentRecords.Count -gt 0) {
                    @($legacyFiles.FullName) + @(
                        if (Test-Path -Path $legacyCurrentPath) { $legacyCurrentPath }
                    )
                }
                else {
                    @()
                }

                Publish-StoreFilesTransactional -BasePath $Path -StoreName 'advancedhunting' -Files @([PSCustomObject]@{
                    StagePath = $stagedCurrentPath
                    TargetPath = $currentPath
                }) -RemovePaths $removePaths
            }
            finally {
                if (Test-Path -Path $stageRoot) {
                    Remove-Item -Path $stageRoot -Recurse -Force -ErrorAction SilentlyContinue
                }
            }
        }
    }

    return @{
        CurrentPath    = $currentPath
        CurrentRecords = $currentRecords
        MigratedLegacy = $migratedLegacy
    }
}


# Shared MDE export helpers used by local export, generator refresh, and the Azure runbook.

function Get-MdeAccessToken {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$AccessToken,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$TenantId,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$AppId,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $AppSecret,

        [Parameter(Mandatory = $false)]
        [string]$ResourceAppIdUri = 'https://api.securitycenter.microsoft.com',

        [Parameter(Mandatory = $false)]
        [switch]$UseEnvironmentFallback,

        [Parameter(Mandatory = $false)]
        [switch]$UseAzureCliFallback,

        [Parameter(Mandatory = $false)]
        [switch]$WriteStatus
    )

    if (-not [string]::IsNullOrWhiteSpace($AccessToken)) {
        if ($WriteStatus) {
            Write-Host 'Using provided Microsoft Defender for Endpoint access token' -ForegroundColor Cyan
        }

        return $AccessToken.Trim()
    }

    $resolvedTenantId = $TenantId
    $resolvedAppId = $AppId
    $resolvedSecret = $AppSecret

    if ($UseEnvironmentFallback) {
        $environmentAccessToken = $env:DEFENDER_ACCESS_TOKEN
        if (-not [string]::IsNullOrWhiteSpace($environmentAccessToken)) {
            return $environmentAccessToken.Trim()
        }

        if ([string]::IsNullOrWhiteSpace($resolvedTenantId)) {
            $resolvedTenantId = $env:DEFENDER_TENANT_ID
        }
        if ([string]::IsNullOrWhiteSpace($resolvedAppId)) {
            $resolvedAppId = $env:DEFENDER_APP_ID
        }
        if ($null -eq $resolvedSecret -or [string]::IsNullOrWhiteSpace([string]$resolvedSecret)) {
            $resolvedSecret = $env:DEFENDER_APP_SECRET
        }
    }

    $resolvedSecretText = ''
    if ($resolvedSecret -is [System.Security.SecureString]) {
        $resolvedSecretText = [System.Net.NetworkCredential]::new('', [System.Security.SecureString]$resolvedSecret).Password
    }
    elseif ($null -ne $resolvedSecret) {
        $resolvedSecretText = [string]$resolvedSecret
    }

    if (
        -not [string]::IsNullOrWhiteSpace($resolvedTenantId) -and
        -not [string]::IsNullOrWhiteSpace($resolvedAppId) -and
        -not [string]::IsNullOrWhiteSpace($resolvedSecretText)
    ) {
        if ($WriteStatus) {
            Write-Host 'Authenticating to Microsoft Defender for Endpoint...' -ForegroundColor Cyan
        }

        $oAuthUri = "https://login.microsoftonline.com/$resolvedTenantId/oauth2/token"
        $authBody = [ordered]@{
            resource = $ResourceAppIdUri
            client_id = $resolvedAppId
            client_secret = $resolvedSecretText
            grant_type = 'client_credentials'
        }

        try {
            $response = Invoke-RestMethod -Method Post -Uri $oAuthUri -Body $authBody -ErrorAction Stop
            if ($WriteStatus) {
                Write-Host '  Authentication successful' -ForegroundColor Green
            }

            return [string]$response.access_token
        }
        catch {
            throw "Failed to authenticate to Microsoft Defender for Endpoint: $_"
        }
    }

    if ($UseAzureCliFallback) {
        $azCommand = Get-Command -Name 'az' -CommandType Application -ErrorAction SilentlyContinue
        if ($null -ne $azCommand) {
            try {
                $azAccessToken = [string](& $azCommand.Source 'account' 'get-access-token' '--resource' $ResourceAppIdUri '--query' 'accessToken' '-o' 'tsv')
                if (-not [string]::IsNullOrWhiteSpace($azAccessToken)) {
                    return $azAccessToken.Trim()
                }
            }
            catch {
                Write-Verbose "Azure CLI token acquisition failed: $_"
            }
        }
    }

    if ($UseEnvironmentFallback -or $UseAzureCliFallback) {
        throw "No Defender API token source available. Provide -AccessToken, set DEFENDER_ACCESS_TOKEN, set DEFENDER_TENANT_ID/DEFENDER_APP_ID/DEFENDER_APP_SECRET, or sign in with 'az login'."
    }

    throw 'No Defender API token source available. Provide -AccessToken or -TenantId/-AppId/-AppSecret.'
}

function Get-MdeHeaderCollection {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$AccessToken
    )

    return @{
        'Content-Type'  = 'application/json'
        'Accept'        = 'application/json'
        'Authorization' = "Bearer $AccessToken"
    }
}

function Resolve-UriQueryParameterValue {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Uri,

        [Parameter(Mandatory = $true)]
        [string]$Name,

        [Parameter(Mandatory = $true)]
        [string]$Value
    )

    $absoluteUri = $null
    if (-not [System.Uri]::TryCreate($Uri, [System.UriKind]::Absolute, [ref]$absoluteUri)) {
        return $Uri
    }

    $uriBuilder = [System.UriBuilder]::new($absoluteUri)
    $queryEntries = [System.Collections.Generic.List[string]]::new()
    foreach ($queryEntry in @($uriBuilder.Query.TrimStart('?').Split('&', [System.StringSplitOptions]::RemoveEmptyEntries))) {
        $key = [System.Uri]::UnescapeDataString(($queryEntry.Split('=', 2))[0])
        if ($key -ieq $Name) {
            continue
        }

        $queryEntries.Add($queryEntry)
    }

    $queryEntries.Add(("{0}={1}" -f [System.Uri]::EscapeDataString($Name), [System.Uri]::EscapeDataString($Value)))
    $uriBuilder.Query = [string]::Join('&', $queryEntries)
    return $uriBuilder.Uri.AbsoluteUri
}

function Get-MdeBulkVulnerabilityExportRequestUri {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ExportUrl,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 6)]
        [int]$SasValidHours = 6
    )

    return (Resolve-UriQueryParameterValue -Uri $ExportUrl -Name 'sasValidHours' -Value ([string]$SasValidHours))
}

function Get-VulnSnapshotStagingPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$OutputFile
    )

    return (Join-Path -Path (Split-Path -Path $OutputFile -Parent) -ChildPath ('.' + (Split-Path -Path $OutputFile -Leaf) + '.partial'))
}

function Invoke-MdeBulkVulnerabilitySnapshotDownload {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $true)]
        [string]$ExportUrl
    )

    $emptyDownloadMaxAttempts = 4
    $emptyDownloadInitialDelayMs = 2000
    $emptyDownloadBackoffMultiplier = 2.0

    $resolvedExportUrl = Get-MdeBulkVulnerabilityExportRequestUri -ExportUrl $ExportUrl
    $response = Invoke-RestMethodWithRetry -Uri $resolvedExportUrl -Headers $Headers -Method Get -MaxRetries 4 -InitialDelayMs 5000 -TimeoutSec 600 -RetryTransientTransportFailures
    $exportFiles = @($response.exportFiles)
    if ($exportFiles.Count -eq 0) {
        throw 'Bulk vulnerability export returned no files.'
    }

    $downloadedFiles = [System.Collections.Generic.List[string]]::new()
    $partIndexBySnapshotKey = @{}
    foreach ($fileUrl in $exportFiles) {
        if ($fileUrl -match '/collection/([^/?]+)/.*%3DgroupId%3D([^&%? ]+)') {
            $date = $Matches[1]
            $groupId = [System.Uri]::UnescapeDataString($Matches[2])
        }
        elseif ($fileUrl -match '/flat-va/([^/?]+)/[^/?]+/json/_RbacGroupId(?:%3D|=)([^/?&]+)') {
            $date = $Matches[1]
            $groupId = [System.Uri]::UnescapeDataString($Matches[2])
        }
        else {
            throw "Unexpected export URL format. Cannot extract date and groupId from: $(Get-SanitizedUriForLog -Uri $fileUrl)"
        }

        $snapshotKey = "${groupId}|${date}"
        $partIndex = if ($partIndexBySnapshotKey.ContainsKey($snapshotKey)) {
            [int]$partIndexBySnapshotKey[$snapshotKey]
        }
        else {
            0
        }
        $partIndexBySnapshotKey[$snapshotKey] = ($partIndex + 1)

        $outputFile = Join-Path $OutputPath ("VulnExport_{0}_{1}_part_{2}.json.gz" -f $groupId, $date, $partIndex)
        $stagingOutputFile = Get-VulnSnapshotStagingPath -OutputFile $outputFile
        $downloadAttempt = 0
        $emptyDownloadDelayMs = $emptyDownloadInitialDelayMs

        while ($true) {
            if (Test-Path -LiteralPath $stagingOutputFile -PathType Leaf) {
                Remove-Item -LiteralPath $stagingOutputFile -Force -ErrorAction SilentlyContinue
            }

            try {
                $downloadAttempt++
                Invoke-WebRequestWithRetry -Uri $fileUrl -OutFile $stagingOutputFile -MaxRetries 6 -InitialDelayMs 2000 -TimeoutSec 1800 -RetryTransientTransportFailures
                $stagingFile = Get-Item -LiteralPath $stagingOutputFile -Force -ErrorAction Stop
            }
            catch {
                if (Test-Path -LiteralPath $stagingOutputFile -PathType Leaf) {
                    Remove-Item -LiteralPath $stagingOutputFile -Force -ErrorAction SilentlyContinue
                }

                throw
            }

            if ($stagingFile.Length -gt 0) {
                try {
                    if (Test-Path -LiteralPath $outputFile -PathType Leaf) {
                        Remove-Item -LiteralPath $outputFile -Force -ErrorAction SilentlyContinue
                    }

                    [System.IO.File]::Move($stagingOutputFile, $outputFile)
                }
                catch {
                    if (Test-Path -LiteralPath $stagingOutputFile -PathType Leaf) {
                        Remove-Item -LiteralPath $stagingOutputFile -Force -ErrorAction SilentlyContinue
                    }

                    throw
                }

                break
            }

            if (Test-Path -LiteralPath $stagingOutputFile -PathType Leaf) {
                Remove-Item -LiteralPath $stagingOutputFile -Force -ErrorAction SilentlyContinue
            }

            if ($downloadAttempt -ge $emptyDownloadMaxAttempts) {
                throw "Downloaded file is empty: $(Get-SanitizedUriForLog -Uri $fileUrl)"
            }

            Write-Warning ("Downloaded file was empty for {0} (attempt {1}/{2}). Retrying in {3}s..." -f (Get-SanitizedUriForLog -Uri $fileUrl), $downloadAttempt, $emptyDownloadMaxAttempts, [math]::Round($emptyDownloadDelayMs / 1000, 1))
            Start-Sleep -Milliseconds $emptyDownloadDelayMs
            $emptyDownloadDelayMs = [int]($emptyDownloadDelayMs * $emptyDownloadBackoffMultiplier)
        }

        $downloadedFiles.Add($outputFile)
    }

    return [PSCustomObject]@{
        ExportFileCount = $exportFiles.Count
        DownloadedFiles = @($downloadedFiles)
    }
}

function Export-MdeBulkVulnerabilityData {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $true)]
        [string]$ExportUrl
    )

    Write-Host 'Exporting vulnerability data from MDE API...' -ForegroundColor Cyan
    $result = Invoke-MdeBulkVulnerabilitySnapshotDownload -Headers $Headers -OutputPath $OutputPath -ExportUrl $ExportUrl
    foreach ($downloadedFile in $result.DownloadedFiles) {
        Write-Host "  Downloading $(Split-Path -Leaf $downloadedFile)" -ForegroundColor Gray
    }

    return @($result.DownloadedFiles)
}

function Invoke-MdeAdvancedHuntingStoreRefresh {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $true)]
        [string]$QueryUrl
    )

    function Invoke-MdeAdvancedHuntingQuery {
        [CmdletBinding()]
        [OutputType([object[]])]
        param(
            [Parameter(Mandatory = $true)]
            [hashtable]$RequestHeaders,

            [Parameter(Mandatory = $true)]
            [string]$RequestUrl,

            [Parameter(Mandatory = $true)]
            [string]$Query,

            [Parameter(Mandatory = $true)]
            [string]$Label
        )

        Write-Information ("  Running Advanced Hunting query: {0}" -f $Label) -InformationAction Continue
        $body = @{ Query = $Query } | ConvertTo-Json
        $response = Invoke-RestMethodWithRetry -Uri $RequestUrl -Headers $RequestHeaders -Method Post -Body $body
        if ($null -eq $response -or $null -eq $response.Results) {
            return @()
        }

        return @($response.Results)
    }

    function Set-AdvancedHuntingResultRecordType {
        [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Internal helper only annotates in-memory Advanced Hunting query results with a record-type marker.')]
        [CmdletBinding()]
        param(
            [Parameter(Mandatory = $true)]
            [object[]]$Records,

            [Parameter(Mandatory = $true)]
            [string]$RecordType
        )

        foreach ($record in @($Records)) {
            if ($null -eq $record) {
                continue
            }

            if ($record.PSObject.Properties['RecordType']) {
                $record.RecordType = $RecordType
            }
            else {
                Add-Member -InputObject $record -NotePropertyName RecordType -NotePropertyValue $RecordType -Force
            }
        }
    }

    $cveQuery = @"
let RelevantCves =
    DeviceTvmSoftwareVulnerabilities
    | where isnotempty(CveId)
    | distinct CveId;
RelevantCves
| join kind=leftouter (
    DeviceTvmSoftwareVulnerabilitiesKB
    | where isnotempty(CveId)
    | project CveId, PublishedDate, VulnerabilityDescription, EpssScore, AffectedSoftware, IsExploitAvailable, LastModifiedTime
) on CveId
| summarize arg_max(LastModifiedTime, PublishedDate, VulnerabilityDescription, EpssScore, AffectedSoftware, IsExploitAvailable) by CveId
| project CveId,
    PublishedDate = format_datetime(PublishedDate, 'yyyy-MM-dd'),
    VulnerabilityDescription,
    EpssScore,
    AffectedSoftware,
    IsExploitAvailable,
    LastModifiedTime
"@

    $deviceUsersQuery = @"
DeviceInfo
| where OnboardingStatus == 'Onboarded'
| where isnotempty(DeviceId) and isnotempty(LoggedOnUsers)
| project DeviceId, Timestamp, LoggedOnUsers
| summarize arg_max(Timestamp, LoggedOnUsers) by DeviceId
| project DeviceId, LoggedOnUsers, LastModifiedTime = Timestamp
"@

    $inventoryQuery = @"
let RelevantSoftware =
    DeviceTvmSoftwareVulnerabilities
    | where isnotempty(DeviceId) and isnotempty(SoftwareName)
    | summarize by DeviceId, SoftwareVendor, SoftwareName, SoftwareVersion;
RelevantSoftware
| join kind=leftouter (
    DeviceTvmSoftwareInventory
    | where isnotempty(DeviceId) and isnotempty(SoftwareName)
    | project DeviceId, SoftwareVendor, SoftwareName, SoftwareVersion, ProductCodeCpe, EndOfSupportStatus, EndOfSupportDate
    | extend InventorySignalCount =
        iff(isnotempty(ProductCodeCpe), 1, 0) +
        iff(isnotempty(EndOfSupportStatus), 1, 0) +
        iff(isnotempty(EndOfSupportDate), 1, 0)
) on DeviceId, SoftwareVendor, SoftwareName, SoftwareVersion
| summarize arg_max(InventorySignalCount, ProductCodeCpe, EndOfSupportStatus, EndOfSupportDate) by DeviceId, SoftwareVendor, SoftwareName, SoftwareVersion
| project DeviceId,
    SoftwareVendor,
    SoftwareName,
    SoftwareVersion,
    ProductCodeCpe,
    EndOfSupportStatus,
    EndOfSupportDate = format_datetime(EndOfSupportDate, 'yyyy-MM-dd')
"@

    $cveResults = @(Invoke-MdeAdvancedHuntingQuery -RequestHeaders $Headers -RequestUrl $QueryUrl -Query $cveQuery -Label 'cve-enrichment')
    $deviceUserResults = @(Invoke-MdeAdvancedHuntingQuery -RequestHeaders $Headers -RequestUrl $QueryUrl -Query $deviceUsersQuery -Label 'device-users')
    $inventoryResults = @(Invoke-MdeAdvancedHuntingQuery -RequestHeaders $Headers -RequestUrl $QueryUrl -Query $inventoryQuery -Label 'software-inventory')

    Set-AdvancedHuntingResultRecordType -Records $cveResults -RecordType 'Cve'
    Set-AdvancedHuntingResultRecordType -Records $deviceUserResults -RecordType 'DeviceUsers'
    Set-AdvancedHuntingResultRecordType -Records $inventoryResults -RecordType 'Inventory'

    if ($cveResults.Count -eq 0 -and $deviceUserResults.Count -eq 0 -and $inventoryResults.Count -eq 0) {
        return [PSCustomObject]@{
            Success = $false
            RecordCount = 0
            OutputFile = $null
            MigratedLegacy = $false
        }
    }

    return Invoke-WithStoreLock -BasePath $OutputPath -StoreName 'advancedhunting' -ScriptBlock {
        Restore-StoreTransaction -BasePath $OutputPath -StoreName 'advancedhunting'

        $store = Initialize-AdvancedHuntingStore -Path $OutputPath -RemoveLegacyFiles

        foreach ($existingKey in @($store.CurrentRecords.Keys)) {
            $existingRecord = $store.CurrentRecords[$existingKey]
            $recordType = Get-AdvancedHuntingRecordType -Record $existingRecord
            if ($recordType -eq 'DeviceUsers' -or $recordType -eq 'Inventory') {
                [void]$store.CurrentRecords.Remove($existingKey)
            }
        }

        foreach ($result in $cveResults) {
            $storeKey = Get-AdvancedHuntingStoreKey -Record $result
            if ($storeKey) {
                $store.CurrentRecords[$storeKey] = $result
            }
        }

        foreach ($result in $deviceUserResults) {
            $storeKey = Get-AdvancedHuntingStoreKey -Record $result
            if ($storeKey) {
                $store.CurrentRecords[$storeKey] = $result
            }
        }

        foreach ($result in $inventoryResults) {
            $storeKey = Get-AdvancedHuntingStoreKey -Record $result
            if ($storeKey) {
                $store.CurrentRecords[$storeKey] = $result
            }
        }

        $stageRoot = Join-Path $OutputPath ('.advancedhunting-store-staging-' + [guid]::NewGuid().ToString('N'))
        [void](New-Item -Path $stageRoot -ItemType Directory -Force)

        try {
            $stagedCurrentPath = Join-Path $stageRoot (Split-Path -Leaf $store.CurrentPath)
            Write-NdjsonRecordsFile -Path $stagedCurrentPath -Records $store.CurrentRecords.Values
            Write-Information ("  Advanced Hunting store publish: {0} record(s)" -f $store.CurrentRecords.Count) -InformationAction Continue

            Publish-StoreFilesTransactional -BasePath $OutputPath -StoreName 'advancedhunting' -Files @([PSCustomObject]@{
                StagePath = $stagedCurrentPath
                TargetPath = $store.CurrentPath
            })

            return [PSCustomObject]@{
                Success = $true
                RecordCount = ($cveResults.Count + $deviceUserResults.Count + $inventoryResults.Count)
                OutputFile = $store.CurrentPath
                MigratedLegacy = $store.MigratedLegacy
            }
        }
        finally {
            if (Test-Path -Path $stageRoot) {
                Remove-Item -Path $stageRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }
}

function Export-MdeAdvancedHuntingData {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $true)]
        [string]$QueryUrl
    )

    Write-Host 'Exporting Advanced Hunting data...' -ForegroundColor Cyan
    Write-Host '  Running Advanced Hunting query...' -ForegroundColor Gray
    $result = Invoke-MdeAdvancedHuntingStoreRefresh -Headers $Headers -OutputPath $OutputPath -QueryUrl $QueryUrl

    if ($result.Success) {
        Write-Host "  Retrieved $($result.RecordCount) records from Advanced Hunting" -ForegroundColor Green
        if ($result.MigratedLegacy) {
            Write-Host '  Migrated legacy Advanced Hunting snapshots to current cache' -ForegroundColor Green
        }
        Write-Host "  Saved to: $($result.OutputFile)" -ForegroundColor Green
        return $result
    }

    Write-Warning 'Advanced Hunting query returned no results'
    return $result
}

function Get-MdeMachineRefreshPublishPlan {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string]$BaseApiUrl,

        [Parameter(Mandatory = $true)]
        [string]$ObservedOn,

        [Parameter(Mandatory = $true)]
        [hashtable]$CurrentRecords,

        [Parameter(Mandatory = $true)]
        [string]$StagedCurrentPath
    )

    $url = "$BaseApiUrl/api/machines?`$filter=onboardingStatus eq 'Onboarded'"
    $pageCount = 0
    $machineCount = 0
    $changeCount = 0
    $seenMachineIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $currentFileStream = $null
    $currentGzipStream = $null
    $currentWriter = $null
    $currentJsonWriter = $null
    $stagedHistoryPath = $null
    $historyTargetPath = $null
    $historyFileStream = $null
    $historyGzipStream = $null
    $historyWriter = $null
    $historyJsonWriter = $null

    try {
        $currentFileStream = [System.IO.File]::Create($StagedCurrentPath)
        $currentGzipStream = [System.IO.Compression.GZipStream]::new($currentFileStream, [System.IO.Compression.CompressionMode]::Compress)
        $currentWriter = [System.IO.StreamWriter]::new($currentGzipStream, [System.Text.UTF8Encoding]::new($false))
        $currentJsonWriter = [Newtonsoft.Json.JsonTextWriter]::new($currentWriter)
        $currentJsonWriter.Formatting = [Newtonsoft.Json.Formatting]::None

        do {
            $pageCount++
            $response = Invoke-RestMethodWithRetry -Uri $url -Headers $Headers -Method Get

            if ($response.value) {
                foreach ($machine in $response.value) {
                    $snapshot = New-MachineSnapshotRecord -Machine $machine -ObservedOn $ObservedOn
                    $snapshotId = [string]$snapshot.id
                    if ([string]::IsNullOrWhiteSpace($snapshotId)) {
                        continue
                    }

                    if (-not $seenMachineIds.Add($snapshotId)) {
                        continue
                    }

                    Write-JsonValueToWriter -Writer $currentJsonWriter -Value $snapshot
                    $currentJsonWriter.Flush()
                    $currentWriter.WriteLine()
                    $machineCount++

                    $existing = $CurrentRecords[$snapshotId]
                    if (($null -eq $existing) -or ($existing.stateHash -ne $snapshot.stateHash)) {
                        if ($null -eq $historyJsonWriter) {
                            $historyFileName = New-MachineHistorySegmentFileName
                            $stageDirectory = Split-Path -Path $StagedCurrentPath -Parent
                            $stagedHistoryPath = Join-Path $stageDirectory ('.' + $historyFileName)
                            $historyTargetPath = Join-Path $stageDirectory $historyFileName
                            $historyFileStream = [System.IO.File]::Create($stagedHistoryPath)
                            $historyGzipStream = [System.IO.Compression.GZipStream]::new($historyFileStream, [System.IO.Compression.CompressionMode]::Compress)
                            $historyWriter = [System.IO.StreamWriter]::new($historyGzipStream, [System.Text.UTF8Encoding]::new($false))
                            $historyJsonWriter = [Newtonsoft.Json.JsonTextWriter]::new($historyWriter)
                            $historyJsonWriter.Formatting = [Newtonsoft.Json.Formatting]::None
                        }

                        Write-JsonValueToWriter -Writer $historyJsonWriter -Value $snapshot
                        $historyJsonWriter.Flush()
                        $historyWriter.WriteLine()
                        $changeCount++
                    }

                    [void]$CurrentRecords.Remove($snapshotId)
                }
            }

            $url = if ($response.PSObject.Properties['@odata.nextLink']) {
                $response.'@odata.nextLink'
            }
            else {
                $null
            }
            $response = $null
        } while ($url)

        foreach ($existingId in @($CurrentRecords.Keys)) {
            $removalRecord = New-MachineRemovalRecord -MachineId $existingId -ObservedOn $ObservedOn

            if ($null -eq $historyJsonWriter) {
                $historyFileName = New-MachineHistorySegmentFileName
                $stageDirectory = Split-Path -Path $StagedCurrentPath -Parent
                $stagedHistoryPath = Join-Path $stageDirectory ('.' + $historyFileName)
                $historyTargetPath = Join-Path $stageDirectory $historyFileName
                $historyFileStream = [System.IO.File]::Create($stagedHistoryPath)
                $historyGzipStream = [System.IO.Compression.GZipStream]::new($historyFileStream, [System.IO.Compression.CompressionMode]::Compress)
                $historyWriter = [System.IO.StreamWriter]::new($historyGzipStream, [System.Text.UTF8Encoding]::new($false))
                $historyJsonWriter = [Newtonsoft.Json.JsonTextWriter]::new($historyWriter)
                $historyJsonWriter.Formatting = [Newtonsoft.Json.Formatting]::None
            }

            Write-JsonValueToWriter -Writer $historyJsonWriter -Value $removalRecord
            $historyJsonWriter.Flush()
            $historyWriter.WriteLine()
            $changeCount++
        }
    }
    finally {
        if ($currentJsonWriter) { $currentJsonWriter.Close() }
        elseif ($currentWriter) { $currentWriter.Dispose() }
        elseif ($currentGzipStream) { $currentGzipStream.Dispose() }
        elseif ($currentFileStream) { $currentFileStream.Dispose() }

        if ($historyJsonWriter) { $historyJsonWriter.Close() }
        elseif ($historyWriter) { $historyWriter.Dispose() }
        elseif ($historyGzipStream) { $historyGzipStream.Dispose() }
        elseif ($historyFileStream) { $historyFileStream.Dispose() }
    }

    return [PSCustomObject]@{
        ChangeCount = $changeCount
        MachineCount = $machineCount
        PageCount = $pageCount
        StagedCurrentPath = $StagedCurrentPath
        StagedHistoryPath = $stagedHistoryPath
        HistoryTargetPath = $historyTargetPath
    }
}

function Get-MachineStoreRefreshPlan {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$CurrentRecords,

        [Parameter(Mandatory = $true)]
        [hashtable]$FetchedSnapshotsById,

        [Parameter(Mandatory = $true)]
        [string]$ObservedOn
    )

    $changeRecords = [System.Collections.Generic.List[object]]::new()
    $nextCurrentRecords = $FetchedSnapshotsById

    foreach ($snapshot in $FetchedSnapshotsById.Values) {
        $existing = $CurrentRecords[$snapshot.id]
        if (($null -eq $existing) -or ($existing.stateHash -ne $snapshot.stateHash)) {
            $changeRecords.Add($snapshot)
        }
    }

    foreach ($existingId in @($CurrentRecords.Keys)) {
        if (-not $nextCurrentRecords.ContainsKey($existingId)) {
            $changeRecords.Add((New-MachineRemovalRecord -MachineId $existingId -ObservedOn $ObservedOn))
        }
    }

    return [PSCustomObject]@{
        ChangeRecords = $changeRecords
        NextCurrentRecords = $nextCurrentRecords
        MachineCount = $FetchedSnapshotsById.Count
    }
}

function Publish-MachineStoreState {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $true)]
        [hashtable]$Store,

        [Parameter(Mandatory = $true)]
        [int]$ChangeCount,

        [Parameter(Mandatory = $true)]
        [string]$StagedCurrentPath,

        [Parameter(Mandatory = $true)]
        [int]$CurrentRecordCount,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [string]$StagedHistoryPath,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [string]$HistoryTargetPath
    )

    $stageRoot = Join-Path $OutputPath ('.machine-store-staging-' + [guid]::NewGuid().ToString('N'))
    [void](New-Item -Path $stageRoot -ItemType Directory -Force)

    try {
        $historyFileCount = if ([string]::IsNullOrWhiteSpace($HistoryTargetPath)) { 0 } else { 1 }
        Write-Information ("  Machine store publish: {0} current record(s), {1} staged history file(s), {2} change record(s)" -f $CurrentRecordCount, $historyFileCount, $ChangeCount) -InformationAction Continue

        $filesToPublish = [System.Collections.Generic.List[object]]::new()
        $filesToPublish.Add([PSCustomObject]@{
            StagePath = $StagedCurrentPath
            TargetPath = $Store.CurrentPath
        })

        $outputFiles = [System.Collections.Generic.List[string]]::new()
        $outputFiles.Add($Store.CurrentPath)

        $publishedHistoryNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($historyFile in Get-MachineHistoryQuarterlyFiles -BasePath $OutputPath) {
            [void]$publishedHistoryNames.Add($historyFile.Name)
        }

        if (-not [string]::IsNullOrWhiteSpace($StagedHistoryPath) -and -not [string]::IsNullOrWhiteSpace($HistoryTargetPath)) {
            $filesToPublish.Add([PSCustomObject]@{
                StagePath = $StagedHistoryPath
                TargetPath = $HistoryTargetPath
            })

            $historyName = Split-Path -Leaf $HistoryTargetPath
            [void]$publishedHistoryNames.Add($historyName)
            $outputFiles.Add($HistoryTargetPath)
        }

        $removePaths = @(Get-MachineHistoryRemovePaths -BasePath $OutputPath -PublishedHistoryNames $publishedHistoryNames)
        Publish-StoreFilesTransactional -BasePath $OutputPath -StoreName 'machines' -Files @($filesToPublish) -RemovePaths $removePaths

        return [PSCustomObject]@{
            Success = $true
            ChangeCount = $ChangeCount
            OutputFiles = @($outputFiles)
            MigratedLegacy = $Store.MigratedLegacy
        }
    }
    finally {
        if (Test-Path -Path $stageRoot) {
            Remove-Item -Path $stageRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}

function Invoke-MdeMachineStoreRefresh {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $true)]
        [string]$BaseApiUrl
    )

    $observedOn = Get-Date -Format 'yyyy-MM-dd'
    $resolvedHeaders = $Headers
    $resolvedOutputPath = $OutputPath
    $resolvedBaseApiUrl = $BaseApiUrl
    $resolvedObservedOn = $observedOn

    return Invoke-WithStoreLock -BasePath $resolvedOutputPath -StoreName 'machines' -ScriptBlock {
        Restore-StoreTransaction -BasePath $resolvedOutputPath -StoreName 'machines'

        $store = Initialize-MachineHistoryStore -Path $resolvedOutputPath -RemoveLegacyFiles
        $stagedCurrentPath = Join-Path $resolvedOutputPath ('.machine-current-staged-' + [guid]::NewGuid().ToString('N') + '.json.gz')
        $refreshPlan = Get-MdeMachineRefreshPublishPlan -Headers $resolvedHeaders -BaseApiUrl $resolvedBaseApiUrl -ObservedOn $resolvedObservedOn -CurrentRecords $store.CurrentRecords -StagedCurrentPath $stagedCurrentPath
        $store.CurrentRecords = $null

        if (Get-Command -Name Invoke-FullGarbageCollection -ErrorAction SilentlyContinue) {
            Invoke-FullGarbageCollection
        }

        try {
            $publishResult = Publish-MachineStoreState -OutputPath $resolvedOutputPath -Store $store -ChangeCount $refreshPlan.ChangeCount -StagedCurrentPath $refreshPlan.StagedCurrentPath -CurrentRecordCount $refreshPlan.MachineCount -StagedHistoryPath $refreshPlan.StagedHistoryPath -HistoryTargetPath $refreshPlan.HistoryTargetPath
            return [PSCustomObject]@{
                Success = $true
                MachineCount = $refreshPlan.MachineCount
                ChangeCount = $publishResult.ChangeCount
                PageCount = $refreshPlan.PageCount
                OutputFiles = @($publishResult.OutputFiles)
                MigratedLegacy = $publishResult.MigratedLegacy
            }
        }
        finally {
            if (Test-Path -LiteralPath $stagedCurrentPath -PathType Leaf) {
                Remove-Item -LiteralPath $stagedCurrentPath -Force -ErrorAction SilentlyContinue
            }
            if (-not [string]::IsNullOrWhiteSpace($refreshPlan.StagedHistoryPath) -and (Test-Path -LiteralPath $refreshPlan.StagedHistoryPath -PathType Leaf)) {
                Remove-Item -LiteralPath $refreshPlan.StagedHistoryPath -Force -ErrorAction SilentlyContinue
            }
        }
    }
}

function Export-MdeMachineData {
    [CmdletBinding(DefaultParameterSetName = 'Headers')]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true, ParameterSetName = 'Headers')]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true, ParameterSetName = 'AccessToken')]
        [string]$AccessToken,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $false)]
        [string]$BaseApiUrl = 'https://api.securitycenter.microsoft.com'
    )

    $resolvedHeaders = if ($PSCmdlet.ParameterSetName -eq 'AccessToken') {
        Get-MdeHeaderCollection -AccessToken $AccessToken
    }
    else {
        $Headers
    }

    Write-Host 'Exporting machine data from Defender API...' -ForegroundColor Cyan
    $result = Invoke-MdeMachineStoreRefresh -Headers $resolvedHeaders -OutputPath $OutputPath -BaseApiUrl $BaseApiUrl

    Write-Host "  Retrieved $($result.MachineCount) machines" -ForegroundColor Green
    Write-Host "  Machine state changes captured: $($result.ChangeCount)" -ForegroundColor Green
    if ($result.MigratedLegacy) {
        Write-Host '  Migrated legacy machine snapshots to current/history store' -ForegroundColor Green
    }
    $outputFiles = @($result.OutputFiles | ForEach-Object { Split-Path -Leaf $_ })
    Write-Host "  Saved to $($outputFiles -join ', ')" -ForegroundColor Green

    return $result
}

# Shared enrichment and source-row projection helpers used by dashboard generation
# and validation.

function Get-StringArray {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) { return @() }
    if ($Value -is [string]) {
        if ([string]::IsNullOrWhiteSpace($Value)) { return @() }
        return @($Value)
    }

    if ($Value -is [System.Collections.IEnumerable]) {
        $result = [System.Collections.Generic.List[string]]::new()
        foreach ($item in $Value) {
            if ($null -eq $item) { continue }
            $text = [string]$item
            if (-not [string]::IsNullOrWhiteSpace($text)) {
                $result.Add($text)
            }
        }
        return @($result)
    }

    return @([string]$Value)
}

function Get-NullableProjectionString {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return $null
    }

    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) {
        return $null
    }

    return $text
}

function Get-RecordPropertyValueIfPresent {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Record,

        [Parameter(Mandatory = $true)]
        [string]$PropertyName
    )

    if ($null -eq $Record) {
        return $null
    }

    if ($Record -is [System.Collections.IDictionary]) {
        if ($Record.Contains($PropertyName)) {
            return $Record[$PropertyName]
        }

        return $null
    }

    $property = $Record.PSObject.Properties[$PropertyName]
    if ($null -eq $property) {
        return $null
    }

    return $property.Value
}

function New-MachineInfoObject {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Machine
    )

    if ($null -eq $Machine) {
        return $null
    }

    $projection = Get-MachineProjection -Machine $Machine
    if ($null -eq $projection) {
        return $null
    }

    return $projection.MachineInfo
}

function Get-MachineProjection {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Machine
    )

    if ($null -eq $Machine) {
        return $null
    }

    $machineTuple = if ($Machine -is [System.Array]) {
        ConvertTo-NormalizationMachineTuple -Machine $Machine
    }
    else {
        $null
    }

    $getScalarValue = {
        param(
            [int]$TupleIndex,
            [string]$PropertyName
        )

        if ($machineTuple -and $machineTuple.Length -gt $TupleIndex) {
            return $machineTuple[$TupleIndex]
        }

        return $Machine.PSObject.Properties[$PropertyName]?.Value
    }

    $machineTags = if ($machineTuple -and $machineTuple.Length -ge 15) {
        @(Get-StringArray -Value $machineTuple[14])
    }
    elseif ($Machine.PSObject.Properties['machineTags']?.Value) {
        @(Get-StringArray -Value $Machine.PSObject.Properties['machineTags']?.Value)
    }
    else {
        @()
    }

    $lastSeen = & $getScalarValue 8 'lastSeen'
    $firstSeen = & $getScalarValue 9 'firstSeen'

    return [PSCustomObject]@{
        ComputerDnsName = Get-NullableProjectionString (& $getScalarValue 11 'computerDnsName')
        RbacGroupName = Get-NullableProjectionString (& $getScalarValue 12 'rbacGroupName')
        OSPlatform = Get-NullableProjectionString (& $getScalarValue 13 'osPlatform')
        OSVersion = Get-NullableProjectionString (& $getScalarValue 10 'osVersion')
        MachineTags = @($machineTags)
        MachineInfo = [PSCustomObject]@{
            ip = & $getScalarValue 0 'lastIpAddress'
            eip = & $getScalarValue 1 'lastExternalIpAddress'
            hs = & $getScalarValue 2 'healthStatus'
            rs = & $getScalarValue 3 'riskScore'
            el = & $getScalarValue 4 'exposureLevel'
            dv = & $getScalarValue 5 'deviceValue'
            mb = & $getScalarValue 6 'managedBy'
            aad = & $getScalarValue 7 'isAadJoined'
            ls = Convert-ToYmdDate -DateValue $lastSeen
            fs = Convert-ToYmdDate -DateValue $firstSeen
        }
    }
}

function Get-FilteredAffectedSoftware {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $AdvancedHuntingRecord,

        [Parameter(Mandatory = $true)]
        [System.Collections.Generic.HashSet[string]]$VendorSet
    )

    if ($null -eq $AdvancedHuntingRecord) {
        return $null
    }

    $affectedSoftwareSource = @(Get-StringArray -Value $AdvancedHuntingRecord.AffectedSoftware)
    if (@($affectedSoftwareSource).Count -eq 0) {
        return $null
    }

    $filtered = [System.Collections.Generic.List[string]]::new()
    foreach ($software in $affectedSoftwareSource) {
        $vendor = if ($software -match ':') { $software.Split(':', 2)[0] } else { $software }
        $vendorMatchKey = Get-VendorMatchKey -Vendor $vendor
        if (-not [string]::IsNullOrWhiteSpace($vendorMatchKey) -and $VendorSet.Contains($vendorMatchKey)) {
            $filtered.Add([string]$software)
        }
    }

    if (@($filtered).Count -eq 0) {
        return $null
    }

    return @($filtered)
}

function Get-SourceCveEnrichment {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$CveId,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $AdvancedHunting,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $NvdCveData,

        [Parameter(Mandatory = $true)]
        [System.Collections.Generic.HashSet[string]]$VendorSet
    )

    $ahRecord = if ($null -ne $AdvancedHunting) { $AdvancedHunting[$CveId] } else { $null }
    $nvdRecord = if ($null -ne $NvdCveData) { $NvdCveData[$CveId] } else { $null }
    $exploitAvailability = Get-RecordPropertyValueIfPresent -Record $ahRecord -PropertyName 'IsExploitAvailable'

    return [PSCustomObject]@{
        PublishedDate = if ($ahRecord -and $ahRecord.PublishedDate) { [string]$ahRecord.PublishedDate } elseif ($nvdRecord) { [string]$nvdRecord.PublishedDate } else { $null }
        VulnerabilityDescription = if ($ahRecord -and $ahRecord.VulnerabilityDescription) { [string]$ahRecord.VulnerabilityDescription } elseif ($nvdRecord) { [string]$nvdRecord.VulnerabilityDescription } else { $null }
        EpssScore = if ($ahRecord) { $ahRecord.EpssScore } else { $null }
        AffectedSoftware = Get-FilteredAffectedSoftware -AdvancedHuntingRecord $ahRecord -VendorSet $VendorSet
        IsExploitAvailable = $exploitAvailability
        NvdLastModifiedDate = if ($nvdRecord) { [string]$nvdRecord.LastModifiedDate } else { $null }
        NvdBaseScore = if ($nvdRecord) { $nvdRecord.BaseScore } else { $null }
        NvdBaseSeverity = if ($nvdRecord) { [string]$nvdRecord.BaseSeverity } else { $null }
        NvdVector = if ($nvdRecord) { [string]$nvdRecord.Vector } else { $null }
        NvdKevDate = if ($nvdRecord) { [string]$nvdRecord.CisaExploitAdd } else { $null }
        NvdActionDue = if ($nvdRecord) { [string]$nvdRecord.CisaActionDue } else { $null }
        NvdRequiredAction = if ($nvdRecord) { [string]$nvdRecord.CisaRequiredAction } else { $null }
        NvdWeaknesses = if ($nvdRecord -and $nvdRecord.Weaknesses) { @(Get-StringArray -Value $nvdRecord.Weaknesses) } else { $null }
    }
}

function Get-SourceInventoryEnrichment {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        $Record,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $AdvancedHuntingInventory
    )

    $emptyInventory = [PSCustomObject]@{
        ProductCodeCpe = $null
        EndOfSupportStatus = $null
        EndOfSupportDate = $null
    }
    if ($null -eq $AdvancedHuntingInventory) {
        return $emptyInventory
    }

    $inventoryKey = Get-AdvancedHuntingInventoryMatchKey `
        -DeviceId ([string](Get-VulnPropertyValue -InputObject $Record -Name 'DeviceId')) `
        -SoftwareVendor ([string](Get-VulnPropertyValue -InputObject $Record -Name 'SoftwareVendor')) `
        -SoftwareName ([string](Get-VulnPropertyValue -InputObject $Record -Name 'SoftwareName')) `
        -SoftwareVersion ([string](Get-VulnPropertyValue -InputObject $Record -Name 'SoftwareVersion'))
    if ([string]::IsNullOrWhiteSpace($inventoryKey)) {
        return $emptyInventory
    }

    $inventoryRecord = $AdvancedHuntingInventory[$inventoryKey]
    if ($null -eq $inventoryRecord) {
        return $emptyInventory
    }

    return [PSCustomObject]@{
        ProductCodeCpe = [string]$inventoryRecord.ProductCodeCpe
        EndOfSupportStatus = [string]$inventoryRecord.EndOfSupportStatus
        EndOfSupportDate = [string]$inventoryRecord.EndOfSupportDate
    }
}

# Shared enrichment readers used by dashboard generation, validation, and Azure
# packaging outputs.

function Resolve-AdvancedHuntingBundleSourceFileList {
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo[]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $currentPath = Get-AdvancedHuntingCurrentPath -BasePath $Path
    $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath

    if ((-not (Test-Path -LiteralPath $currentPath -PathType Leaf)) -and (Test-Path -LiteralPath $legacyCurrentPath -PathType Leaf)) {
        $currentPath = $legacyCurrentPath
    }

    if (Test-Path -LiteralPath $currentPath -PathType Leaf) {
        return @((Get-Item -LiteralPath $currentPath))
    }

    return @(Get-ChildItem -Path $Path -Filter 'AdvancedHunting_*.json' -File -ErrorAction SilentlyContinue |
        Where-Object { Test-IsLegacyAdvancedHuntingSnapshotFileName -Name $_.Name } |
        Sort-Object Name -Descending)
}

function ConvertTo-AdvancedHuntingBundleStringArray {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return ,([string[]]@())
    }

    if ($Value -is [string]) {
        if ([string]::IsNullOrWhiteSpace($Value)) {
            return ,([string[]]@())
        }

        return ,([string[]]@($Value))
    }

    if ($Value -is [string[]]) {
        $requiresFiltering = $false
        foreach ($text in $Value) {
            if ([string]::IsNullOrWhiteSpace($text)) {
                $requiresFiltering = $true
                break
            }
        }

        if (-not $requiresFiltering) {
            return ,$Value
        }

        $values = [System.Collections.Generic.List[string]]::new($Value.Length)
        foreach ($item in $Value) {
            $text = [string]$item
            if (-not [string]::IsNullOrWhiteSpace($text)) {
                $values.Add($text)
            }
        }

        return ,([string[]]$values.ToArray())
    }

    $values = $null
    if ($Value -is [System.Array]) {
        $values = [System.Collections.Generic.List[string]]::new($Value.Length)
    }
    elseif ($Value -is [System.Collections.ICollection]) {
        $values = [System.Collections.Generic.List[string]]::new($Value.Count)
    }
    else {
        $values = [System.Collections.Generic.List[string]]::new()
    }

    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        foreach ($item in $Value) {
            if ($null -eq $item) { continue }
            $text = [string]$item
            if (-not [string]::IsNullOrWhiteSpace($text)) {
                $values.Add($text)
            }
        }
    }
    else {
        $text = [string]$Value
        if (-not [string]::IsNullOrWhiteSpace($text)) {
            $values.Add($text)
        }
    }

    return ,([string[]]$values.ToArray())
}

function ConvertTo-AdvancedHuntingBundleDescriptionValue {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return $null
    }

    if ($Value -is [string]) {
        return $Value
    }

    $parts = ConvertTo-AdvancedHuntingBundleStringArray -Value $Value
    if ($parts.Count -eq 0) {
        return $null
    }

    return ($parts -join "`n")
}

function ConvertTo-AdvancedHuntingBundleNullableBoolean {
    [CmdletBinding()]
    [OutputType([Nullable[bool]])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return $null
    }

    if ($Value -is [bool]) {
        return $Value
    }

    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) {
        return $null
    }

    switch -Regex ($text.Trim().ToLowerInvariant()) {
        '^(true|1|yes)$' { return $true }
        '^(false|0|no)$' { return $false }
    }

    return $null
}

function Add-AdvancedHuntingBundleLoggedOnUserValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value,

        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [System.Collections.Generic.List[string]]$Values,

        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [System.Collections.Generic.HashSet[string]]$Seen
    )

    if ($null -eq $Value) {
        return
    }

    if ($Value -is [string]) {
        $text = $Value.Trim()
        if ([string]::IsNullOrWhiteSpace($text)) {
            return
        }

        if ((($text.StartsWith('[') -and $text.EndsWith(']')) -or ($text.StartsWith('{') -and $text.EndsWith('}')))) {
            try {
                $parsedValue = $text | ConvertFrom-Json -Depth 20
                Add-AdvancedHuntingBundleLoggedOnUserValue -Value $parsedValue -Values $Values -Seen $Seen
                return
            }
            catch {
                Write-Verbose ("Falling back to raw LoggedOnUsers text after JSON parse failed: {0}" -f $_.Exception.Message)
            }
        }

        if ($Seen.Add($text)) {
            $Values.Add($text)
        }
        return
    }

    if ($Value -is [pscustomobject] -or $Value -is [System.Collections.IDictionary]) {
        $propertyBag = $Value.PSObject.Properties
        $upn = [string]$propertyBag['UserPrincipalName']?.Value
        $domainName = [string]$propertyBag['DomainName']?.Value
        $accountName = [string]$propertyBag['AccountName']?.Value
        $userName = [string]$propertyBag['UserName']?.Value
        $displayName = [string]$propertyBag['Name']?.Value

        $resolvedName = $null
        if (-not [string]::IsNullOrWhiteSpace($upn)) {
            $resolvedName = $upn.Trim()
        }
        elseif (-not [string]::IsNullOrWhiteSpace($accountName)) {
            $resolvedName = if (-not [string]::IsNullOrWhiteSpace($domainName)) {
                $domainName.Trim() + '\' + $accountName.Trim()
            }
            else {
                $accountName.Trim()
            }
        }
        elseif (-not [string]::IsNullOrWhiteSpace($userName)) {
            $resolvedName = if (-not [string]::IsNullOrWhiteSpace($domainName)) {
                $domainName.Trim() + '\' + $userName.Trim()
            }
            else {
                $userName.Trim()
            }
        }
        elseif (-not [string]::IsNullOrWhiteSpace($displayName)) {
            $resolvedName = $displayName.Trim()
        }

        if (-not [string]::IsNullOrWhiteSpace($resolvedName)) {
            if ($Seen.Add($resolvedName)) {
                $Values.Add($resolvedName)
            }
            return
        }

        foreach ($property in $propertyBag) {
            Add-AdvancedHuntingBundleLoggedOnUserValue -Value $property.Value -Values $Values -Seen $Seen
        }
        return
    }

    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        foreach ($item in $Value) {
            Add-AdvancedHuntingBundleLoggedOnUserValue -Value $item -Values $Values -Seen $Seen
        }
        return
    }

    $fallbackText = [string]$Value
    if (-not [string]::IsNullOrWhiteSpace($fallbackText) -and $Seen.Add($fallbackText)) {
        $Values.Add($fallbackText)
    }
}

function ConvertTo-AdvancedHuntingBundleLoggedOnUserList {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    $values = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    Add-AdvancedHuntingBundleLoggedOnUserValue -Value $Value -Values $values -Seen $seen
    return ,([string[]]$values.ToArray())
}

function Read-AdvancedHuntingBundle {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $false)]
        [switch]$IncludeDeviceUsers,

        [Parameter(Mandatory = $false)]
        [switch]$IncludeInventoryData
    )

    $includeDeviceUsersRequested = [bool]$IncludeDeviceUsers
    $includeInventoryDataRequested = [bool]$IncludeInventoryData

    return Invoke-WithStoreLock -BasePath $Path -StoreName 'advancedhunting' -ScriptBlock {
        Restore-StoreTransaction -BasePath $Path -StoreName 'advancedhunting'

        Write-Information "Reading Advanced Hunting bundle data from $Path..." -InformationAction Continue

        $ahData = @{}
        $deviceUsers = @{}
        $inventoryData = @{}
        $parseErrors = 0
        $sourceFiles = @(Resolve-AdvancedHuntingBundleSourceFileList -Path $Path)

        if ($sourceFiles.Count -eq 0) {
            Write-Information '  No Advanced Hunting data files found. Bundle outputs will be empty.' -InformationAction Continue
            return [PSCustomObject]@{
                AdvancedHuntingData = @{}
                DeviceUsers = @{}
                InventoryData = @{}
            }
        }

        if ($sourceFiles.Count -eq 1) {
            Write-Information "  Using $($sourceFiles[0].Name)" -InformationAction Continue
        }
        else {
            Write-Information "  Found $($sourceFiles.Count) legacy Advanced Hunting file(s)" -InformationAction Continue
        }

        foreach ($file in $sourceFiles) {
            Write-Information "  Processing $($file.Name)..." -InformationAction Continue
            foreach ($record in Read-AdvancedHuntingRecordsFromFile -Path $file.FullName) {
                try {
                    $recordType = Get-AdvancedHuntingRecordType -Record $record

                    if ($includeInventoryDataRequested -and $recordType -eq 'Inventory') {
                        $inventoryKey = Get-AdvancedHuntingInventoryMatchKey `
                            -DeviceId ([string]$record.PSObject.Properties['DeviceId']?.Value) `
                            -SoftwareVendor ([string]$record.PSObject.Properties['SoftwareVendor']?.Value) `
                            -SoftwareName ([string]$record.PSObject.Properties['SoftwareName']?.Value) `
                            -SoftwareVersion ([string]$record.PSObject.Properties['SoftwareVersion']?.Value)
                        if ([string]::IsNullOrWhiteSpace($inventoryKey) -or $inventoryData.ContainsKey($inventoryKey)) {
                            continue
                        }

                        $productCodeCpe = [string]$record.PSObject.Properties['ProductCodeCpe']?.Value
                        $endOfSupportStatus = [string]$record.PSObject.Properties['EndOfSupportStatus']?.Value
                        $endOfSupportDate = Convert-ToYmdDate -DateValue $record.PSObject.Properties['EndOfSupportDate']?.Value

                        if ([string]::IsNullOrWhiteSpace($productCodeCpe) -and [string]::IsNullOrWhiteSpace($endOfSupportStatus) -and [string]::IsNullOrWhiteSpace($endOfSupportDate)) {
                            continue
                        }

                        $inventoryData[$inventoryKey] = @{
                            ProductCodeCpe = if ([string]::IsNullOrWhiteSpace($productCodeCpe)) { $null } else { $productCodeCpe }
                            EndOfSupportStatus = if ([string]::IsNullOrWhiteSpace($endOfSupportStatus)) { $null } else { $endOfSupportStatus }
                            EndOfSupportDate = $endOfSupportDate
                        }
                        continue
                    }

                    if ($includeDeviceUsersRequested -and $recordType -eq 'DeviceUsers') {
                        $deviceId = [string]$record.PSObject.Properties['DeviceId']?.Value
                        if ([string]::IsNullOrWhiteSpace($deviceId) -or $deviceUsers.ContainsKey($deviceId)) {
                            continue
                        }

                        $loggedOnUsers = ConvertTo-AdvancedHuntingBundleLoggedOnUserList -Value $record.PSObject.Properties['LoggedOnUsers']?.Value
                        if ($loggedOnUsers.Count -gt 0) {
                            $deviceUsers[$deviceId] = $loggedOnUsers
                        }
                        continue
                    }

                    $cveId = [string]$record.PSObject.Properties['CveId']?.Value
                    if (-not [string]::IsNullOrWhiteSpace($cveId) -and -not $ahData.ContainsKey($cveId)) {
                        $pdRaw = $record.PSObject.Properties['PublishedDate']?.Value
                        $rawDescription = $record.PSObject.Properties['VulnerabilityDescription']?.Value
                        $rawAffectedSoftware = $record.PSObject.Properties['AffectedSoftware']?.Value
                        $affectedSoftware = ConvertTo-AdvancedHuntingBundleStringArray -Value $rawAffectedSoftware
                        $ahData[$cveId] = @{
                            PublishedDate = Convert-ToYmdDate -DateValue $pdRaw
                            VulnerabilityDescription = ConvertTo-AdvancedHuntingBundleDescriptionValue -Value $rawDescription
                            EpssScore = $record.PSObject.Properties['EpssScore']?.Value
                            AffectedSoftware = if ($affectedSoftware.Count -gt 0) { $affectedSoftware } else { $null }
                            IsExploitAvailable = ConvertTo-AdvancedHuntingBundleNullableBoolean -Value $record.PSObject.Properties['IsExploitAvailable']?.Value
                        }
                    }
                }
                catch {
                    $parseErrors++
                    if ($parseErrors -le 5) {
                        Write-Warning "Failed to process Advanced Hunting bundle record in $($file.Name): $_"
                    }
                }
            }
        }

        if ($parseErrors -gt 0) {
            Write-Warning "Total bundle parse errors: $parseErrors"
        }

        Write-Information "  Bundle loaded $($ahData.Count) unique CVE(s)" -InformationAction Continue
        if ($IncludeDeviceUsers) {
            Write-Information "  Bundle loaded $($deviceUsers.Count) device-user record(s)" -InformationAction Continue
        }
        if ($IncludeInventoryData) {
            Write-Information "  Bundle loaded $($inventoryData.Count) inventory tuple(s)" -InformationAction Continue
        }

        return [PSCustomObject]@{
            AdvancedHuntingData = $ahData
            DeviceUsers = $deviceUsers
            InventoryData = $inventoryData
        }
    }
}

function Read-AdvancedHuntingData {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    function ConvertTo-AdvancedHuntingStringArray {
        [CmdletBinding()]
        [OutputType([string[]])]
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Value
        )

        return ,(ConvertTo-AdvancedHuntingBundleStringArray -Value $Value)
    }

    function ConvertTo-AdvancedHuntingDescriptionValue {
        [CmdletBinding()]
        [OutputType([string])]
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Value
        )

        if ($null -eq $Value) {
            return $null
        }

        if ($Value -is [string]) {
            return $Value
        }

        $parts = ConvertTo-AdvancedHuntingStringArray -Value $Value
        if ($parts.Count -eq 0) {
            return $null
        }

        return ($parts -join "`n")
    }

    function ConvertTo-AdvancedHuntingNullableBoolean {
        [CmdletBinding()]
        [OutputType([Nullable[bool]])]
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Value
        )

        if ($null -eq $Value) {
            return $null
        }

        if ($Value -is [bool]) {
            return $Value
        }

        $text = [string]$Value
        if ([string]::IsNullOrWhiteSpace($text)) {
            return $null
        }

        switch -Regex ($text.Trim().ToLowerInvariant()) {
            '^(true|1|yes)$' { return $true }
            '^(false|0|no)$' { return $false }
        }

        return $null
    }

    return Invoke-WithStoreLock -BasePath $Path -StoreName 'advancedhunting' -ScriptBlock {
        Restore-StoreTransaction -BasePath $Path -StoreName 'advancedhunting'

        Write-Information "Reading Advanced Hunting data from $Path..." -InformationAction Continue

        $ahData = @{}
        $parseErrors = 0
        $currentPath = Get-AdvancedHuntingCurrentPath -BasePath $Path
        $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath

        if ((-not (Test-Path -Path $currentPath)) -and (Test-Path -Path $legacyCurrentPath)) {
            $currentPath = $legacyCurrentPath
        }

        if (Test-Path -Path $currentPath) {
            Write-Information "  Using $(Split-Path -Leaf $currentPath)" -InformationAction Continue
            $sourceFiles = @(Get-Item -Path $currentPath)
        }
        else {
            $sourceFiles = @(Get-ChildItem -Path $Path -Filter 'AdvancedHunting_*.json' -File |
                Where-Object { Test-IsLegacyAdvancedHuntingSnapshotFileName -Name $_.Name } |
                Sort-Object Name -Descending)

            if ($sourceFiles.Count -eq 0) {
                Write-Warning 'No Advanced Hunting data files found. CVE enrichment will be skipped.'
                return @{}
            }

            Write-Information "  Found $($sourceFiles.Count) legacy Advanced Hunting file(s)" -InformationAction Continue
        }

        foreach ($file in $sourceFiles) {
            Write-Information "  Processing $($file.Name)..." -InformationAction Continue
            foreach ($record in Read-AdvancedHuntingRecordsFromFile -Path $file.FullName) {
                try {
                    $cveId = [string]$record.PSObject.Properties['CveId']?.Value
                    if (-not [string]::IsNullOrWhiteSpace($cveId) -and -not $ahData.ContainsKey($cveId)) {
                        $pdRaw = $record.PSObject.Properties['PublishedDate']?.Value
                        $rawDescription = $record.PSObject.Properties['VulnerabilityDescription']?.Value
                        $rawAffectedSoftware = $record.PSObject.Properties['AffectedSoftware']?.Value
                        $affectedSoftware = ConvertTo-AdvancedHuntingStringArray -Value $rawAffectedSoftware
                        $ahData[$cveId] = @{
                            PublishedDate = Convert-ToYmdDate -DateValue $pdRaw
                            VulnerabilityDescription = ConvertTo-AdvancedHuntingDescriptionValue -Value $rawDescription
                            EpssScore = $record.PSObject.Properties['EpssScore']?.Value
                            AffectedSoftware = if ($affectedSoftware.Count -gt 0) { $affectedSoftware } else { $null }
                            IsExploitAvailable = ConvertTo-AdvancedHuntingNullableBoolean -Value $record.PSObject.Properties['IsExploitAvailable']?.Value
                        }
                    }
                }
                catch {
                    $parseErrors++
                    if ($parseErrors -le 5) {
                        Write-Warning "Failed to process Advanced Hunting record in $($file.Name): $_"
                    }
                }
            }
        }

        if ($parseErrors -gt 0) {
            Write-Warning "Total parse errors: $parseErrors"
        }

        Write-Information "  Loaded enrichment data for $($ahData.Count) unique CVEs" -InformationAction Continue
        return $ahData
    }
}

function Read-AdvancedHuntingInventoryData {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    return Invoke-WithStoreLock -BasePath $Path -StoreName 'advancedhunting' -ScriptBlock {
        Restore-StoreTransaction -BasePath $Path -StoreName 'advancedhunting'

        Write-Information "Reading Advanced Hunting software inventory data from $Path..." -InformationAction Continue

        $inventoryData = @{}
        $parseErrors = 0
        $currentPath = Get-AdvancedHuntingCurrentPath -BasePath $Path
        $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath

        if ((-not (Test-Path -Path $currentPath)) -and (Test-Path -Path $legacyCurrentPath)) {
            $currentPath = $legacyCurrentPath
        }

        if (Test-Path -Path $currentPath) {
            Write-Information "  Using $(Split-Path -Leaf $currentPath)" -InformationAction Continue
            $sourceFiles = @(Get-Item -Path $currentPath)
        }
        else {
            $sourceFiles = @(Get-ChildItem -Path $Path -Filter 'AdvancedHunting_*.json' -File |
                Where-Object { Test-IsLegacyAdvancedHuntingSnapshotFileName -Name $_.Name } |
                Sort-Object Name -Descending)

            if ($sourceFiles.Count -eq 0) {
                Write-Information '  No Advanced Hunting software inventory data files found.' -InformationAction Continue
                return @{}
            }

            Write-Information "  Found $($sourceFiles.Count) legacy Advanced Hunting file(s)" -InformationAction Continue
        }

        foreach ($file in $sourceFiles) {
            Write-Information "  Processing $($file.Name)..." -InformationAction Continue
            foreach ($record in Read-AdvancedHuntingRecordsFromFile -Path $file.FullName) {
                try {
                    if ((Get-AdvancedHuntingRecordType -Record $record) -ne 'Inventory') {
                        continue
                    }

                    $inventoryKey = Get-AdvancedHuntingInventoryMatchKey `
                        -DeviceId ([string]$record.PSObject.Properties['DeviceId']?.Value) `
                        -SoftwareVendor ([string]$record.PSObject.Properties['SoftwareVendor']?.Value) `
                        -SoftwareName ([string]$record.PSObject.Properties['SoftwareName']?.Value) `
                        -SoftwareVersion ([string]$record.PSObject.Properties['SoftwareVersion']?.Value)
                    if ([string]::IsNullOrWhiteSpace($inventoryKey) -or $inventoryData.ContainsKey($inventoryKey)) {
                        continue
                    }

                    $productCodeCpe = [string]$record.PSObject.Properties['ProductCodeCpe']?.Value
                    $endOfSupportStatus = [string]$record.PSObject.Properties['EndOfSupportStatus']?.Value
                    $endOfSupportDate = Convert-ToYmdDate -DateValue $record.PSObject.Properties['EndOfSupportDate']?.Value

                    if ([string]::IsNullOrWhiteSpace($productCodeCpe) -and [string]::IsNullOrWhiteSpace($endOfSupportStatus) -and [string]::IsNullOrWhiteSpace($endOfSupportDate)) {
                        continue
                    }

                    $inventoryData[$inventoryKey] = @{
                        ProductCodeCpe = if ([string]::IsNullOrWhiteSpace($productCodeCpe)) { $null } else { $productCodeCpe }
                        EndOfSupportStatus = if ([string]::IsNullOrWhiteSpace($endOfSupportStatus)) { $null } else { $endOfSupportStatus }
                        EndOfSupportDate = $endOfSupportDate
                    }
                }
                catch {
                    $parseErrors++
                    if ($parseErrors -le 5) {
                        Write-Warning "Failed to process Advanced Hunting inventory record in $($file.Name): $_"
                    }
                }
            }
        }

        if ($parseErrors -gt 0) {
            Write-Warning "Total parse errors: $parseErrors"
        }

        Write-Information "  Loaded software inventory data for $($inventoryData.Count) device/software tuple(s)" -InformationAction Continue
        return $inventoryData
    }
}

function Read-AdvancedHuntingDeviceUserMap {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    function Add-AdvancedHuntingLoggedOnUserValue {
        [CmdletBinding()]
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Value,

            [Parameter(Mandatory = $true)]
            [AllowEmptyCollection()]
            [System.Collections.Generic.List[string]]$Values,

            [Parameter(Mandatory = $true)]
            [AllowEmptyCollection()]
            [System.Collections.Generic.HashSet[string]]$Seen
        )

        if ($null -eq $Value) {
            return
        }

        if ($Value -is [string]) {
            $text = $Value.Trim()
            if ([string]::IsNullOrWhiteSpace($text)) {
                return
            }

            if ((($text.StartsWith('[') -and $text.EndsWith(']')) -or ($text.StartsWith('{') -and $text.EndsWith('}')))) {
                try {
                    $parsedValue = $text | ConvertFrom-Json -Depth 20
                    Add-AdvancedHuntingLoggedOnUserValue -Value $parsedValue -Values $Values -Seen $Seen
                    return
                }
                catch {
                    Write-Verbose ("Falling back to raw LoggedOnUsers text after JSON parse failed: {0}" -f $_.Exception.Message)
                }
            }

            if ($Seen.Add($text)) {
                $Values.Add($text)
            }
            return
        }

        if ($Value -is [pscustomobject] -or $Value -is [System.Collections.IDictionary]) {
            $propertyBag = $Value.PSObject.Properties
            $upn = [string]$propertyBag['UserPrincipalName']?.Value
            $domainName = [string]$propertyBag['DomainName']?.Value
            $accountName = [string]$propertyBag['AccountName']?.Value
            $userName = [string]$propertyBag['UserName']?.Value
            $displayName = [string]$propertyBag['Name']?.Value

            $resolvedName = $null
            if (-not [string]::IsNullOrWhiteSpace($upn)) {
                $resolvedName = $upn.Trim()
            }
            elseif (-not [string]::IsNullOrWhiteSpace($accountName)) {
                $resolvedName = if (-not [string]::IsNullOrWhiteSpace($domainName)) {
                    $domainName.Trim() + '\' + $accountName.Trim()
                }
                else {
                    $accountName.Trim()
                }
            }
            elseif (-not [string]::IsNullOrWhiteSpace($userName)) {
                $resolvedName = if (-not [string]::IsNullOrWhiteSpace($domainName)) {
                    $domainName.Trim() + '\' + $userName.Trim()
                }
                else {
                    $userName.Trim()
                }
            }
            elseif (-not [string]::IsNullOrWhiteSpace($displayName)) {
                $resolvedName = $displayName.Trim()
            }

            if (-not [string]::IsNullOrWhiteSpace($resolvedName)) {
                if ($Seen.Add($resolvedName)) {
                    $Values.Add($resolvedName)
                }
                return
            }

            foreach ($property in $propertyBag) {
                Add-AdvancedHuntingLoggedOnUserValue -Value $property.Value -Values $Values -Seen $Seen
            }
            return
        }

        if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
            foreach ($item in $Value) {
                Add-AdvancedHuntingLoggedOnUserValue -Value $item -Values $Values -Seen $Seen
            }
            return
        }

        $fallbackText = [string]$Value
        if (-not [string]::IsNullOrWhiteSpace($fallbackText) -and $Seen.Add($fallbackText)) {
            $Values.Add($fallbackText)
        }
    }

    function ConvertTo-AdvancedHuntingLoggedOnUserList {
        [CmdletBinding()]
        [OutputType([string[]])]
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Value
        )

        $values = [System.Collections.Generic.List[string]]::new()
        $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        Add-AdvancedHuntingLoggedOnUserValue -Value $Value -Values $values -Seen $seen
        return [string[]]$values.ToArray()
    }

    return Invoke-WithStoreLock -BasePath $Path -StoreName 'advancedhunting' -ScriptBlock {
        Restore-StoreTransaction -BasePath $Path -StoreName 'advancedhunting'

        Write-Information "Reading Advanced Hunting device-user data from $Path..." -InformationAction Continue

        $deviceUsers = @{}
        $parseErrors = 0
        $currentPath = Get-AdvancedHuntingCurrentPath -BasePath $Path
        $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath

        if ((-not (Test-Path -Path $currentPath)) -and (Test-Path -Path $legacyCurrentPath)) {
            $currentPath = $legacyCurrentPath
        }

        if (Test-Path -Path $currentPath) {
            Write-Information "  Using $(Split-Path -Leaf $currentPath)" -InformationAction Continue
            $sourceFiles = @(Get-Item -Path $currentPath)
        }
        else {
            $sourceFiles = @(Get-ChildItem -Path $Path -Filter 'AdvancedHunting_*.json' -File |
                Where-Object { Test-IsLegacyAdvancedHuntingSnapshotFileName -Name $_.Name } |
                Sort-Object Name -Descending)

            if ($sourceFiles.Count -eq 0) {
                Write-Information '  No Advanced Hunting device-user data files found.' -InformationAction Continue
                return @{}
            }

            Write-Information "  Found $($sourceFiles.Count) legacy Advanced Hunting file(s)" -InformationAction Continue
        }

        foreach ($file in $sourceFiles) {
            Write-Information "  Processing $($file.Name)..." -InformationAction Continue
            foreach ($record in Read-AdvancedHuntingRecordsFromFile -Path $file.FullName) {
                try {
                    if ((Get-AdvancedHuntingRecordType -Record $record) -ne 'DeviceUsers') {
                        continue
                    }

                    $deviceId = [string]$record.PSObject.Properties['DeviceId']?.Value
                    if ([string]::IsNullOrWhiteSpace($deviceId) -or $deviceUsers.ContainsKey($deviceId)) {
                        continue
                    }

                    $loggedOnUsers = @(ConvertTo-AdvancedHuntingLoggedOnUserList -Value $record.PSObject.Properties['LoggedOnUsers']?.Value)
                    if ($loggedOnUsers.Count -gt 0) {
                        $deviceUsers[$deviceId] = @($loggedOnUsers)
                    }
                }
                catch {
                    $parseErrors++
                    if ($parseErrors -le 5) {
                        Write-Warning "Failed to process Advanced Hunting device-user record in $($file.Name): $_"
                    }
                }
            }
        }

        if ($parseErrors -gt 0) {
            Write-Warning "Total parse errors: $parseErrors"
        }

        Write-Information "  Loaded logged-on user data for $($deviceUsers.Count) device(s)" -InformationAction Continue
        return $deviceUsers
    }
}

function Read-NvdCveData {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    function ConvertTo-NvdStringArray {
        [CmdletBinding()]
        [OutputType([string[]])]
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Value
        )

        if ($null -eq $Value) {
            return @()
        }

        $values = [System.Collections.Generic.List[string]]::new()
        if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
            foreach ($item in $Value) {
                if ($null -eq $item) { continue }
                $text = [string]$item
                if (-not [string]::IsNullOrWhiteSpace($text)) {
                    $values.Add($text)
                }
            }
        }
        else {
            $text = [string]$Value
            if (-not [string]::IsNullOrWhiteSpace($text)) {
                $values.Add($text)
            }
        }

        return [string[]]$values.ToArray()
    }

    function ConvertTo-NvdDescriptionValue {
        [CmdletBinding()]
        [OutputType([string])]
        param(
            [Parameter(Mandatory = $false)]
            [AllowNull()]
            $Value
        )

        $parts = @(ConvertTo-NvdStringArray -Value $Value)
        if ($parts.Count -eq 0) {
            return $null
        }

        return ($parts -join "`n")
    }

    return Invoke-WithStoreLock -BasePath $Path -StoreName 'nvdcve' -ScriptBlock {
        Restore-StoreTransaction -BasePath $Path -StoreName 'nvdcve'

        $currentPath = Get-NvdCveCurrentPath -BasePath $Path
        if (-not (Test-Path -LiteralPath $currentPath -PathType Leaf)) {
            Write-Information "No NVD CVE cache found at $currentPath. NVD enrichment will be skipped." -InformationAction Continue
            return @{}
        }

        Write-Information "Reading NVD CVE data from $currentPath..." -InformationAction Continue

        $rawJson = Read-GzipTextFile -Path $currentPath
        if ([string]::IsNullOrWhiteSpace($rawJson)) {
            return @{}
        }

        try {
            $document = $rawJson | ConvertFrom-Json -Depth 100
        }
        catch {
            Write-Warning "Failed to parse NVD CVE cache '$currentPath': $_"
            return @{}
        }

        $records = if ($document.PSObject.Properties['records']) { @($document.records) } else { @($document) }
        $nvdData = @{}
        foreach ($record in $records) {
            if ($null -eq $record) {
                continue
            }

            $cveId = [string]$record.PSObject.Properties['CveId']?.Value
            if ([string]::IsNullOrWhiteSpace($cveId)) {
                continue
            }

            $weaknesses = @(ConvertTo-NvdStringArray -Value $record.PSObject.Properties['Weaknesses']?.Value)
            $nvdData[$cveId] = @{
                PublishedDate = Convert-ToYmdDate -DateValue $record.PSObject.Properties['PublishedDate']?.Value
                LastModifiedDate = Convert-ToYmdDate -DateValue $record.PSObject.Properties['LastModifiedDate']?.Value
                VulnerabilityDescription = ConvertTo-NvdDescriptionValue -Value $record.PSObject.Properties['VulnerabilityDescription']?.Value
                BaseScore = $record.PSObject.Properties['BaseScore']?.Value
                BaseSeverity = [string]$record.PSObject.Properties['BaseSeverity']?.Value
                Vector = [string]$record.PSObject.Properties['Vector']?.Value
                CisaExploitAdd = Convert-ToYmdDate -DateValue $record.PSObject.Properties['CisaExploitAdd']?.Value
                CisaActionDue = Convert-ToYmdDate -DateValue $record.PSObject.Properties['CisaActionDue']?.Value
                CisaRequiredAction = [string]$record.PSObject.Properties['CisaRequiredAction']?.Value
                Weaknesses = if ($weaknesses.Count -gt 0) { @($weaknesses) } else { $null }
            }
        }

        Write-Information "  Loaded NVD enrichment data for $($nvdData.Count) CVE(s)" -InformationAction Continue
        return $nvdData
    }
}

# Shared NVD export helpers used by local NVD cache sync and downstream
# enrichment consumers.

function Resolve-NvdApiKey {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$RequestedApiKey
    )

    if (-not [string]::IsNullOrWhiteSpace($RequestedApiKey)) {
        return $RequestedApiKey.Trim()
    }

    if (-not [string]::IsNullOrWhiteSpace($env:NVD_API_KEY)) {
        return $env:NVD_API_KEY.Trim()
    }

    return ''
}

function Get-NvdApiHeader {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$ResolvedApiKey
    )

    $headers = @{
        Accept = 'application/json'
    }

    if (-not [string]::IsNullOrWhiteSpace($ResolvedApiKey)) {
        $headers.apiKey = $ResolvedApiKey
    }

    return $headers
}

function Format-NvdApiDate {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [datetimeoffset]$Value
    )

    return $Value.UtcDateTime.ToString('yyyy-MM-ddTHH:mm:ss.fffZ')
}

function Invoke-NvdApiRequest {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string]$Uri,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 10)]
        [int]$MaxTransientRetries = 3,

        [Parameter(Mandatory = $false)]
        [ValidateRange(100, 30000)]
        [int]$InitialTransientDelayMs = 1000,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 3600)]
        [int]$TimeoutSeconds = 120
    )

    $attempt = 0
    $delayMs = $InitialTransientDelayMs

    while ($true) {
        try {
            return (Invoke-RestMethodWithRetry -Uri $Uri -Headers $Headers -Method Get -TimeoutSec $TimeoutSeconds)
        }
        catch {
            $attempt++
            $exceptionText = @(
                [string]$_.Exception.Message
                [string]$_.Exception.InnerException?.Message
            ) -join "`n"

            $isTransientTransportFailure = $exceptionText -match 'ResponseEnded|response ended prematurely|An error occurred while sending the request|The underlying connection was closed|The request was canceled|timed out'
            if (-not $isTransientTransportFailure -or $attempt -ge $MaxTransientRetries) {
                throw
            }

            Write-Warning ("Transient NVD transport failure (attempt {0}/{1}): {2}. Retrying in {3}s..." -f $attempt, $MaxTransientRetries, $_.Exception.Message, [math]::Round($delayMs / 1000, 1))
            Start-Sleep -Milliseconds $delayMs
            $delayMs = [int]($delayMs * 2)
        }
    }
}

function Get-NvdTargetCveIdSet {
    [CmdletBinding()]
    [OutputType([System.Collections.Generic.HashSet[string]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [string[]]$ExplicitCveIds,

        [Parameter(Mandatory = $false)]
        [switch]$SkipObservedWindowMerge
    )

    $targetCveIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    foreach ($value in @($ExplicitCveIds)) {
        $cveId = [string]$value
        if (-not [string]::IsNullOrWhiteSpace($cveId)) {
            [void]$targetCveIds.Add($cveId.Trim())
        }
    }

    if ($targetCveIds.Count -gt 0) {
        return (, $targetCveIds)
    }

    Write-Host 'Discovering target CVEs from local exports...' -ForegroundColor Cyan
    $processedCount = 0
    Get-NormalizationSourceRows -DataPath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge | ForEach-Object {
        $row = $_
        $cveId = [string]$row.PSObject.Properties['CveId']?.Value
        if (-not [string]::IsNullOrWhiteSpace($cveId)) {
            [void]$targetCveIds.Add($cveId)
        }

        $processedCount++
        if (($processedCount % 250000) -eq 0) {
            Write-Information ("  Indexed CVEs from {0} source row(s)..." -f $processedCount) -InformationAction Continue
        }
    }

    return (, $targetCveIds)
}

function Get-NvdEnglishDescription {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Descriptions
    )

    foreach ($description in @($Descriptions)) {
        if ($null -eq $description) { continue }
        $lang = [string](Get-NvdObjectPropertyValue -InputObject $description -PropertyName 'lang')
        $value = [string](Get-NvdObjectPropertyValue -InputObject $description -PropertyName 'value')
        if ($lang -eq 'en' -and -not [string]::IsNullOrWhiteSpace($value)) {
            return $value
        }
    }

    foreach ($description in @($Descriptions)) {
        if ($null -eq $description) { continue }
        $value = [string](Get-NvdObjectPropertyValue -InputObject $description -PropertyName 'value')
        if (-not [string]::IsNullOrWhiteSpace($value)) {
            return $value
        }
    }

    return $null
}

function Get-NvdWeaknessList {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Weaknesses
    )

    $values = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($weakness in @($Weaknesses)) {
        foreach ($description in @(Get-NvdObjectPropertyValue -InputObject $weakness -PropertyName 'description')) {
            $text = [string](Get-NvdObjectPropertyValue -InputObject $description -PropertyName 'value')
            if (-not [string]::IsNullOrWhiteSpace($text) -and $seen.Add($text)) {
                $values.Add($text)
            }
        }
    }

    if ($values.Count -eq 0) {
        return $null
    }

    return [string[]]$values.ToArray()
}

function Get-NvdObjectPropertyValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $InputObject,

        [Parameter(Mandatory = $true)]
        [string]$PropertyName
    )

    if ($null -eq $InputObject -or [string]::IsNullOrWhiteSpace($PropertyName)) {
        return $null
    }

    $property = $InputObject.PSObject.Properties[$PropertyName]
    if ($null -eq $property) {
        return $null
    }

    return $property.Value
}

function Get-NvdPreferredMetric {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Metrics
    )

    if ($null -eq $Metrics) {
        return $null
    }

    foreach ($propertyName in @('cvssMetricV40', 'cvssMetricV31', 'cvssMetricV30', 'cvssMetricV2')) {
        $property = $Metrics.PSObject.Properties[$propertyName]
        if ($null -eq $property) {
            continue
        }

        $candidates = @($property.Value | Where-Object { $null -ne $_ })
        if ($candidates.Count -eq 0) {
            continue
        }

        $primary = $candidates | Where-Object { [string]$_.type -eq 'Primary' } | Select-Object -First 1
        if ($null -ne $primary) {
            return $primary
        }

        return $candidates[0]
    }

    return $null
}

function Convert-NvdVulnerabilityToRecord {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        $Vulnerability
    )

    $cve = Get-NvdObjectPropertyValue -InputObject $Vulnerability -PropertyName 'cve'
    $cveId = [string](Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'id')
    if ($null -eq $cve -or [string]::IsNullOrWhiteSpace($cveId)) {
        return $null
    }

    $metric = Get-NvdPreferredMetric -Metrics (Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'metrics')
    $cvssData = if ($metric) { Get-NvdObjectPropertyValue -InputObject $metric -PropertyName 'cvssData' } else { $null }
    $weaknesses = Get-NvdWeaknessList -Weaknesses (Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'weaknesses')
    $baseScore = if ($cvssData) {
        Get-NvdObjectPropertyValue -InputObject $cvssData -PropertyName 'baseScore'
    }
    else {
        Get-NvdObjectPropertyValue -InputObject $metric -PropertyName 'baseScore'
    }
    $baseSeverity = if ($cvssData) {
        [string](Get-NvdObjectPropertyValue -InputObject $cvssData -PropertyName 'baseSeverity')
    }
    else {
        [string](Get-NvdObjectPropertyValue -InputObject $metric -PropertyName 'baseSeverity')
    }

    return [PSCustomObject]@{
        CveId = $cveId
        PublishedDate = Convert-ToYmdDate -DateValue (Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'published')
        LastModifiedDate = Convert-ToYmdDate -DateValue (Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'lastModified')
        VulnerabilityDescription = Get-NvdEnglishDescription -Descriptions (Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'descriptions')
        BaseScore = $baseScore
        BaseSeverity = $baseSeverity
        Vector = if ($cvssData) { [string](Get-NvdObjectPropertyValue -InputObject $cvssData -PropertyName 'vectorString') } else { $null }
        CisaExploitAdd = Convert-ToYmdDate -DateValue (Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'cisaExploitAdd')
        CisaActionDue = Convert-ToYmdDate -DateValue (Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'cisaActionDue')
        CisaRequiredAction = if ([string]::IsNullOrWhiteSpace([string](Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'cisaRequiredAction'))) { $null } else { [string](Get-NvdObjectPropertyValue -InputObject $cve -PropertyName 'cisaRequiredAction') }
        Weaknesses = $weaknesses
    }
}

function Read-NvdCacheDocument {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    $currentPath = Get-NvdCveCurrentPath -BasePath $BasePath
    if (-not (Test-Path -LiteralPath $currentPath -PathType Leaf)) {
        return $null
    }

    $json = Read-GzipTextFile -Path $currentPath
    if ([string]::IsNullOrWhiteSpace($json)) {
        return $null
    }

    return ($json | ConvertFrom-Json -Depth 100)
}

function Write-NvdCacheDocument {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$Document
    )

    $documentToWrite = $Document

    Invoke-WithStoreLock -BasePath $BasePath -StoreName 'nvdcve' -ScriptBlock {
        Restore-StoreTransaction -BasePath $BasePath -StoreName 'nvdcve'

        $currentPath = Get-NvdCveCurrentPath -BasePath $BasePath
        $stageRoot = Join-Path $BasePath ('.nvdcve-store-staging-' + [guid]::NewGuid().ToString('N'))
        [void](New-Item -Path $stageRoot -ItemType Directory -Force)

        try {
            $stagedCurrentPath = Join-Path $stageRoot (Split-Path -Leaf $currentPath)
            $json = $documentToWrite | ConvertTo-Json -Compress -Depth 100
            Write-GzipTextFile -Path $stagedCurrentPath -Content $json
            Publish-StoreFilesTransactional -BasePath $BasePath -StoreName 'nvdcve' -Files @([PSCustomObject]@{
                StagePath = $stagedCurrentPath
                TargetPath = $currentPath
            })
        }
        finally {
            if (Test-Path -LiteralPath $stageRoot) {
                Remove-Item -LiteralPath $stageRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    } | Out-Null
}

function Invoke-NvdTargetedBackfill {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [string[]]$CveIds,

        [Parameter(Mandatory = $true)]
        [hashtable]$RecordsByCve,

        [Parameter(Mandatory = $false)]
        [ValidateRange(0, 30)]
        [int]$ThrottleSeconds = 6,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 3600)]
        [int]$RequestTimeoutSeconds = 120
    )

    $requestCount = 0
    $updatedCount = 0
    $missing = [System.Collections.Generic.List[string]]::new()
    $baseUrl = 'https://services.nvd.nist.gov/rest/json/cves/2.0'

    for ($index = 0; $index -lt $CveIds.Count; $index++) {
        $cveId = [string]$CveIds[$index]
        if ([string]::IsNullOrWhiteSpace($cveId)) {
            continue
        }

        $uri = $baseUrl + '?cveId=' + [System.Uri]::EscapeDataString($cveId)
        $response = Invoke-NvdApiRequest -Headers $Headers -Uri $uri -TimeoutSeconds $RequestTimeoutSeconds
        $requestCount++
        $vulnerabilities = @($response.vulnerabilities | Where-Object { $null -ne $_ })
        if ($vulnerabilities.Count -eq 0) {
            $missing.Add($cveId)
        }
        else {
            $record = Convert-NvdVulnerabilityToRecord -Vulnerability $vulnerabilities[0]
            if ($null -ne $record) {
                $RecordsByCve[[string]$record.CveId] = $record
                $updatedCount++
            }
        }

        if (((($index + 1) % 25) -eq 0) -or (($index + 1) -eq $CveIds.Count)) {
            Write-Information ("  Targeted NVD backfill: {0}/{1} CVE(s) processed..." -f ($index + 1), $CveIds.Count) -InformationAction Continue
        }

        if ($ThrottleSeconds -gt 0 -and ($index + 1) -lt $CveIds.Count) {
            Start-Sleep -Seconds $ThrottleSeconds
        }
    }

    return [PSCustomObject]@{
        RequestCount = $requestCount
        UpdatedCount = $updatedCount
        MissingCveIds = @($missing)
    }
}

function Get-NvdMissingTargetCveIdList {
    [CmdletBinding()]
    [OutputType([string[]])]
    param(
        [Parameter(Mandatory = $true)]
        [System.Collections.Generic.HashSet[string]]$TargetCveIds,

        [Parameter(Mandatory = $true)]
        [hashtable]$RecordsByCve
    )

    $missing = [System.Collections.Generic.List[string]]::new()
    foreach ($targetCveId in $TargetCveIds) {
        $cveId = [string]$targetCveId
        if (-not $RecordsByCve.ContainsKey($cveId)) {
            $missing.Add($cveId)
        }
    }

    return [string[]]$missing.ToArray()
}

function Invoke-NvdCatalogBootstrap {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [System.Collections.Generic.HashSet[string]]$TargetCveIds,

        [Parameter(Mandatory = $true)]
        [hashtable]$RecordsByCve,

        [Parameter(Mandatory = $false)]
        [ValidateRange(0, 30)]
        [int]$ThrottleSeconds = 6,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 2000)]
        [int]$ResultsPerPage = 2000,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 3600)]
        [int]$RequestTimeoutSeconds = 120
    )

    $remainingTargets = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($targetCveId in $TargetCveIds) {
        $cveId = [string]$targetCveId
        if (-not $RecordsByCve.ContainsKey($cveId)) {
            [void]$remainingTargets.Add($cveId)
        }
    }

    if ($remainingTargets.Count -eq 0) {
        return [PSCustomObject]@{
            RequestCount = 0
            UpdatedCount = 0
            RemainingCount = 0
            TotalResults = 0
        }
    }

    Write-Host 'Cold-start bootstrap: reverse-scanning newest NVD catalog pages until the missing target CVEs are found...' -ForegroundColor Cyan

    $baseUrl = 'https://services.nvd.nist.gov/rest/json/cves/2.0'
    $requestCount = 0
    $pageRequestCount = 0
    $updatedCount = 0
    $totalResults = 0
    $totalPages = 0

    $metadataUri = $baseUrl + '?resultsPerPage=1&startIndex=0'
    $metadataResponse = Invoke-NvdApiRequest -Headers $Headers -Uri $metadataUri -TimeoutSeconds $RequestTimeoutSeconds
    $requestCount++
    $totalResults = [int]$metadataResponse.totalResults
    $totalPages = [int][math]::Ceiling($totalResults / [double]$ResultsPerPage)
    $startIndex = [int]([math]::Floor(([math]::Max(0, $totalResults - 1)) / [double]$ResultsPerPage) * $ResultsPerPage)

    Write-Information ("  Missing target CVEs before bootstrap: {0}. The full catalog is about {1} page(s) at {2} result(s) per page; the scan stops early once every missing target CVE is found." -f $remainingTargets.Count, $totalPages, $ResultsPerPage) -InformationAction Continue
    if ($ThrottleSeconds -gt 0) {
        $estimatedMinutes = [int][math]::Ceiling((([math]::Max(0, $totalPages - 1)) * $ThrottleSeconds) / 60.0)
        Write-Information ("  Worst-case full-catalog scan at {0}s throttle would take about {1} minute(s), but most runs should stop earlier." -f $ThrottleSeconds, $estimatedMinutes) -InformationAction Continue
    }

    do {
        $uri = $baseUrl + '?' + (@(
                'resultsPerPage=' + $ResultsPerPage
                'startIndex=' + $startIndex
            ) -join '&')

        $response = Invoke-NvdApiRequest -Headers $Headers -Uri $uri -TimeoutSeconds $RequestTimeoutSeconds
        $requestCount++
        $pageRequestCount++

        $vulnerabilities = @($response.vulnerabilities | Where-Object { $null -ne $_ })
        foreach ($vulnerability in $vulnerabilities) {
            $record = Convert-NvdVulnerabilityToRecord -Vulnerability $vulnerability
            if ($null -eq $record) {
                continue
            }

            $recordCveId = [string]$record.CveId
            if (-not $remainingTargets.Contains($recordCveId)) {
                continue
            }

            $RecordsByCve[$recordCveId] = $record
            if ($remainingTargets.Remove($recordCveId)) {
                $updatedCount++
            }
        }

        if ((($pageRequestCount % 5) -eq 0) -or ($remainingTargets.Count -eq 0)) {
            $catalogPageNumber = if ($totalPages -gt 0) { ([int][math]::Floor($startIndex / [double]$ResultsPerPage) + 1) } else { $pageRequestCount }
            $scannedPercent = if ($totalPages -gt 0) { [int][math]::Round(($pageRequestCount / [double]$totalPages) * 100) } else { 100 }
            Write-Information ("  Catalog bootstrap progress: scanned {0}/{1} page(s) ({2}% of worst-case path); current catalog page {3}; matched {4} target CVE(s); remaining {5}." -f $pageRequestCount, $totalPages, $scannedPercent, $catalogPageNumber, $updatedCount, $remainingTargets.Count) -InformationAction Continue
        }

        if ($remainingTargets.Count -eq 0) {
            break
        }

        if ($startIndex -le 0) {
            break
        }

        $startIndex = [math]::Max(0, ($startIndex - $ResultsPerPage))

        if ($ThrottleSeconds -gt 0) {
            Start-Sleep -Seconds $ThrottleSeconds
        }
    } while ($true)

    return [PSCustomObject]@{
        RequestCount = $requestCount
        UpdatedCount = $updatedCount
        RemainingCount = $remainingTargets.Count
        TotalResults = $totalResults
    }
}

function Invoke-NvdDeltaSync {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$Headers,

        [Parameter(Mandatory = $true)]
        [System.Collections.Generic.HashSet[string]]$TargetCveIds,

        [Parameter(Mandatory = $true)]
        [hashtable]$RecordsByCve,

        [Parameter(Mandatory = $true)]
        [datetimeoffset]$StartUtc,

        [Parameter(Mandatory = $true)]
        [datetimeoffset]$EndUtc,

        [Parameter(Mandatory = $false)]
        [ValidateRange(0, 30)]
        [int]$ThrottleSeconds = 6,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1, 3600)]
        [int]$RequestTimeoutSeconds = 120
    )

    if ($StartUtc -ge $EndUtc) {
        return [PSCustomObject]@{
            RequestCount = 0
            UpdatedCount = 0
        }
    }

    $baseUrl = 'https://services.nvd.nist.gov/rest/json/cves/2.0'
    $requestCount = 0
    $updatedCount = 0
    $startIndex = 0
    do {
        $uri = $baseUrl + '?' + (
            @(
                'lastModStartDate=' + [System.Uri]::EscapeDataString((Format-NvdApiDate -Value $StartUtc))
                'lastModEndDate=' + [System.Uri]::EscapeDataString((Format-NvdApiDate -Value $EndUtc))
                'startIndex=' + $startIndex
            ) -join '&'
        )

        $response = Invoke-NvdApiRequest -Headers $Headers -Uri $uri -TimeoutSeconds $RequestTimeoutSeconds
        $requestCount++
        $vulnerabilities = @($response.vulnerabilities | Where-Object { $null -ne $_ })
        foreach ($vulnerability in $vulnerabilities) {
            $record = Convert-NvdVulnerabilityToRecord -Vulnerability $vulnerability
            if ($null -eq $record) {
                continue
            }

            if ($TargetCveIds.Contains([string]$record.CveId) -or $RecordsByCve.ContainsKey([string]$record.CveId)) {
                $RecordsByCve[[string]$record.CveId] = $record
                $updatedCount++
            }
        }

        $resultsPerPage = [int]$response.resultsPerPage
        if ($resultsPerPage -le 0) {
            break
        }

        $startIndex += $resultsPerPage
        if ($startIndex -lt [int]$response.totalResults) {
            if ($ThrottleSeconds -gt 0) {
                Start-Sleep -Seconds $ThrottleSeconds
            }
        }
        else {
            break
        }
    } while ($true)

    return [PSCustomObject]@{
        RequestCount = $requestCount
        UpdatedCount = $updatedCount
    }
}

# Shared generator/runbook helpers used for dashboard normalization and HTML assembly.

function Get-DashboardTemplateContent {
    <#
    .SYNOPSIS
        Reads dashboard template files from the templates directory.

    .DESCRIPTION
        Reads the HTML, CSS, and JavaScript template files and returns their content.
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$TemplatesPath,

        [Parameter(Mandatory = $true)]
        [string]$DefaultRootPath
    )

    $templatesDirectory = if (-not [string]::IsNullOrWhiteSpace($TemplatesPath)) {
        $TemplatesPath
    }
    else {
        Join-Path -Path $DefaultRootPath -ChildPath 'templates'
    }

    $templates = @{
        Html = $null
        Css = $null
        Js = $null
    }

    $htmlPath = Join-Path -Path $templatesDirectory -ChildPath 'dashboard.html'
    $cssPath = Join-Path -Path $templatesDirectory -ChildPath 'dashboard.css'
    $jsPath = Join-Path -Path $templatesDirectory -ChildPath 'dashboard.js'

    if (Test-Path -Path $htmlPath) {
        Write-Host '  Loading HTML template...' -ForegroundColor Gray
        $templates.Html = Get-Content -Path $htmlPath -Raw
    }
    else {
        throw "Template file not found: $htmlPath"
    }

    if (Test-Path -Path $cssPath) {
        Write-Host '  Loading CSS template...' -ForegroundColor Gray
        $templates.Css = Get-Content -Path $cssPath -Raw
    }
    else {
        throw "Template file not found: $cssPath"
    }

    if (Test-Path -Path $jsPath) {
        Write-Host '  Loading JavaScript template...' -ForegroundColor Gray
        $templates.Js = Get-Content -Path $jsPath -Raw
    }
    else {
        throw "Template file not found: $jsPath"
    }

    return $templates
}

function Get-LocalDashboardRepositoryRoot {
    [CmdletBinding()]
    [OutputType([string])]
    param()

    $candidatePath = $PSScriptRoot
    while (-not [string]::IsNullOrWhiteSpace($candidatePath)) {
        if ((Test-Path -LiteralPath (Join-Path $candidatePath 'Generate-VulnerabilityDashboard.ps1') -PathType Leaf) -and
            (Test-Path -LiteralPath (Join-Path $candidatePath 'build') -PathType Container)) {
            return $candidatePath
        }

        $parentPath = Split-Path -Path $candidatePath -Parent
        if ([string]::IsNullOrWhiteSpace($parentPath) -or $parentPath -eq $candidatePath) {
            break
        }

        $candidatePath = $parentPath
    }

    return $null
}

function Find-SharedDashboardLibraryCacheFile {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$CacheFileName
    )

    $repoRoot = Get-LocalDashboardRepositoryRoot
    if ([string]::IsNullOrWhiteSpace($repoRoot)) {
        return $null
    }

    $libraryCacheSuffix = [System.IO.Path]::Combine('.dashboard-cache', 'libraries')
    foreach ($searchRoot in @(
        (Join-Path $repoRoot 'exports'),
        (Join-Path $repoRoot '.local')
    )) {
        if (-not (Test-Path -LiteralPath $searchRoot -PathType Container)) {
            continue
        }

        $cacheMatch = Get-ChildItem -LiteralPath $searchRoot -Filter $CacheFileName -File -Recurse -ErrorAction SilentlyContinue |
            Where-Object { $_.DirectoryName.EndsWith($libraryCacheSuffix, [System.StringComparison]::OrdinalIgnoreCase) -and $_.Length -gt 0 } |
            Select-Object -First 1

        if ($null -ne $cacheMatch) {
            return $cacheMatch.FullName
        }
    }

    return $null
}

function Save-JSLibraryFile {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Url,

        [Parameter(Mandatory = $true)]
        [string]$Name,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $false)]
        [bool]$Critical = $false,

        [Parameter(Mandatory = $false)]
        [string]$CacheBasePath
    )

    $cachePath = $null
    $cacheFileName = $null
    if (-not [string]::IsNullOrWhiteSpace($CacheBasePath)) {
        $cacheDirectory = Get-DashboardCacheDirectory -BasePath $CacheBasePath -ChildPath 'libraries' -Create
        $urlHashBytes = [System.Security.Cryptography.SHA256]::HashData([System.Text.Encoding]::UTF8.GetBytes($Url))
        $urlHash = ([System.BitConverter]::ToString($urlHashBytes)).Replace('-', '').ToLowerInvariant().Substring(0, 16)
        $extension = [System.IO.Path]::GetExtension($OutputPath)
        if ([string]::IsNullOrWhiteSpace($extension)) {
            $extension = '.js'
        }

        $safeName = ($Name -replace '[^A-Za-z0-9._-]', '-')
        $cachePath = Join-Path $cacheDirectory ("{0}-{1}{2}" -f $safeName, $urlHash, $extension)
        $cacheFileName = [System.IO.Path]::GetFileName($cachePath)
        if (Test-Path -LiteralPath $cachePath -PathType Leaf) {
            $cachedLibrary = Get-Item -LiteralPath $cachePath
            if ($cachedLibrary.Length -le 0) {
                Write-Warning "Cached $Name library was empty; refreshing."
                Remove-Item -LiteralPath $cachePath -Force -ErrorAction SilentlyContinue
            }
            else {
                Copy-Item -LiteralPath $cachePath -Destination $OutputPath -Force
                Write-Information "Reusing cached $Name library" -InformationAction Continue
                return $OutputPath
            }
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($cacheFileName)) {
        $sharedCachePath = Find-SharedDashboardLibraryCacheFile -CacheFileName $cacheFileName
        if (-not [string]::IsNullOrWhiteSpace($sharedCachePath)) {
            Copy-Item -LiteralPath $sharedCachePath -Destination $OutputPath -Force
            if (-not [string]::IsNullOrWhiteSpace($cachePath) -and -not $sharedCachePath.Equals($cachePath, [System.StringComparison]::OrdinalIgnoreCase)) {
                Copy-Item -LiteralPath $sharedCachePath -Destination $cachePath -Force
            }

            Write-Information "Reusing shared cached $Name library" -InformationAction Continue
            return $OutputPath
        }
    }

    Write-Information "Downloading $Name library..." -InformationAction Continue

    try {
        Invoke-WebRequest -Uri $Url -OutFile $OutputPath -TimeoutSec 30
        $downloadedLibrary = Get-Item -LiteralPath $OutputPath -ErrorAction Stop
        if ($downloadedLibrary.Length -le 0) {
            throw "$Name library download produced an empty file."
        }

        if ($cachePath) {
            Copy-Item -LiteralPath $OutputPath -Destination $cachePath -Force
        }
        Write-Information "  $Name downloaded successfully" -InformationAction Continue
        return $OutputPath
    }
    catch {
        if (Test-Path -LiteralPath $OutputPath -PathType Leaf) {
            Remove-Item -LiteralPath $OutputPath -Force -ErrorAction SilentlyContinue
        }

        $errorMessage = "Failed to download $Name from $Url`: $_"
        if ($Critical) {
            Write-Error $errorMessage
            throw
        }

        Write-Warning $errorMessage
        return $null
    }
}

function Write-FileContent {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [System.IO.TextWriter]$Writer,

        [Parameter(Mandatory = $true)]
        [string]$FilePath
    )

    $reader = [System.IO.StreamReader]::new($FilePath, [System.Text.Encoding]::UTF8)
    try {
        $buffer = New-Object char[] 8192
        while (($charsRead = $reader.Read($buffer, 0, $buffer.Length)) -gt 0) {
            $Writer.Write($buffer, 0, $charsRead)
        }
    }
    finally {
        $reader.Dispose()
    }
}

function Compress-FileGzip {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$InputPath,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $false)]
        [System.IO.Compression.CompressionLevel]$CompressionLevel = [System.IO.Compression.CompressionLevel]::Fastest
    )

    $inputStream = $null
    $outputStream = $null
    $gzipStream = $null
    try {
        $inputStream = [System.IO.File]::OpenRead($InputPath)
        $outputStream = [System.IO.File]::Create($OutputPath)
        $gzipStream = [System.IO.Compression.GZipStream]::new($outputStream, $CompressionLevel)
        $inputStream.CopyTo($gzipStream)
    }
    finally {
        if ($gzipStream) { $gzipStream.Dispose() }
        elseif ($outputStream) { $outputStream.Dispose() }
        if ($inputStream) { $inputStream.Dispose() }
    }

    return $OutputPath
}

function Write-CombinedTextBundle {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string[]]$InputPaths,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath
    )

    $writer = [System.IO.StreamWriter]::new($OutputPath, $false, [System.Text.UTF8Encoding]::new($false))
    try {
        foreach ($inputPath in $InputPaths) {
            if ([string]::IsNullOrWhiteSpace($inputPath) -or -not (Test-Path -LiteralPath $inputPath -PathType Leaf)) {
                continue
            }

            Write-FileContent -Writer $writer -FilePath $inputPath
            $writer.WriteLine()
            $writer.WriteLine()
        }
    }
    finally {
        $writer.Dispose()
    }

    return $OutputPath
}

function Write-Base64CharBuffer {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [System.IO.TextWriter]$Writer,

        [Parameter(Mandatory = $true)]
        [char[]]$Chars,

        [Parameter(Mandatory = $true)]
        [int]$Count,

        [Parameter(Mandatory = $true)]
        [ref]$CurrentLineLength,

        [Parameter(Mandatory = $false)]
        [switch]$InsertLineBreaks
    )

    if ($Count -le 0) {
        return
    }

    if (-not $InsertLineBreaks) {
        $Writer.Write($Chars, 0, $Count)
        return
    }

    $offset = 0
    $lineLength = [int]$CurrentLineLength.Value
    while ($offset -lt $Count) {
        $remainingOnLine = 76 - $lineLength
        if ($remainingOnLine -le 0) {
            $Writer.Write("`r`n")
            $lineLength = 0
            $remainingOnLine = 76
        }

        $charsToWrite = [System.Math]::Min($remainingOnLine, $Count - $offset)
        $Writer.Write($Chars, $offset, $charsToWrite)
        $offset += $charsToWrite
        $lineLength += $charsToWrite

        if ($lineLength -eq 76 -and $offset -lt $Count) {
            $Writer.Write("`r`n")
            $lineLength = 0
        }
    }

    $CurrentLineLength.Value = $lineLength
}

function Write-Base64FileContent {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [System.IO.TextWriter]$Writer,

        [Parameter(Mandatory = $true)]
        [string]$FilePath,

        [Parameter(Mandatory = $false)]
        [switch]$InsertLineBreaks
    )

    $inputBlockByteCount = 57 * 128
    $inputBuffer = [byte[]]::new($inputBlockByteCount + 2)
    $base64CharBuffer = [char[]]::new([int]([System.Math]::Ceiling($inputBuffer.Length / 3.0) * 4))
    $currentLineLength = 0
    $pendingByteCount = 0
    $stream = $null

    try {
        $stream = [System.IO.FileStream]::new(
            $FilePath,
            [System.IO.FileMode]::Open,
            [System.IO.FileAccess]::Read,
            [System.IO.FileShare]::Read,
            4096,
            [System.IO.FileOptions]::SequentialScan)
        while (($bytesRead = $stream.Read($inputBuffer, $pendingByteCount, $inputBlockByteCount)) -gt 0) {
            $totalByteCount = $pendingByteCount + $bytesRead
            $bytesToEncode = if ($stream.Position -lt $stream.Length) {
                $totalByteCount - ($totalByteCount % 3)
            }
            else {
                $totalByteCount
            }

            if ($bytesToEncode -le 0) {
                $pendingByteCount = $totalByteCount
                continue
            }

            $base64CharCount = [System.Convert]::ToBase64CharArray($inputBuffer, 0, $bytesToEncode, $base64CharBuffer, 0)
            Write-Base64CharBuffer -Writer $Writer -Chars $base64CharBuffer -Count $base64CharCount -CurrentLineLength ([ref]$currentLineLength) -InsertLineBreaks:$InsertLineBreaks

            $pendingByteCount = $totalByteCount - $bytesToEncode
            if ($pendingByteCount -gt 0) {
                [System.Array]::Copy($inputBuffer, $bytesToEncode, $inputBuffer, 0, $pendingByteCount)
            }
        }

        if ($pendingByteCount -gt 0) {
            $base64CharCount = [System.Convert]::ToBase64CharArray($inputBuffer, 0, $pendingByteCount, $base64CharBuffer, 0)
            Write-Base64CharBuffer -Writer $Writer -Chars $base64CharBuffer -Count $base64CharCount -CurrentLineLength ([ref]$currentLineLength) -InsertLineBreaks:$InsertLineBreaks
        }
    }
    finally {
        if ($stream) {
            $stream.Dispose()
        }
    }
}

function Get-Base64FileContent {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$FilePath,

        [Parameter(Mandatory = $false)]
        [switch]$InsertLineBreaks
    )

    $bytes = [System.IO.File]::ReadAllBytes($FilePath)
    $formatting = if ($InsertLineBreaks) { [System.Base64FormattingOptions]::InsertLineBreaks } else { [System.Base64FormattingOptions]::None }
    return [System.Convert]::ToBase64String($bytes, $formatting)
}

function Write-JsonValueToWriter {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextWriter]$Writer,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Value
    )

    if ($null -eq $Value) {
        $Writer.WriteNull()
        return
    }

    if ($Value -is [System.Management.Automation.PSObject]) {
        $wroteNoteProperties = $false
        foreach ($property in $Value.PSObject.Properties) {
            if ($property.MemberType -ne [System.Management.Automation.PSMemberTypes]::NoteProperty) {
                continue
            }

            if (-not $wroteNoteProperties) {
                $Writer.WriteStartObject()
                $wroteNoteProperties = $true
            }

            $Writer.WritePropertyName([string]$property.Name)
            Write-JsonValueToWriter -Writer $Writer -Value $property.Value
        }

        if ($wroteNoteProperties) {
            $Writer.WriteEndObject()
            return
        }

        $baseValue = $Value.BaseObject
        if ($null -ne $baseValue -and $baseValue -ne $Value) {
            Write-JsonValueToWriter -Writer $Writer -Value $baseValue
            return
        }
    }

    $typeCode = [System.Type]::GetTypeCode($Value.GetType())
    switch ($typeCode) {
        ([System.TypeCode]::Boolean) {
            $Writer.WriteValue([bool]$Value)
            return
        }
        ([System.TypeCode]::Byte) {
            $Writer.WriteValue([byte]$Value)
            return
        }
        ([System.TypeCode]::SByte) {
            $Writer.WriteValue([sbyte]$Value)
            return
        }
        ([System.TypeCode]::Int16) {
            $Writer.WriteValue([int16]$Value)
            return
        }
        ([System.TypeCode]::UInt16) {
            $Writer.WriteValue([uint16]$Value)
            return
        }
        ([System.TypeCode]::Int32) {
            $Writer.WriteValue([int]$Value)
            return
        }
        ([System.TypeCode]::UInt32) {
            $Writer.WriteValue([uint32]$Value)
            return
        }
        ([System.TypeCode]::Int64) {
            $Writer.WriteValue([long]$Value)
            return
        }
        ([System.TypeCode]::UInt64) {
            $Writer.WriteValue([uint64]$Value)
            return
        }
        ([System.TypeCode]::Single) {
            $Writer.WriteValue([single]$Value)
            return
        }
        ([System.TypeCode]::Double) {
            $Writer.WriteValue([double]$Value)
            return
        }
        ([System.TypeCode]::Decimal) {
            $Writer.WriteValue([decimal]$Value)
            return
        }
        ([System.TypeCode]::DateTime) {
            $Writer.WriteValue(([datetime]$Value).ToString('o'))
            return
        }
        ([System.TypeCode]::Char) {
            $Writer.WriteValue([string]$Value)
            return
        }
        ([System.TypeCode]::String) {
            $Writer.WriteValue([string]$Value)
            return
        }
    }

    if ($Value -is [System.Collections.IDictionary]) {
        $Writer.WriteStartObject()
        foreach ($key in $Value.Keys) {
            $Writer.WritePropertyName([string]$key)
            Write-JsonValueToWriter -Writer $Writer -Value $Value[$key]
        }
        $Writer.WriteEndObject()
        return
    }

    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        $Writer.WriteStartArray()
        foreach ($item in $Value) {
            Write-JsonValueToWriter -Writer $Writer -Value $item
        }
        $Writer.WriteEndArray()
        return
    }

    $Writer.WriteValue($Value.ToString())
}

function Get-NormalizedLookupPropertyValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Value,

        [Parameter(Mandatory = $true)]
        [string]$Name
    )

    if ($null -eq $Value) {
        return $null
    }

    if ($Value -is [System.Collections.IDictionary]) {
        return $Value[$Name]
    }

    $property = $Value.PSObject.Properties[$Name]
    if ($null -ne $property) {
        return $property.Value
    }

    return $null
}

function Set-NormalizedLookupPropertyValue {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Internal helper updates in-memory lookup state during payload finalization.')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [object]$Lookups,

        [Parameter(Mandatory = $true)]
        [string]$Name,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Value
    )

    if ($Lookups -is [System.Collections.IDictionary]) {
        $Lookups[$Name] = $Value
        return
    }

    $property = $Lookups.PSObject.Properties[$Name]
    if ($null -ne $property) {
        $property.Value = $Value
        return
    }

    Add-Member -InputObject $Lookups -NotePropertyName $Name -NotePropertyValue $Value -Force
}

function Get-NormalizedLookupCount {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [object]$Lookups,

        [Parameter(Mandatory = $true)]
        [string]$Name
    )

    $value = Get-NormalizedLookupPropertyValue -Value $Lookups -Name $Name
    if ($null -eq $value) {
        return 0
    }

    if ($value -is [System.Collections.ICollection]) {
        return [int]$value.Count
    }

    return [int]@($value).Count
}

function Get-NormalizedLookupCountSummary {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [object]$Lookups
    )

    return [PSCustomObject]@{
        DeviceCount = Get-NormalizedLookupCount -Lookups $Lookups -Name 'devices'
        CveCount = Get-NormalizedLookupCount -Lookups $Lookups -Name 'cves'
        SoftwareCount = Get-NormalizedLookupCount -Lookups $Lookups -Name 'software'
        VendorCount = Get-NormalizedLookupCount -Lookups $Lookups -Name 'vendors'
    }
}

function Write-NormalizedDeviceMachineInfoToWriter {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextWriter]$Writer,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$MachineInfo
    )

    if ($null -eq $MachineInfo) {
        $Writer.WriteNull()
        return
    }

    $Writer.WriteStartObject()
    foreach ($propertyName in @('ip', 'eip', 'u', 'hs', 'rs', 'el', 'dv', 'mb', 'aad', 'ls', 'fs')) {
        $Writer.WritePropertyName($propertyName)
        Write-JsonValueToWriter -Writer $Writer -Value (Get-NormalizedLookupPropertyValue -Value $MachineInfo -Name $propertyName)
    }
    $Writer.WriteEndObject()
}

function Write-NormalizedDeviceLookupsToWriter {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextWriter]$Writer,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Devices
    )

    if ($null -eq $Devices) {
        $Writer.WriteNull()
        return
    }

    $Writer.WriteStartArray()
    foreach ($device in $Devices) {
        if ($null -eq $device) {
            $Writer.WriteNull()
            continue
        }

        $Writer.WriteStartObject()
        foreach ($propertyName in @('id', 'n', 'g', 'o', 'ov', 't')) {
            $Writer.WritePropertyName($propertyName)
            Write-JsonValueToWriter -Writer $Writer -Value (Get-NormalizedLookupPropertyValue -Value $device -Name $propertyName)
        }
        $Writer.WritePropertyName('m')
        Write-NormalizedDeviceMachineInfoToWriter -Writer $Writer -MachineInfo (Get-NormalizedLookupPropertyValue -Value $device -Name 'm')
        $Writer.WriteEndObject()
    }
    $Writer.WriteEndArray()
}

function Open-JsonArrayFileWriter {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $streamWriter = [System.IO.StreamWriter]::new($Path, $false, [System.Text.UTF8Encoding]::new($false))
    $jsonWriter = [Newtonsoft.Json.JsonTextWriter]::new($streamWriter)
    $jsonWriter.Formatting = [Newtonsoft.Json.Formatting]::None
    $jsonWriter.WriteStartArray()

    return [PSCustomObject]@{
        Path = $Path
        StreamWriter = $streamWriter
        JsonWriter = $jsonWriter
    }
}

function Write-JsonArrayFileValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState,

        [Parameter(Mandatory = $false)]
        $Value
    )

    Write-JsonValueToWriter -Writer $WriterState.JsonWriter -Value $Value
}

function Close-JsonArrayFileWriter {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState
    )

    if ($WriterState.JsonWriter) {
        $WriterState.JsonWriter.WriteEndArray()
        $WriterState.JsonWriter.Flush()
        $WriterState.JsonWriter.Close()
        $WriterState.JsonWriter = $null
        $WriterState.StreamWriter = $null
        return
    }

    if ($WriterState.StreamWriter) {
        $WriterState.StreamWriter.Dispose()
        $WriterState.StreamWriter = $null
    }
}

function Write-CompactJsonArrayValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState,

        [Parameter(Mandatory = $false)]
        $Value
    )

    $writer = $WriterState.JsonWriter
    if ($null -eq $Value) {
        $writer.WriteNull()
        return
    }

    if ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        $writer.WriteStartArray()
        foreach ($nestedValue in $Value) {
            if ($null -eq $nestedValue) {
                $writer.WriteNull()
            }
            else {
                $writer.WriteValue($nestedValue)
            }
        }
        $writer.WriteEndArray()
        return
    }

    $writer.WriteValue($Value)
}

function Write-CompactColumnFileValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($WriterState.PSObject.Properties['JsonWriter'] -and $WriterState.JsonWriter) {
        Write-CompactJsonArrayValue -WriterState $WriterState -Value $Value
        return
    }

    Add-CompactVulnColumnValue -ColumnState $WriterState -Value $Value
}

function Open-CompactVulnColumnWriterSet {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$DirectoryPath
    )

    $null = New-Item -Path $DirectoryPath -ItemType Directory -Force
    $paths = [ordered]@{}
    $writers = @{}
    foreach ($columnName in @('d', 'c', 's', 'v', 'f', 'l', 'ua', 'u', 'dp', 'rp', 'iv')) {
        $columnPath = Join-Path $DirectoryPath ($columnName + '.json')
        $streamWriter = [System.IO.StreamWriter]::new($columnPath, $false, [System.Text.UTF8Encoding]::new($false))
        $streamWriter.Write('[')
        $paths[$columnName] = $columnPath
        $writers[$columnName] = [PSCustomObject]@{
            Path = $columnPath
            StreamWriter = $streamWriter
            Buffer = [System.Text.StringBuilder]::new(131072)
            HasValue = $false
        }
    }

    $columnOrder = @('d', 'c', 's', 'v', 'f', 'l', 'ua', 'u', 'dp', 'rp', 'iv')
    $columnStates = [object[]]::new(11)
    for ($i = 0; $i -lt 11; $i++) {
        $columnStates[$i] = $writers[$columnOrder[$i]]
    }

    return [PSCustomObject]@{
        DirectoryPath = $DirectoryPath
        Paths = $paths
        Writers = $writers
        ColumnStates = $columnStates
    }
}

function Write-CompactVulnRecordColumnSet {
    param(
        [pscustomobject]$WriterSet,
        [object[]]$Record
    )

    if ($null -eq $Record) {
        throw 'Compact vulnerability record cannot be null.'
    }

    $states = $WriterSet.ColumnStates
    for ($i = 0; $i -lt 11; $i++) {
        $col = $states[$i]
        $val = $Record[$i]
        $buf = $col.Buffer

        if ($col.HasValue) { [void]$buf.Append(',') } else { $col.HasValue = $true }

        if ($null -eq $val) {
            [void]$buf.Append('null')
        }
        elseif ($val -is [System.Collections.IEnumerable] -and $val -isnot [string]) {
            [void]$buf.Append('[')
            $isFirst = $true
            foreach ($nv in $val) {
                if ($isFirst) { $isFirst = $false } else { [void]$buf.Append(',') }
                if ($null -eq $nv) { [void]$buf.Append('null') } else { [void]$buf.Append([string]$nv) }
            }
            [void]$buf.Append(']')
        }
        else {
            [void]$buf.Append([string]$val)
        }

        if ($buf.Length -ge 131072) {
            $col.StreamWriter.Write($buf.ToString())
            [void]$buf.Clear()
        }
    }
}

function Add-CompactVulnColumnValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ColumnState,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    $buffer = $ColumnState.Buffer
    if ($ColumnState.HasValue) {
        [void]$buffer.Append(',')
    }
    else {
        $ColumnState.HasValue = $true
    }

    if ($null -eq $Value) {
        [void]$buffer.Append('null')
    }
    elseif ($Value -is [System.Collections.IEnumerable] -and $Value -isnot [string]) {
        [void]$buffer.Append('[')
        $isFirstNestedValue = $true
        foreach ($nestedValue in $Value) {
            if ($isFirstNestedValue) {
                $isFirstNestedValue = $false
            }
            else {
                [void]$buffer.Append(',')
            }

            if ($null -eq $nestedValue) {
                [void]$buffer.Append('null')
            }
            else {
                [void]$buffer.Append([string]$nestedValue)
            }
        }
        [void]$buffer.Append(']')
    }
    else {
        [void]$buffer.Append([string]$Value)
    }

    if ($buffer.Length -ge 131072) {
        $ColumnState.StreamWriter.Write($buffer.ToString())
        [void]$buffer.Clear()
    }
}

function Sync-CompactVulnColumnWriterSet {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterSet
    )

    foreach ($columnWriter in $WriterSet.Writers.Values) {
        if ($columnWriter.StreamWriter) {
            if ($columnWriter.Buffer.Length -gt 0) {
                $columnWriter.StreamWriter.Write($columnWriter.Buffer.ToString())
                [void]$columnWriter.Buffer.Clear()
            }
            $columnWriter.StreamWriter.Flush()
        }
    }
}

function Close-CompactVulnColumnWriterSet {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterSet
    )

    foreach ($columnWriter in $WriterSet.Writers.Values) {
        if ($columnWriter.StreamWriter) {
            if ($columnWriter.Buffer.Length -gt 0) {
                $columnWriter.StreamWriter.Write($columnWriter.Buffer.ToString())
                [void]$columnWriter.Buffer.Clear()
            }
            $columnWriter.StreamWriter.Write(']')
            $columnWriter.StreamWriter.Dispose()
            $columnWriter.StreamWriter = $null
        }
    }
}

function Read-CompactJsonReaderValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextReader]$Reader
    )

    switch ($Reader.TokenType) {
        ([Newtonsoft.Json.JsonToken]::Null) { return $null }
        ([Newtonsoft.Json.JsonToken]::Integer) { return $Reader.Value }
        ([Newtonsoft.Json.JsonToken]::Float) { return $Reader.Value }
        ([Newtonsoft.Json.JsonToken]::String) { return $Reader.Value }
        ([Newtonsoft.Json.JsonToken]::Boolean) { return $Reader.Value }
        ([Newtonsoft.Json.JsonToken]::StartArray) {
            $values = [System.Collections.Generic.List[object]]::new()
            while ($Reader.Read()) {
                if ($Reader.TokenType -eq [Newtonsoft.Json.JsonToken]::EndArray) {
                    break
                }

                $values.Add((Read-CompactJsonReaderValue -Reader $Reader))
            }

            return @($values)
        }
        default {
            throw "Unsupported JSON token '$($Reader.TokenType)' while reading compact vulnerability payload."
        }
    }
}

function Open-CompactJsonArrayReader {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    $streamReader = [System.IO.StreamReader]::new($resolvedPath, [System.Text.Encoding]::UTF8)
    $jsonReader = [Newtonsoft.Json.JsonTextReader]::new($streamReader)
    if (-not $jsonReader.Read() -or $jsonReader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartArray) {
        $jsonReader.Dispose()
        $streamReader.Dispose()
        throw "Expected JSON array in '$resolvedPath'."
    }

    return [PSCustomObject]@{
        Path = $resolvedPath
        StreamReader = $streamReader
        JsonReader = $jsonReader
    }
}

function Read-NextCompactJsonArrayValue {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ReaderState
    )

    $jsonReader = $ReaderState.JsonReader
    while ($jsonReader.Read()) {
        if ($jsonReader.TokenType -eq [Newtonsoft.Json.JsonToken]::EndArray) {
            return [PSCustomObject]@{
                HasValue = $false
                Value = $null
            }
        }

        return [PSCustomObject]@{
            HasValue = $true
            Value = (Read-CompactJsonReaderValue -Reader $jsonReader)
        }
    }

    throw "Unexpected end of compact JSON array '$($ReaderState.Path)'."
}

function Skip-JsonReaderValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextReader]$Reader
    )

    if ($Reader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartArray -and
        $Reader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartObject) {
        return
    }

    $depth = 1
    while ($depth -gt 0 -and $Reader.Read()) {
        switch ($Reader.TokenType) {
            ([Newtonsoft.Json.JsonToken]::StartArray) { $depth++ }
            ([Newtonsoft.Json.JsonToken]::StartObject) { $depth++ }
            ([Newtonsoft.Json.JsonToken]::EndArray) { $depth-- }
            ([Newtonsoft.Json.JsonToken]::EndObject) { $depth-- }
        }
    }
}

function Get-JsonReaderArrayElementCount {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextReader]$Reader,

        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if ($Reader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartArray) {
        throw "Expected JSON array in '$Path', found '$($Reader.TokenType)'."
    }

    $count = 0
    while ($Reader.Read()) {
        if ($Reader.TokenType -eq [Newtonsoft.Json.JsonToken]::EndArray) {
            break
        }

        Skip-JsonReaderValue -Reader $Reader
        $count++
    }

    return $count
}

function Get-PayloadVulnCountFromJsonReader {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextReader]$Reader,

        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if (-not $Reader.Read() -or $Reader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartObject) {
        throw "Expected JSON object payload in '$Path'."
    }

    $vulnsFormat = $null
    while ($Reader.Read()) {
        if ($Reader.TokenType -eq [Newtonsoft.Json.JsonToken]::EndObject) {
            break
        }

        if ($Reader.TokenType -ne [Newtonsoft.Json.JsonToken]::PropertyName) {
            continue
        }

        $propertyName = [string]$Reader.Value
        if (-not $Reader.Read()) {
            throw "Unexpected end of payload while reading '$Path'."
        }

        if ($propertyName -eq 'vulnsFormat') {
            $vulnsFormat = [string]$Reader.Value
            continue
        }

        if ($propertyName -ne 'vulns') {
            Skip-JsonReaderValue -Reader $Reader
            continue
        }

        if ($Reader.TokenType -eq [Newtonsoft.Json.JsonToken]::StartArray) {
            return (Get-JsonReaderArrayElementCount -Reader $Reader -Path $Path)
        }

        if ($Reader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartObject) {
            throw "Expected 'vulns' property in '$Path' to be an array or object, found '$($Reader.TokenType)'."
        }

        while ($Reader.Read()) {
            if ($Reader.TokenType -eq [Newtonsoft.Json.JsonToken]::EndObject) {
                break
            }

            if ($Reader.TokenType -ne [Newtonsoft.Json.JsonToken]::PropertyName) {
                continue
            }

            $columnName = [string]$Reader.Value
            if (-not $Reader.Read()) {
                throw "Unexpected end of payload while reading vuln columns in '$Path'."
            }

            if ($columnName -eq 'd') {
                return (Get-JsonReaderArrayElementCount -Reader $Reader -Path $Path)
            }

            Skip-JsonReaderValue -Reader $Reader
        }

        if ($vulnsFormat) {
            throw "Unable to locate vuln count column for payload format '$vulnsFormat' in '$Path'."
        }

        throw "Unable to locate vulnerability rows in '$Path'."
    }

    return 0
}

function Get-CompressedPayloadVulnCount {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $fileStream = $null
    $gzip = $null
    $reader = $null
    $jsonReader = $null

    try {
        $fileStream = [System.IO.File]::OpenRead($Path)
        $gzip = [System.IO.Compression.GZipStream]::new($fileStream, [System.IO.Compression.CompressionMode]::Decompress)
        $reader = [System.IO.StreamReader]::new($gzip, [System.Text.Encoding]::UTF8)
        $jsonReader = [Newtonsoft.Json.JsonTextReader]::new($reader)
        return (Get-PayloadVulnCountFromJsonReader -Reader $jsonReader -Path $Path)
    }
    finally {
        if ($jsonReader) { $jsonReader.Close() }
        elseif ($reader) { $reader.Dispose() }
        elseif ($gzip) { $gzip.Dispose() }
        elseif ($fileStream) { $fileStream.Dispose() }
    }
}

function Get-DashboardHtmlScriptContent {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Html,

        [Parameter(Mandatory = $true)]
        [string]$ScriptId
    )

    $pattern = '<script\s+id="' + [regex]::Escape($ScriptId) + '"[^>]*>(?<content>.*?)</script>'
    $match = [regex]::Match(
        $Html,
        $pattern,
        [System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor [System.Text.RegularExpressions.RegexOptions]::Singleline
    )

    if (-not $match.Success) {
        return ''
    }

    return $match.Groups['content'].Value.Trim()
}

function Write-DecodedBase64TextToStream {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Text,

        [Parameter(Mandatory = $true)]
        [ref]$Carry,

        [Parameter(Mandatory = $true)]
        [System.IO.Stream]$OutputStream
    )

    $cleanText = if ([string]::IsNullOrWhiteSpace($Text)) {
        ''
    }
    elseif ($Text.IndexOfAny(@([char]' ', [char]"`t", [char]"`r", [char]"`n")) -ge 0) {
        [regex]::Replace($Text, '\s+', '')
    }
    else {
        $Text
    }

    if ([string]::IsNullOrEmpty($cleanText) -and [string]::IsNullOrEmpty([string]$Carry.Value)) {
        return
    }

    $combined = ([string]$Carry.Value) + $cleanText
    $blockCharCount = 16384
    $fullCharCount = $combined.Length - ($combined.Length % 4)
    $offset = 0
    while ($offset -lt $fullCharCount) {
        $charsToDecode = [System.Math]::Min($blockCharCount, ($fullCharCount - $offset))
        if (($charsToDecode % 4) -ne 0) {
            $charsToDecode -= ($charsToDecode % 4)
        }

        $bytes = [System.Convert]::FromBase64String($combined.Substring($offset, $charsToDecode))
        $OutputStream.Write($bytes, 0, $bytes.Length)
        $offset += $charsToDecode
    }

    $Carry.Value = if ($fullCharCount -lt $combined.Length) {
        $combined.Substring($fullCharCount)
    }
    else {
        ''
    }
}

function Write-EmbeddedDashboardPayloadGzipFile {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath
    )

    $startMarker = '<script id="vulnsData" type="application/json">'
    $endMarker = '</script>'
    $reader = $null
    $inputStream = $null
    $outputStream = $null
    $startFound = $false
    $endFound = $false
    $carryText = ''
    $base64Carry = ''

    try {
        $inputStream = [System.IO.FileStream]::new(
            $HtmlPath,
            [System.IO.FileMode]::Open,
            [System.IO.FileAccess]::Read,
            [System.IO.FileShare]::Read,
            4096,
            [System.IO.FileOptions]::SequentialScan)
        $reader = [System.IO.StreamReader]::new($inputStream, [System.Text.UTF8Encoding]::new($false), $true, 65536, $false)
        $charBuffer = [char[]]::new(65536)

        while (($charsRead = $reader.Read($charBuffer, 0, $charBuffer.Length)) -gt 0) {
            $chunkText = $carryText + [string]::new($charBuffer, 0, $charsRead)
            $carryText = ''

            if (-not $startFound) {
                $startIndex = $chunkText.IndexOf($startMarker, [System.StringComparison]::Ordinal)
                if ($startIndex -lt 0) {
                    $overlapLength = [System.Math]::Min(($startMarker.Length - 1), $chunkText.Length)
                    if ($overlapLength -gt 0) {
                        $carryText = $chunkText.Substring($chunkText.Length - $overlapLength)
                    }
                    continue
                }

                $startFound = $true
                $outputStream = [System.IO.FileStream]::new(
                    $OutputPath,
                    [System.IO.FileMode]::Create,
                    [System.IO.FileAccess]::Write,
                    [System.IO.FileShare]::Read,
                    4096,
                    [System.IO.FileOptions]::SequentialScan)
                $chunkText = $chunkText.Substring($startIndex + $startMarker.Length)
            }

            $endIndex = $chunkText.IndexOf($endMarker, [System.StringComparison]::Ordinal)
            if ($endIndex -ge 0) {
                Write-DecodedBase64TextToStream -Text $chunkText.Substring(0, $endIndex) -Carry ([ref]$base64Carry) -OutputStream $outputStream
                $endFound = $true
                break
            }

            $overlapLength = [System.Math]::Min(($endMarker.Length - 1), $chunkText.Length)
            if ($chunkText.Length -gt $overlapLength) {
                Write-DecodedBase64TextToStream -Text $chunkText.Substring(0, ($chunkText.Length - $overlapLength)) -Carry ([ref]$base64Carry) -OutputStream $outputStream
            }
            if ($overlapLength -gt 0) {
                $carryText = $chunkText.Substring($chunkText.Length - $overlapLength)
            }
        }

        if ($startFound -and -not $endFound) {
            $endIndex = $carryText.IndexOf($endMarker, [System.StringComparison]::Ordinal)
            if ($endIndex -ge 0) {
                Write-DecodedBase64TextToStream -Text $carryText.Substring(0, $endIndex) -Carry ([ref]$base64Carry) -OutputStream $outputStream
                $endFound = $true
            }
        }

        if (-not $startFound) {
            return $false
        }

        if (-not $endFound) {
            throw "Unable to locate payload terminator in '$HtmlPath'."
        }

        if (-not [string]::IsNullOrEmpty($base64Carry)) {
            if (($base64Carry.Length % 4) -ne 0) {
                throw "Embedded payload base64 in '$HtmlPath' ended on an invalid boundary."
            }

            $bytes = [System.Convert]::FromBase64String($base64Carry)
            $outputStream.Write($bytes, 0, $bytes.Length)
        }

        if ($outputStream -and $outputStream.Length -le 0) {
            throw "Embedded payload in '$HtmlPath' is empty."
        }

        $outputStream.Flush()
        return $true
    }
    finally {
        if ($reader) {
            $reader.Dispose()
        }
        elseif ($inputStream) {
            $inputStream.Dispose()
        }

        if ($outputStream) {
            $outputStream.Dispose()
        }
    }
}

function Get-DashboardHtmlPrefixContent {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $false)]
        [ValidateRange(1024, 1048576)]
        [int]$MaxChars = 131072
    )

    $inputStream = $null
    $reader = $null
    try {
        $inputStream = [System.IO.FileStream]::new(
            $Path,
            [System.IO.FileMode]::Open,
            [System.IO.FileAccess]::Read,
            [System.IO.FileShare]::Read,
            4096,
            [System.IO.FileOptions]::SequentialScan)
        $reader = [System.IO.StreamReader]::new($inputStream, [System.Text.UTF8Encoding]::new($false), $true, 4096, $false)
        $buffer = [char[]]::new($MaxChars)
        $charsRead = $reader.Read($buffer, 0, $buffer.Length)
        if ($charsRead -le 0) {
            return ''
        }

        return [string]::new($buffer, 0, $charsRead)
    }
    finally {
        if ($reader) {
            $reader.Dispose()
        }
        elseif ($inputStream) {
            $inputStream.Dispose()
        }
    }
}

function Resolve-DashboardEmbeddedPayloadSource {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath
    )

    $resolvedPath = [System.IO.Path]::GetFullPath($HtmlPath)
    $metadataContent = Get-DashboardHtmlPrefixContent -Path $resolvedPath
    $dataFormat = Get-DashboardHtmlScriptContent -Html $metadataContent -ScriptId 'dataFormat'

    if ($dataFormat -eq 'external-compressed') {
        $dashboardConfigJson = Get-DashboardHtmlScriptContent -Html $metadataContent -ScriptId 'dashboardConfig'
        if ([string]::IsNullOrWhiteSpace($dashboardConfigJson)) {
            $metadataContent = [System.IO.File]::ReadAllText($resolvedPath, [System.Text.Encoding]::UTF8)
            $dashboardConfigJson = Get-DashboardHtmlScriptContent -Html $metadataContent -ScriptId 'dashboardConfig'
        }

        if ([string]::IsNullOrWhiteSpace($dashboardConfigJson)) {
            throw "Unable to locate dashboardConfig metadata in '$HtmlPath'."
        }

        $dashboardConfig = $dashboardConfigJson | ConvertFrom-Json -Depth 20
        $payloadUrl = [string]$dashboardConfig.payloadUrl
        if ([string]::IsNullOrWhiteSpace($payloadUrl)) {
            throw "dashboardConfig in '$HtmlPath' does not define payloadUrl."
        }

        $htmlDirectory = Split-Path -Path $resolvedPath -Parent
        $payloadRelativePath = $payloadUrl.Replace('/', '\')
        return [PSCustomObject]@{
            DataFormat = $dataFormat
            PayloadPath = [System.IO.Path]::GetFullPath((Join-Path $htmlDirectory $payloadRelativePath))
            DeleteAfterRead = $false
        }
    }

    $tempPayloadPath = Join-Path ([System.IO.Path]::GetTempPath()) ('dashboard-embedded-payload-' + [guid]::NewGuid().ToString('N') + '.json.gz')

    if (Write-EmbeddedDashboardPayloadGzipFile -HtmlPath $resolvedPath -OutputPath $tempPayloadPath) {
        return [PSCustomObject]@{
            DataFormat = 'compressed'
            PayloadPath = $tempPayloadPath
            DeleteAfterRead = $true
        }
    }

    if (Test-Path -LiteralPath $tempPayloadPath -PathType Leaf) {
        Remove-Item -LiteralPath $tempPayloadPath -Force -ErrorAction SilentlyContinue
    }

    if ([string]::IsNullOrWhiteSpace($dataFormat)) {
        $metadataContent = [System.IO.File]::ReadAllText($resolvedPath, [System.Text.Encoding]::UTF8)
        $dataFormat = Get-DashboardHtmlScriptContent -Html $metadataContent -ScriptId 'dataFormat'
    }

    if ($dataFormat -eq 'external-compressed') {
        $dashboardConfigJson = Get-DashboardHtmlScriptContent -Html $metadataContent -ScriptId 'dashboardConfig'
        if ([string]::IsNullOrWhiteSpace($dashboardConfigJson)) {
            throw "Unable to locate dashboardConfig metadata in '$HtmlPath'."
        }

        $dashboardConfig = $dashboardConfigJson | ConvertFrom-Json -Depth 20
        $payloadUrl = [string]$dashboardConfig.payloadUrl
        if ([string]::IsNullOrWhiteSpace($payloadUrl)) {
            throw "dashboardConfig in '$HtmlPath' does not define payloadUrl."
        }

        $htmlDirectory = Split-Path -Path $resolvedPath -Parent
        $payloadRelativePath = $payloadUrl.Replace('/', '\')
        return [PSCustomObject]@{
            DataFormat = $dataFormat
            PayloadPath = [System.IO.Path]::GetFullPath((Join-Path $htmlDirectory $payloadRelativePath))
            DeleteAfterRead = $false
        }
    }

    if ([string]::IsNullOrWhiteSpace($dataFormat) -or $dataFormat -eq 'compressed') {
        throw "Unable to locate embedded vulnerability payload in '$HtmlPath'."
    }

    throw "Unsupported dashboard payload format '$dataFormat' in '$HtmlPath'."
}

function Get-DashboardEmbeddedPayloadTempPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath
    )

    return [string](Resolve-DashboardEmbeddedPayloadSource -HtmlPath $HtmlPath).PayloadPath
}

function Get-DashboardEmbeddedPayloadInspection {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $payloadSource = Resolve-DashboardEmbeddedPayloadSource -HtmlPath $Path
    $payloadPath = [string]$payloadSource.PayloadPath

    try {
        return [PSCustomObject]@{
            DataFormat = [string]$payloadSource.DataFormat
            PayloadPath = $payloadPath
            PayloadRowCount = (Get-CompressedPayloadVulnCount -Path $payloadPath)
            PayloadSha256 = (Get-FileSha256Hex -Path $payloadPath)
        }
    }
    finally {
        if ($payloadSource -and $payloadSource.DeleteAfterRead -and -not [string]::IsNullOrWhiteSpace($payloadPath) -and (Test-Path -LiteralPath $payloadPath -PathType Leaf)) {
            Remove-Item -LiteralPath $payloadPath -Force -ErrorAction SilentlyContinue
        }
    }
}

function Get-EmbeddedDashboardPayloadVulnCount {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    return [int](Get-DashboardEmbeddedPayloadInspection -Path $Path).PayloadRowCount
}

function Get-DashboardPayloadGzipSha256 {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    return [string](Get-DashboardEmbeddedPayloadInspection -Path $Path).PayloadSha256
}

function Get-NormalizedAuditDecimalString {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    if ($null -eq $Value) {
        return ''
    }

    $raw = [string]$Value
    if ([string]::IsNullOrWhiteSpace($raw)) {
        return ''
    }

    [decimal]$decimalValue = 0
    if ([decimal]::TryParse($raw, [ref]$decimalValue)) {
        return $decimalValue.ToString('0.#####', [System.Globalization.CultureInfo]::InvariantCulture)
    }

    return $raw.Trim()
}

function ConvertTo-VulnColumnFileSet {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$VulnsPath,

        [Parameter(Mandatory = $true)]
        [hashtable]$ColumnWriters
    )

    $reader = $null
    $jsonReader = $null

    try {
        $reader = [System.IO.StreamReader]::new($VulnsPath, [System.Text.Encoding]::UTF8)
        $jsonReader = [Newtonsoft.Json.JsonTextReader]::new($reader)

        if (-not $jsonReader.Read() -or $jsonReader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartArray) {
            throw "Expected vulnerability payload '$VulnsPath' to start with a JSON array."
        }

        while ($jsonReader.Read()) {
            if ($jsonReader.TokenType -eq [Newtonsoft.Json.JsonToken]::EndArray) {
                break
            }

            if ($jsonReader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartArray) {
                throw "Expected compact vulnerability row array in '$VulnsPath', found '$($jsonReader.TokenType)'."
            }

            $rowValues = New-Object object[] 11
            for ($fieldIndex = 0; $fieldIndex -lt 11; $fieldIndex++) {
                if (-not $jsonReader.Read()) {
                    throw "Unexpected end of vulnerability payload '$VulnsPath'."
                }

                $rowValues[$fieldIndex] = Read-CompactJsonReaderValue -Reader $jsonReader
            }

            if (-not $jsonReader.Read() -or $jsonReader.TokenType -ne [Newtonsoft.Json.JsonToken]::EndArray) {
                throw "Expected end of compact vulnerability row array in '$VulnsPath'."
            }

            Write-CompactColumnFileValue -WriterState $ColumnWriters.d -Value $rowValues[0]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.c -Value $rowValues[1]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.s -Value $rowValues[2]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.v -Value $rowValues[3]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.f -Value $rowValues[4]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.l -Value $rowValues[5]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.ua -Value $rowValues[6]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.u -Value $rowValues[7]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.dp -Value $rowValues[8]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.rp -Value $rowValues[9]
            Write-CompactColumnFileValue -WriterState $ColumnWriters.iv -Value $rowValues[10]
        }
    }
    finally {
        if ($jsonReader) { $jsonReader.Close() }
        if ($reader) { $reader.Dispose() }
    }
}

function Get-CompactVulnJsonRowCount {
    [CmdletBinding()]
    [OutputType([int])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $reader = $null
    $jsonReader = $null
    $rowCount = 0

    try {
        $reader = [System.IO.StreamReader]::new($Path, [System.Text.Encoding]::UTF8)
        $jsonReader = [Newtonsoft.Json.JsonTextReader]::new($reader)

        if (-not $jsonReader.Read() -or $jsonReader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartArray) {
            throw "Expected compact vulnerability JSON '$Path' to start with a JSON array."
        }

        while ($jsonReader.Read()) {
            if ($jsonReader.TokenType -eq [Newtonsoft.Json.JsonToken]::EndArray) {
                break
            }

            if ($jsonReader.TokenType -ne [Newtonsoft.Json.JsonToken]::StartArray) {
                throw "Expected compact vulnerability row array in '$Path', found '$($jsonReader.TokenType)'."
            }

            Skip-JsonReaderValue -Reader $jsonReader
            $rowCount++
        }

        return $rowCount
    }
    finally {
        if ($jsonReader) { $jsonReader.Close() }
        if ($reader) { $reader.Dispose() }
    }
}

function Write-CombinedPayloadLookups {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextWriter]$Writer,

        [Parameter(Mandatory = $true)]
        [object]$Lookups,

        [Parameter(Mandatory = $false)]
        [switch]$ConsumeLookups
    )

    $Writer.WritePropertyName('lookups')
    Write-CombinedPayloadLookupsValue -Writer $Writer -Lookups $Lookups -ConsumeLookups:$ConsumeLookups
}

function Write-CombinedPayloadLookupsValue {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [Newtonsoft.Json.JsonTextWriter]$Writer,

        [Parameter(Mandatory = $true)]
        [object]$Lookups,

        [Parameter(Mandatory = $false)]
        [switch]$ConsumeLookups
    )

    $Writer.WriteStartObject()
    foreach ($lookupPropertyName in @(
            'vendors',
            'severities',
            'exploitLevels',
            'groups',
            'platforms',
            'tags',
            'updates',
            'versions',
            'dates',
            'diskPaths',
            'regPaths',
            'affSoftware',
            'batchTitles',
            'devices',
            'inventory',
            'software',
            'cves',
            'noTagsIdx'
        )) {
        $Writer.WritePropertyName($lookupPropertyName)
        if ($Lookups -is [System.Collections.IDictionary]) {
            $lookupValue = $Lookups[$lookupPropertyName]
        }
        else {
            $lookupValue = $Lookups.PSObject.Properties[$lookupPropertyName].Value
        }
        if ($lookupPropertyName -eq 'devices') {
            Write-NormalizedDeviceLookupsToWriter -Writer $Writer -Devices $lookupValue
        }
        else {
            Write-JsonValueToWriter -Writer $Writer -Value $lookupValue
        }

        if ($ConsumeLookups) {
            Set-NormalizedLookupPropertyValue -Lookups $Lookups -Name $lookupPropertyName -Value $null
            if ($lookupPropertyName -in @('devices', 'inventory', 'software', 'cves')) {
                Invoke-FullGarbageCollection
            }
        }
    }
    $Writer.WriteEndObject()
}

function Open-CombinedPayloadWriter {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $true)]
        [string]$VulnsFormat
    )

    $fileStream = $null
    $gzipStream = $null
    $writer = $null
    $jsonWriter = $null

    try {
        $fileStream = [System.IO.File]::Create($OutputPath)
        $gzipStream = [System.IO.Compression.GZipStream]::new($fileStream, [System.IO.Compression.CompressionLevel]::Fastest)
        $writer = [System.IO.StreamWriter]::new($gzipStream, [System.Text.UTF8Encoding]::new($false))
        $jsonWriter = [Newtonsoft.Json.JsonTextWriter]::new($writer)
        $jsonWriter.Formatting = [Newtonsoft.Json.Formatting]::None
        $jsonWriter.WriteStartObject()
        $jsonWriter.WritePropertyName('vulnsFormat')
        $jsonWriter.WriteValue($VulnsFormat)
        $jsonWriter.WritePropertyName('vulns')

        return [PSCustomObject]@{
            OutputPath = $OutputPath
            FileStream = $fileStream
            GzipStream = $gzipStream
            StreamWriter = $writer
            JsonWriter = $jsonWriter
        }
    }
    catch {
        if ($jsonWriter) { $jsonWriter.Close() }
        elseif ($writer) { $writer.Dispose() }
        elseif ($gzipStream) { $gzipStream.Dispose() }
        elseif ($fileStream) { $fileStream.Dispose() }
        throw
    }
}

function Close-CombinedPayloadWriter {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState,

        [Parameter(Mandatory = $true)]
        [object]$Lookups,

        [Parameter(Mandatory = $false)]
        [switch]$ConsumeLookups
    )

    try {
        Update-NormalizedAffectedSoftwareLookup -Lookups $Lookups
        Write-CombinedPayloadLookups -Writer $WriterState.JsonWriter -Lookups $Lookups -ConsumeLookups:$ConsumeLookups
        $WriterState.JsonWriter.WriteEndObject()
        $WriterState.JsonWriter.Flush()
    }
    finally {
        if ($WriterState.JsonWriter) { $WriterState.JsonWriter.Close() }
        elseif ($WriterState.StreamWriter) { $WriterState.StreamWriter.Dispose() }
        elseif ($WriterState.GzipStream) { $WriterState.GzipStream.Dispose() }
        elseif ($WriterState.FileStream) { $WriterState.FileStream.Dispose() }
    }
}

function Update-NormalizedAffectedSoftwareLookup {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Internal helper only mutates in-memory lookup data before serialization.')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Lookups
    )

    if ($null -eq $Lookups) {
        return
    }

    $vendors = $null
    $cves = $null
    $affSoftware = $null
    if ($Lookups -is [System.Collections.IDictionary]) {
        $vendors = $Lookups['vendors']
        $cves = $Lookups['cves']
        $affSoftware = $Lookups['affSoftware']
    }
    else {
        $vendors = $Lookups.PSObject.Properties['vendors']?.Value
        $cves = $Lookups.PSObject.Properties['cves']?.Value
        $affSoftware = $Lookups.PSObject.Properties['affSoftware']?.Value
    }

    if ($null -eq $vendors -or $null -eq $cves -or $null -eq $affSoftware) {
        return
    }

    $datasetVendors = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($vendor in @($vendors)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$vendor)) {
            [void]$datasetVendors.Add((Get-VendorMatchKey -Vendor $vendor))
        }
    }

    $affectedSoftwareLookupCount = @($affSoftware).Count
    foreach ($cve in @($cves)) {
        if ($null -eq $cve -or $null -eq $cve.as -or @($cve.as).Count -eq 0) {
            continue
        }

        $filteredIndices = [System.Collections.Generic.List[int]]::new()
        foreach ($asIdx in @($cve.as)) {
            $resolvedIndex = -1
            try {
                $resolvedIndex = [int]$asIdx
            }
            catch {
                continue
            }

            if ($resolvedIndex -lt 0 -or $resolvedIndex -ge $affectedSoftwareLookupCount) {
                continue
            }

            $swStr = [string]$affSoftware[$resolvedIndex]
            if ([string]::IsNullOrWhiteSpace($swStr)) {
                continue
            }

            $separatorIndex = $swStr.IndexOf(':')
            $swVendor = if ($separatorIndex -ge 0) { $swStr.Substring(0, $separatorIndex) } else { $swStr }
            if ($datasetVendors.Contains((Get-VendorMatchKey -Vendor $swVendor))) {
                $filteredIndices.Add($resolvedIndex)
            }
        }

        $cve.as = if ($filteredIndices.Count -gt 0) { $filteredIndices } else { $null }
    }
}

function Open-NormalizedVulnWriter {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $false)]
        [string]$VulnOutputPath,

        [Parameter(Mandatory = $false)]
        [string]$VulnColumnDirectoryPath,

        [Parameter(Mandatory = $false)]
        [string]$PayloadOutputPath
    )

    if (-not [string]::IsNullOrWhiteSpace($PayloadOutputPath)) {
        $payloadWriter = Open-CombinedPayloadWriter -OutputPath $PayloadOutputPath -VulnsFormat 'rows-v1'
        $payloadWriter.JsonWriter.WriteStartArray()
        return [PSCustomObject]@{
            Mode = 'payload'
            JsonWriter = $payloadWriter.JsonWriter
            PayloadWriter = $payloadWriter
            PayloadPath = $PayloadOutputPath
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($VulnColumnDirectoryPath)) {
        $columnWriterSet = Open-CompactVulnColumnWriterSet -DirectoryPath $VulnColumnDirectoryPath
        return [PSCustomObject]@{
            Mode = 'column'
            ColumnWriterSet = $columnWriterSet
            VulnColumnPaths = $columnWriterSet.Paths
        }
    }

    $vulnWriter = [System.IO.StreamWriter]::new($VulnOutputPath, $false, [System.Text.UTF8Encoding]::new($false))
    $jsonWriter = [Newtonsoft.Json.JsonTextWriter]::new($vulnWriter)
    $jsonWriter.Formatting = [Newtonsoft.Json.Formatting]::None
    $jsonWriter.WriteStartArray()
    return [PSCustomObject]@{
        Mode = 'rows'
        JsonWriter = $jsonWriter
        VulnWriter = $vulnWriter
        VulnsPath = $VulnOutputPath
    }
}

function Write-NormalizedCompactRecord {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState,

        [Parameter(Mandatory = $true)]
        [object]$Record
    )

    if ($WriterState.Mode -eq 'column') {
        Write-CompactVulnRecordColumnSet -WriterSet $WriterState.ColumnWriterSet -Record $Record
        return
    }

    Write-CompactVulnRecordJson -Writer $WriterState.JsonWriter -Record $Record
}

function Sync-NormalizedVulnWriter {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState
    )

    if ($WriterState.Mode -eq 'column') {
        Sync-CompactVulnColumnWriterSet -WriterSet $WriterState.ColumnWriterSet
        return
    }

    if ($WriterState.JsonWriter) {
        $WriterState.JsonWriter.Flush()
    }
}

function Close-NormalizedVulnWriter {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$WriterState,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [object]$Lookups,

        [Parameter(Mandatory = $false)]
        [switch]$ConsumeLookups
    )

    if ($WriterState.Mode -eq 'column') {
        Sync-CompactVulnColumnWriterSet -WriterSet $WriterState.ColumnWriterSet
        Close-CompactVulnColumnWriterSet -WriterSet $WriterState.ColumnWriterSet
        return [PSCustomObject]@{
            Mode = 'column'
            VulnsPath = $null
            VulnColumnPaths = $WriterState.VulnColumnPaths
            PayloadPath = $null
        }
    }

    if ($WriterState.Mode -eq 'payload') {
        $WriterState.JsonWriter.WriteEndArray()
        Close-CombinedPayloadWriter -WriterState $WriterState.PayloadWriter -Lookups $Lookups -ConsumeLookups:$ConsumeLookups
        return [PSCustomObject]@{
            Mode = 'payload'
            VulnsPath = $null
            VulnColumnPaths = $null
            PayloadPath = $WriterState.PayloadPath
        }
    }

    try {
        $WriterState.JsonWriter.WriteEndArray()
        $WriterState.JsonWriter.Flush()
    }
    finally {
        if ($WriterState.JsonWriter) {
            $WriterState.JsonWriter.Close()
        }
        if ($WriterState.VulnWriter) {
            $WriterState.VulnWriter.Dispose()
        }
    }

    return [PSCustomObject]@{
        Mode = 'rows'
        VulnsPath = $WriterState.VulnsPath
        VulnColumnPaths = $null
        PayloadPath = $null
    }
}

function Write-CombinedPayloadGzip {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [object]$Lookups,

        [Parameter(Mandatory = $false)]
        [string]$VulnsPath,

        [Parameter(Mandatory = $false)]
        [hashtable]$VulnColumnPaths,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $false)]
        [switch]$ConsumeLookups
    )

    $payloadWriter = $null
    $columnReaders = [System.Collections.Generic.List[System.IDisposable]]::new()
    $jsonWriter = $null
    $activeColumnPaths = $null

    try {
        $payloadWriter = Open-CombinedPayloadWriter -OutputPath $OutputPath -VulnsFormat $(if ($VulnColumnPaths) { 'columns-v1' } else { 'rows-v1' })
        $jsonWriter = $payloadWriter.JsonWriter

        if ($VulnColumnPaths) {
            $activeColumnPaths = $VulnColumnPaths
            $jsonWriter.WriteStartObject()
            foreach ($columnName in @('d', 'c', 's', 'v', 'f', 'l', 'ua', 'u', 'dp', 'rp', 'iv')) {
                $jsonWriter.WritePropertyName($columnName)
                $columnReader = [System.IO.StreamReader]::new([string]$activeColumnPaths[$columnName], [System.Text.Encoding]::UTF8)
                $columnJsonReader = [Newtonsoft.Json.JsonTextReader]::new($columnReader)
                [void]$columnReaders.Add($columnJsonReader)
                [void]$columnReaders.Add($columnReader)
                $jsonWriter.WriteToken($columnJsonReader)
            }
            $jsonWriter.WriteEndObject()
        }
        else {
            if ([string]::IsNullOrWhiteSpace($VulnsPath) -or -not (Test-Path -LiteralPath $VulnsPath -PathType Leaf)) {
                throw 'Write-CombinedPayloadGzip requires either -VulnsPath or -VulnColumnPaths.'
            }

            $vulnsReader = [System.IO.StreamReader]::new($VulnsPath, [System.Text.Encoding]::UTF8)
            $vulnsJsonReader = [Newtonsoft.Json.JsonTextReader]::new($vulnsReader)
            [void]$columnReaders.Add($vulnsJsonReader)
            [void]$columnReaders.Add($vulnsReader)
            $jsonWriter.WriteToken($vulnsJsonReader)
        }

        Close-CombinedPayloadWriter -WriterState $payloadWriter -Lookups $Lookups -ConsumeLookups:$ConsumeLookups
        $payloadWriter = $null
    }
    finally {
        foreach ($columnDisposable in $columnReaders) {
            $columnDisposable.Dispose()
        }
        if ($payloadWriter) {
            Close-CombinedPayloadWriter -WriterState $payloadWriter -Lookups $Lookups
        }
    }
}

function Write-TemplatedHtml {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Template,

        [Parameter(Mandatory = $true)]
        [array]$Segments,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $false)]
        [switch]$InsertBase64LineBreaks
    )

    $writer = $null
    $outputStream = $null
    try {
        $outputStream = [System.IO.FileStream]::new(
            $OutputPath,
            [System.IO.FileMode]::Create,
            [System.IO.FileAccess]::Write,
            [System.IO.FileShare]::Read,
            4096,
            [System.IO.FileOptions]::WriteThrough)
        $writer = [System.IO.StreamWriter]::new($outputStream, [System.Text.UTF8Encoding]::new($false), 4096, $false)
        $position = 0
        foreach ($segment in $Segments) {
            $placeholder = $segment.Placeholder
            $index = $Template.IndexOf($placeholder, $position, [System.StringComparison]::Ordinal)
            if ($index -lt 0) {
                throw "Template placeholder not found: $placeholder"
            }

            $writer.Write($Template.Substring($position, $index - $position))
            if ($segment.ContainsKey('Base64FilePath')) {
                Write-Base64FileContent -Writer $writer -FilePath $segment.Base64FilePath -InsertLineBreaks:$InsertBase64LineBreaks
            }
            elseif ($segment.ContainsKey('FilePath')) {
                $writer.Write([System.IO.File]::ReadAllText([string]$segment.FilePath, [System.Text.Encoding]::UTF8))
            }
            else {
                $writer.Write([string]$segment.Value)
            }

            $position = $index + $placeholder.Length
        }

        $writer.Write($Template.Substring($position))
    }
    finally {
        if ($writer) {
            $writer.Dispose()
        }
        elseif ($outputStream) {
            $outputStream.Dispose()
        }
    }
}

function Write-Utf8File {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Content
    )

    [System.IO.File]::WriteAllText($Path, $Content, [System.Text.UTF8Encoding]::new($false))
}

function Get-DashboardAssetsDirectoryPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath
    )

    $resolvedHtmlPath = [System.IO.Path]::GetFullPath($HtmlPath)
    $parentPath = Split-Path -Path $resolvedHtmlPath -Parent
    $assetsDirectoryName = ([System.IO.Path]::GetFileNameWithoutExtension($resolvedHtmlPath) + '.assets')
    return (Join-Path $parentPath $assetsDirectoryName)
}

function Get-DashboardAssetsDirectoryName {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath
    )

    return ([System.IO.Path]::GetFileNameWithoutExtension([System.IO.Path]::GetFullPath($HtmlPath)) + '.assets')
}

function Get-DashboardAssetUrl {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath,

        [Parameter(Mandatory = $true)]
        [string]$AssetFileName
    )

    return ((Get-DashboardAssetsDirectoryName -HtmlPath $HtmlPath) + '/' + $AssetFileName)
}

function Write-DashboardArtifactBundle {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$TemplateHtml,

        [Parameter(Mandatory = $true)]
        [string]$TemplateCss,

        [Parameter(Mandatory = $true)]
        [string]$TemplateJs,

        [Parameter(Mandatory = $true)]
        [string]$PakoLibraryPath,

        [Parameter(Mandatory = $true)]
        [string]$ChartJsLibraryPath,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$ChartJsBundlePath,

        [Parameter(Mandatory = $true)]
        [string]$PdfExportBundleSourcePath,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$PdfExportBundlePath,

        [Parameter(Mandatory = $true)]
        [string]$PayloadPath,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$LookupsJsonEscaped = '',

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$DataQualitySectionHtml = '',

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$DataQualityMetaScript = '',

        [Parameter(Mandatory = $false)]
        [bool]$SplitAssets = $false,

        [Parameter(Mandatory = $false)]
        [bool]$InsertBase64LineBreaks = $false
    )

    if (-not $SplitAssets) {
        if ([string]::IsNullOrWhiteSpace($ChartJsBundlePath) -or -not (Test-Path -LiteralPath $ChartJsBundlePath -PathType Leaf)) {
            throw 'Write-DashboardArtifactBundle requires ChartJsBundlePath when SplitAssets is false.'
        }

        if ([string]::IsNullOrWhiteSpace($PdfExportBundlePath) -or -not (Test-Path -LiteralPath $PdfExportBundlePath -PathType Leaf)) {
            throw 'Write-DashboardArtifactBundle requires PdfExportBundlePath when SplitAssets is false.'
        }
    }

    $dataFormatMarker = if ($SplitAssets) { 'external-compressed' } else { 'compressed' }
    $dashboardAssetsConfig = [ordered]@{
        deliveryMode = if ($SplitAssets) { 'split-assets' } else { 'self-contained' }
        chartJsMode = if ($SplitAssets) { 'external' } else { 'embedded' }
        pdfExportBundleMode = if ($SplitAssets) { 'external' } else { 'embedded' }
        debugLogging = $false
    }

    $cssBlock = $null
    $pakoBlock = $null
    $dashboardJsBlock = $null
    $vulnsDataSegment = $null
    $chartJsSegment = $null
    $pdfExportBundleSegment = $null
    $dashboardAssetsPath = $null

    if ($SplitAssets) {
        $dashboardAssetsPath = Get-DashboardAssetsDirectoryPath -HtmlPath $OutputPath
        [void](New-Item -Path $dashboardAssetsPath -ItemType Directory -Force)

        $cssAssetFileName = 'dashboard.css'
        $jsAssetFileName = 'dashboard.js'
        $pakoAssetFileName = 'pako.js'
        $chartJsAssetFileName = 'chart.js'
        $pdfBundleAssetFileName = 'pdf-export.bundle.js'
        $payloadAssetFileName = 'payload.json.gz'

        $cssAssetPath = Join-Path $dashboardAssetsPath $cssAssetFileName
        $jsAssetPath = Join-Path $dashboardAssetsPath $jsAssetFileName
        $pakoAssetPath = Join-Path $dashboardAssetsPath $pakoAssetFileName
        $chartJsAssetPath = Join-Path $dashboardAssetsPath $chartJsAssetFileName
        $pdfBundleAssetPath = Join-Path $dashboardAssetsPath $pdfBundleAssetFileName
        $payloadAssetPath = Join-Path $dashboardAssetsPath $payloadAssetFileName

        Write-Utf8File -Path $cssAssetPath -Content $TemplateCss
        Write-Utf8File -Path $jsAssetPath -Content $TemplateJs
        Copy-Item -LiteralPath $PakoLibraryPath -Destination $pakoAssetPath -Force
        Copy-Item -LiteralPath $ChartJsLibraryPath -Destination $chartJsAssetPath -Force
        Copy-Item -LiteralPath $PdfExportBundleSourcePath -Destination $pdfBundleAssetPath -Force
        Copy-Item -LiteralPath $PayloadPath -Destination $payloadAssetPath -Force

        $dashboardAssetsConfig.payloadUrl = Get-DashboardAssetUrl -HtmlPath $OutputPath -AssetFileName $payloadAssetFileName
        $dashboardAssetsConfig.chartJsUrl = Get-DashboardAssetUrl -HtmlPath $OutputPath -AssetFileName $chartJsAssetFileName
        $dashboardAssetsConfig.pdfExportBundleUrl = Get-DashboardAssetUrl -HtmlPath $OutputPath -AssetFileName $pdfBundleAssetFileName

        $cssBlock = '<link rel="stylesheet" href="' + (Get-DashboardAssetUrl -HtmlPath $OutputPath -AssetFileName $cssAssetFileName) + '">'
        $pakoBlock = '<script src="' + (Get-DashboardAssetUrl -HtmlPath $OutputPath -AssetFileName $pakoAssetFileName) + '"></script>'
        $dashboardJsBlock = '<script src="' + (Get-DashboardAssetUrl -HtmlPath $OutputPath -AssetFileName $jsAssetFileName) + '"></script>'
        $vulnsDataSegment = @{ Placeholder = '__VULNS_DATA__'; Value = '' }
        $chartJsSegment = @{ Placeholder = '__CHARTJS_CONTENT__'; Value = '' }
        $pdfExportBundleSegment = @{ Placeholder = '__PDF_EXPORT_BUNDLE_CONTENT__'; Value = '' }
    }
    else {
        $cssBlock = "<style>`r`n$TemplateCss`r`n    </style>"
        $pakoBlock = "<script>`r`n$(Get-Content -LiteralPath $PakoLibraryPath -Raw)`r`n    </script>"
        $dashboardJsBlock = "<script>`r`n$TemplateJs`r`n    </script>"
        $vulnsDataSegment = @{ Placeholder = '__VULNS_DATA__'; Base64FilePath = $PayloadPath }
        $chartJsSegment = @{ Placeholder = '__CHARTJS_CONTENT__'; Base64FilePath = $ChartJsBundlePath }
        $pdfExportBundleSegment = @{ Placeholder = '__PDF_EXPORT_BUNDLE_CONTENT__'; Base64FilePath = $PdfExportBundlePath }
    }

    $dashboardConfigJson = $dashboardAssetsConfig | ConvertTo-Json -Compress -Depth 20
    $segments = @(
        @{ Placeholder = '__CSS_BLOCK__'; Value = $cssBlock },
        @{ Placeholder = '__DATA_QUALITY_SECTION__'; Value = $DataQualitySectionHtml },
        @{ Placeholder = '__PAKO_BLOCK__'; Value = $pakoBlock },
        @{ Placeholder = '__DASHBOARD_CONFIG__'; Value = $dashboardConfigJson },
        @{ Placeholder = '__DATA_FORMAT__'; Value = $dataFormatMarker },
        @{ Placeholder = '__DATA_QUALITY_META_SCRIPT__'; Value = $DataQualityMetaScript },
        @{ Placeholder = '__LOOKUPS_DATA__'; Value = $LookupsJsonEscaped },
        $vulnsDataSegment,
        $chartJsSegment,
        $pdfExportBundleSegment,
        @{ Placeholder = '__DASHBOARD_JS_BLOCK__'; Value = $dashboardJsBlock }
    )

    Write-TemplatedHtml -Template $TemplateHtml -Segments $segments -OutputPath $OutputPath -InsertBase64LineBreaks:$InsertBase64LineBreaks

    return [PSCustomObject]@{
        OutputPath = $OutputPath
        AssetsPath = $dashboardAssetsPath
        DataFormat = $dataFormatMarker
        DeliveryMode = [string]$dashboardAssetsConfig.deliveryMode
    }
}

function Read-MachineData {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $false)]
        [switch]$AsNormalizationTuple
    )

    $asNormalizationTupleRequested = [bool]$AsNormalizationTuple
    $machineRecordReader = {
        param(
            [Parameter(Mandatory = $true)]
            [string]$SourcePath
        )

        if ($asNormalizationTupleRequested) {
            Read-MachineNormalizationEntriesFromFile -Path $SourcePath
        }
        else {
            Read-MachineRecordsFromFile -Path $SourcePath
        }
    }

    return Invoke-WithStoreLock -BasePath $Path -StoreName 'machines' -ScriptBlock {
        Restore-StoreTransaction -BasePath $Path -StoreName 'machines'

        Write-Information "Reading machine data from $Path..." -InformationAction Continue
        $machines = @{}

        $currentPath = Get-MachineCurrentPath -BasePath $Path
        $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath
        $currentReadPath = if (Test-Path -Path $currentPath) { $currentPath } elseif (Test-Path -Path $legacyCurrentPath) { $legacyCurrentPath } else { $null }
        $historySourcePaths = @(Get-MachineHistorySourcePaths -BasePath $Path)

        if ($null -ne $currentReadPath) {
            Write-Information "  Using $(Split-Path -Leaf $currentReadPath)" -InformationAction Continue
            foreach ($record in (& $machineRecordReader $currentReadPath)) {
                if ($record.id) {
                    if ($record.PSObject.Properties['removed']?.Value -eq $true) {
                        $machines.Remove($record.id)
                        continue
                    }
                    $machineRecord = if ($asNormalizationTupleRequested) { $record.PSObject.Properties['tuple']?.Value } else { ConvertTo-CompactMachineRecord -Machine $record }
                    if ($null -eq $machineRecord) {
                        $machines.Remove($record.id)
                        continue
                    }
                    $machines[$record.id] = $machineRecord
                }
            }
        }
        elseif ($historySourcePaths.Count -gt 0) {
            Write-Information "  Reconstructing current state from $($historySourcePaths.Count) machine history source file(s)" -InformationAction Continue
            foreach ($sourcePath in $historySourcePaths) {
                foreach ($record in (& $machineRecordReader $sourcePath)) {
                    if ($record.id) {
                        if ($record.PSObject.Properties['removed']?.Value -eq $true) {
                            $machines.Remove($record.id)
                            continue
                        }
                        $machineRecord = if ($asNormalizationTupleRequested) { $record.PSObject.Properties['tuple']?.Value } else { ConvertTo-CompactMachineRecord -Machine $record }
                        if ($null -eq $machineRecord) {
                            $machines.Remove($record.id)
                            continue
                        }
                        $machines[$record.id] = $machineRecord
                    }
                }
            }
        }
        else {
            $machineFiles = @(Get-ChildItem -Path $Path -Filter 'Machines_*.json' -File | Where-Object { Test-IsLegacyMachineSnapshotFileName -Name $_.Name } | Sort-Object Name -Descending)

            if ($machineFiles.Count -eq 0) {
                Write-Warning 'No machine data files found. Device details may be incomplete.'
                return @{}
            }

            Write-Information "  Found $($machineFiles.Count) legacy machine snapshot file(s)" -InformationAction Continue
            foreach ($file in $machineFiles) {
                Write-Information "  Processing $($file.Name)..." -InformationAction Continue
                foreach ($record in (& $machineRecordReader $file.FullName)) {
                    if ($record.id -and -not $machines.ContainsKey($record.id)) {
                        $machineRecord = if ($asNormalizationTupleRequested) { $record.PSObject.Properties['tuple']?.Value } else { ConvertTo-CompactMachineRecord -Machine $record }
                        if ($null -ne $machineRecord) {
                            $machines[$record.id] = $machineRecord
                        }
                    }
                }
            }
        }

        Write-Information "  Loaded $($machines.Count) unique machines" -InformationAction Continue
        return $machines
    }
}

function Read-NormalizationMachineLookup {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    return (Read-MachineData -Path $Path -AsNormalizationTuple)
}

function Get-DashboardCacheDirectory {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [string]$ChildPath,

        [Parameter(Mandatory = $false)]
        [switch]$Create
    )

    $cachePath = Join-Path $BasePath '.dashboard-cache'
    if (-not [string]::IsNullOrWhiteSpace($ChildPath)) {
        $cachePath = Join-Path $cachePath $ChildPath
    }

    if ($Create) {
        [void](New-Item -Path $cachePath -ItemType Directory -Force)
    }

    return $cachePath
}

function Get-FileSha256Hex {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    $fileStream = $null
    $sha256 = $null
    try {
        $fileStream = [System.IO.File]::OpenRead($Path)
        $sha256 = [System.Security.Cryptography.SHA256]::Create()
        $hashBytes = $sha256.ComputeHash($fileStream)
        return ([System.BitConverter]::ToString($hashBytes)).Replace('-', '').ToLowerInvariant()
    }
    finally {
        if ($sha256) { $sha256.Dispose() }
        if ($fileStream) { $fileStream.Dispose() }
    }
}

function Get-FileSetFingerprint {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Version,

        [Parameter(Mandatory = $true)]
        [System.IO.FileInfo[]]$Files,

        [Parameter(Mandatory = $false)]
        [string[]]$MetadataLines,

        [Parameter(Mandatory = $false)]
        [ValidateSet('FullName', 'Name')]
        [string]$FileIdentityProperty = 'FullName'
    )

    $uniqueFiles = @($Files | Where-Object { $null -ne $_ } | Sort-Object FullName -Unique)
    if ($uniqueFiles.Count -eq 0) {
        return $null
    }

    $builder = [System.Text.StringBuilder]::new()
    [void]$builder.AppendLine($Version)
    foreach ($line in @($MetadataLines)) {
        [void]$builder.AppendLine([string]$line)
    }

    foreach ($file in $uniqueFiles) {
        $hash = Get-FileSha256Hex -Path $file.FullName
        $fileIdentity = if ($FileIdentityProperty -eq 'Name') { $file.Name } else { $file.FullName }
        [void]$builder.Append($fileIdentity).Append('|')
        [void]$builder.Append($file.Length).Append('|')
        [void]$builder.AppendLine($hash)
    }

    $fingerprintBytes = [System.Text.Encoding]::UTF8.GetBytes($builder.ToString())
    $fingerprintHash = [System.Security.Cryptography.SHA256]::HashData($fingerprintBytes)
    return ([System.BitConverter]::ToString($fingerprintHash)).Replace('-', '').ToLowerInvariant()
}

function Sync-VulnContentStoreSidecar {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    if (Test-VulnContentStoreExistence -BasePath $BasePath) {
        return $true
    }

    if (-not (Test-VulnStoreExistence -BasePath $BasePath)) {
        return $false
    }

    try {
        Invoke-WithStoreLock -BasePath $BasePath -StoreName 'vuln' -ScriptBlock {
            Restore-StoreTransaction -BasePath $BasePath -StoreName 'vuln'

            if (-not (Test-VulnContentStoreExistence -BasePath $BasePath)) {
                Write-Information '  Rebuilding content-store sidecars from raw vulnerability store...' -InformationAction Continue
                Publish-VulnContentStoreUnlocked -BasePath $BasePath
            }
        } | Out-Null
    }
    catch {
        Write-Verbose "Vulnerability content sidecar rebuild failed; falling back to raw/object normalization. $_"
    }

    return (Test-VulnContentStoreExistence -BasePath $BasePath)
}

function Get-VulnObservedWindowCacheFingerprint {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [ValidateRange(0, 30)]
        [int]$AllowedGapDays = 1
    )

    $sourceFiles = [System.Collections.Generic.List[System.IO.FileInfo]]::new()
    $contentStoreExists = Sync-VulnContentStoreSidecar -BasePath $BasePath
    if ($contentStoreExists) {
        foreach ($path in @(
                (Get-VulnContentDictionaryPath -BasePath $BasePath)
                (Get-VulnCurrentRefsPath -BasePath $BasePath)
            )) {
            if (Test-Path -LiteralPath $path -PathType Leaf) {
                $sourceFiles.Add((Get-Item -LiteralPath $path))
            }
        }

        foreach ($historyRefsFile in @(Get-ChildItem -Path $BasePath -Filter 'VulnHistoryRefs_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
            $sourceFiles.Add($historyRefsFile)
        }
    }
    else {
        $currentPath = Get-VulnCurrentPath -BasePath $BasePath
        if (Test-Path -LiteralPath $currentPath -PathType Leaf) {
            $sourceFiles.Add((Get-Item -LiteralPath $currentPath))
        }

        foreach ($historyRowsFile in @(Get-ChildItem -Path $BasePath -Filter 'VulnHistoryRows_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
            $sourceFiles.Add($historyRowsFile)
        }
    }

    if ($sourceFiles.Count -eq 0) {
        return $null
    }

    return (Get-FileSetFingerprint -Version 'observed-window-cache-v2' -Files @($sourceFiles) -MetadataLines @(
            ('AllowedGapDays=' + $AllowedGapDays)
            ('CacheShape=' + $(if ($contentStoreExists) { 'compact-ref-array-v1' } else { 'row-object-v1' }))
        ) -FileIdentityProperty Name)
}

function Get-VulnObservedWindowCachePath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $true)]
        [string]$Fingerprint,

        [Parameter(Mandatory = $false)]
        [ValidateRange(0, 30)]
        [int]$AllowedGapDays = 1,

        [Parameter(Mandatory = $false)]
        [switch]$Create
    )

    $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'observed-windows' -Create:$Create
    return Join-Path $cacheDirectory ("gap{0}-{1}.json.gz" -f $AllowedGapDays, $Fingerprint)
}

function Clear-StaleVulnObservedWindowCache {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [string]$KeepPath
    )

    $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'observed-windows'
    if (-not (Test-Path -LiteralPath $cacheDirectory -PathType Container)) {
        return
    }

    $normalizedKeepPath = if ([string]::IsNullOrWhiteSpace($KeepPath)) {
        $null
    }
    else {
        [System.IO.Path]::GetFullPath($KeepPath)
    }

    foreach ($cacheFile in @(Get-ChildItem -Path $cacheDirectory -Filter '*.json.gz' -File -ErrorAction SilentlyContinue)) {
        if ($normalizedKeepPath -and ([System.StringComparer]::OrdinalIgnoreCase.Equals($cacheFile.FullName, $normalizedKeepPath))) {
            continue
        }

        Remove-Item -LiteralPath $cacheFile.FullName -Force -ErrorAction SilentlyContinue
    }
}

function Write-MergedVulnContentStoreRefs {
    <#
    .SYNOPSIS
    Memory-efficient observed-window merge that operates on compact content-store
    ref arrays instead of fully-expanded PSCustomObjects. Each ref is a 5-element
    array [Id, DeviceProfileIdx, ContentTemplateIdx, FST, LST] — roughly 30x
    smaller per row than expanded objects.
    #>
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '')]
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [ValidateRange(0, 30)]
        [int]$AllowedGapDays = 1,

        [Parameter(Mandatory = $false)]
        [ValidateRange(4, 256)]
        [int]$PartitionCount = 128
    )

    # Collect ref file paths
    $refPaths = [System.Collections.Generic.List[string]]::new()
    $currentRefsPath = Get-VulnCurrentRefsPath -BasePath $BasePath
    if (Test-Path -LiteralPath $currentRefsPath -PathType Leaf) {
        $refPaths.Add($currentRefsPath)
    }
    foreach ($historyRefsFile in @(Get-ChildItem -Path $BasePath -Filter 'VulnHistoryRefs_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
        $refPaths.Add($historyRefsFile.FullName)
    }

    if ($refPaths.Count -eq 0) { return }

    $partitionDir = Join-Path ([System.IO.Path]::GetTempPath()) ('owref-' + [System.Guid]::NewGuid().ToString('N'))
    [void](New-Item -ItemType Directory -Path $partitionDir -Force)

    $partitionWriters = [System.IO.StreamWriter[]]::new($PartitionCount)

    try {
        # Pass 1 — scatter raw ref lines to partition files by identity hash.
        # Use .NET StreamReader directly to avoid PowerShell pipeline buffering
        # that would materialize all 1.5M+ lines in memory at once.
        foreach ($refPath in $refPaths) {
            $refFileStream = [System.IO.File]::OpenRead($refPath)
            $refGzipStream = if ($refPath.EndsWith('.gz', [System.StringComparison]::OrdinalIgnoreCase)) {
                [System.IO.Compression.GZipStream]::new($refFileStream, [System.IO.Compression.CompressionMode]::Decompress)
            } else { $refFileStream }
            $refReader = [System.IO.StreamReader]::new($refGzipStream, [System.Text.UTF8Encoding]::new($false))
            try {
                while ($null -ne ($line = $refReader.ReadLine())) {
                    if ([string]::IsNullOrWhiteSpace($line)) { continue }

                # Fast Id extraction: ref lines are JSON arrays ["id",...
                $firstQuote = $line.IndexOf('"')
                if ($firstQuote -lt 0) { continue }
                $secondQuote = $line.IndexOf('"', $firstQuote + 1)
                if ($secondQuote -lt 0) { continue }
                $identityKey = $line.Substring($firstQuote + 1, $secondQuote - $firstQuote - 1)

                $hash = [uint32]([int64]$identityKey.GetHashCode() -band 0xFFFFFFFFL)
                $bucket = [int]($hash % [uint32]$PartitionCount)

                if ($null -eq $partitionWriters[$bucket]) {
                    $partPath = Join-Path $partitionDir "p$bucket.ndjson"
                    $partitionWriters[$bucket] = [System.IO.StreamWriter]::new(
                        [System.IO.File]::Create($partPath),
                        [System.Text.UTF8Encoding]::new($false))
                }
                $partitionWriters[$bucket].WriteLine($line)
                }
            }
            finally {
                $refReader.Dispose()
                if ($refGzipStream -ne $refFileStream) { $refGzipStream.Dispose() }
                $refFileStream.Dispose()
            }
        }

        for ($i = 0; $i -lt $PartitionCount; $i++) {
            if ($null -ne $partitionWriters[$i]) {
                $partitionWriters[$i].Dispose()
                $partitionWriters[$i] = $null
            }
        }

        # Pass 2 — gather: process each partition, merge refs by Id
        for ($bucket = 0; $bucket -lt $PartitionCount; $bucket++) {
            $partPath = Join-Path $partitionDir "p$bucket.ndjson"
            if (-not (Test-Path -LiteralPath $partPath -PathType Leaf)) { continue }

            $refsByIdentity = @{}
            foreach ($line in [System.IO.File]::ReadLines($partPath, [System.Text.UTF8Encoding]::new($false))) {
                if ([string]::IsNullOrWhiteSpace($line)) { continue }
                # Parse ref array via System.Text.Json (faster than ConvertFrom-Json)
                $doc = [System.Text.Json.JsonDocument]::Parse($line)
                try {
                    $arr = $doc.RootElement
                    $ref = @(
                        $arr[0].GetString()         # Id
                        $arr[1].GetInt32()           # DeviceProfileIdx
                        $arr[2].GetInt32()           # ContentTemplateIdx
                        $(if ($arr[3].ValueKind -eq [System.Text.Json.JsonValueKind]::Null) { $null } else { $arr[3].GetString() })  # FST
                        $(if ($arr[4].ValueKind -eq [System.Text.Json.JsonValueKind]::Null) { $null } else { $arr[4].GetString() })  # LST
                    )
                }
                finally { $doc.Dispose() }
                $identityKey = [string]$ref[0]
                if (-not $refsByIdentity.ContainsKey($identityKey)) {
                    $refsByIdentity[$identityKey] = [System.Collections.Generic.List[object]]::new()
                }
                $refsByIdentity[$identityKey].Add($ref)
            }

            foreach ($identityKey in @($refsByIdentity.Keys)) {
                $items = @($refsByIdentity[$identityKey] | Sort-Object { [string]$_[3] }, { [string]$_[4] })
                foreach ($mergedRef in @(Merge-VulnObservedWindowSequence `
                        -Items $items `
                        -AllowedGapDays $AllowedGapDays `
                        -GetWindow {
                            param($item)
                            Get-NormalizedVulnSeenWindow -FirstSeenValue ([string]$item[3]) -LastSeenValue ([string]$item[4])
                        } `
                        -CreateItem {
                            param($item)
                            [object[]]$item.Clone()
                        } `
                        -CreateMergedItem {
                            param($candidate, $firstSeenTimestamp, $lastSeenTimestamp)
                            $merged = [object[]]$candidate.Clone()
                            $merged[3] = $firstSeenTimestamp
                            $merged[4] = $lastSeenTimestamp
                            $merged
                        } `
                        -FinalizeItem {
                            param($item, $window)
                            $item[3] = $window.FirstSeenTimestamp
                            $item[4] = $window.LastSeenTimestamp
                            $item
                        })) {
                    ,$mergedRef
                }
            }

            $refsByIdentity.Clear()
            $refsByIdentity = $null
            Remove-Item -LiteralPath $partPath -Force -ErrorAction SilentlyContinue
        }
    }
    finally {
        for ($i = 0; $i -lt $PartitionCount; $i++) {
            if ($null -ne $partitionWriters[$i]) {
                $partitionWriters[$i].Dispose()
            }
        }
        if (Test-Path -LiteralPath $partitionDir) {
            Remove-Item -Recurse -Force -LiteralPath $partitionDir -ErrorAction SilentlyContinue
        }
    }
}

function Publish-VulnObservedWindowCache {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [ValidateRange(0, 30)]
        [int]$AllowedGapDays = 1
    )

    $fingerprint = Get-VulnObservedWindowCacheFingerprint -BasePath $BasePath -AllowedGapDays $AllowedGapDays
    if ([string]::IsNullOrWhiteSpace($fingerprint)) {
        return $null
    }

    $cachePath = Get-VulnObservedWindowCachePath -BasePath $BasePath -Fingerprint $fingerprint -AllowedGapDays $AllowedGapDays -Create
    if (Test-Path -LiteralPath $cachePath -PathType Leaf) {
        Clear-StaleVulnObservedWindowCache -BasePath $BasePath -KeepPath $cachePath
        return $cachePath
    }

    $tempPath = Join-Path (Split-Path -Parent $cachePath) ('.tmp-' + [System.Guid]::NewGuid().ToString('N') + '.json.gz')
    $fileStream = $null
    $gzipStream = $null
    $writer = $null
    try {
        Write-Information ("  Building observed-window cache from vulnerability store ({0})..." -f $fingerprint.Substring(0, 12)) -InformationAction Continue
        $fileStream = [System.IO.File]::Create($tempPath)
        $gzipStream = [System.IO.Compression.GZipStream]::new($fileStream, [System.IO.Compression.CompressionMode]::Compress)
        $writer = [System.IO.StreamWriter]::new($gzipStream, [System.Text.UTF8Encoding]::new($false))

        if (Test-VulnContentStoreExistence -BasePath $BasePath) {
            # Memory-efficient path: merge returns compact ref arrays. Write
            # raw JSON lines directly using StringBuilder to avoid 1.5M+
            # ConvertTo-Json calls.
            Write-MergedVulnContentStoreRefs -BasePath $BasePath -AllowedGapDays $AllowedGapDays | ForEach-Object {
                $ref = $_
                if ($null -eq $ref) { return }
                # Build JSON array string inline — refs are [id, dpIdx, ctIdx, fst, lst]
                $sb = [System.Text.StringBuilder]::new(128)
                [void]$sb.Append('["')
                [void]$sb.Append([string]$ref[0])
                [void]$sb.Append('",')
                [void]$sb.Append([string]$ref[1])
                [void]$sb.Append(',')
                [void]$sb.Append([string]$ref[2])
                [void]$sb.Append(',')
                $fst = $ref[3]; if ($null -eq $fst) { [void]$sb.Append('null') } else { [void]$sb.Append('"'); [void]$sb.Append([string]$fst); [void]$sb.Append('"') }
                [void]$sb.Append(',')
                $lst = $ref[4]; if ($null -eq $lst) { [void]$sb.Append('null') } else { [void]$sb.Append('"'); [void]$sb.Append([string]$lst); [void]$sb.Append('"') }
                [void]$sb.Append(']')
                $writer.WriteLine($sb.ToString())
            }
        }
        else {
            # IMPORTANT: Use pipeline (| ForEach-Object) not foreach() to avoid
            # collecting all merged rows into memory at once.
            $legacyCacheJsonOptions = [System.Text.Json.JsonSerializerOptions]::new()
            $legacyCacheJsonOptions.WriteIndented = $false
            $legacyCacheJsonOptions.MaxDepth = 20
            Write-MergedVulnObservedWindowRows -Source { Read-VulnStoreRow -BasePath $BasePath } -AllowedGapDays $AllowedGapDays | ForEach-Object {
                if ($null -eq $_) { return }
                $dict = [System.Collections.Generic.Dictionary[string,object]]::new()
                foreach ($prop in $_.PSObject.Properties) { $dict[$prop.Name] = $prop.Value }
                $writer.WriteLine([System.Text.Json.JsonSerializer]::Serialize($dict, $legacyCacheJsonOptions))
            }
        }
    }
    finally {
        if ($writer) { $writer.Dispose() }
        elseif ($gzipStream) { $gzipStream.Dispose() }
        elseif ($fileStream) { $fileStream.Dispose() }
    }

    if (Test-Path -LiteralPath $cachePath -PathType Leaf) {
        Remove-Item -LiteralPath $tempPath -Force -ErrorAction SilentlyContinue
    }
    else {
        Move-Item -LiteralPath $tempPath -Destination $cachePath -Force
    }

    Clear-StaleVulnObservedWindowCache -BasePath $BasePath -KeepPath $cachePath
    return $cachePath
}

function Get-MachineFingerprintSourceFileSet {
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo[]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    $files = [System.Collections.Generic.List[System.IO.FileInfo]]::new()
    $currentPath = Get-MachineCurrentPath -BasePath $BasePath
    $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath
    $currentReadPath = if (Test-Path -LiteralPath $currentPath -PathType Leaf) { $currentPath } elseif (Test-Path -LiteralPath $legacyCurrentPath -PathType Leaf) { $legacyCurrentPath } else { $null }

    if ($null -ne $currentReadPath) {
        $files.Add((Get-Item -LiteralPath $currentReadPath))
    }
    else {
        $historySourcePaths = @(Get-MachineHistorySourcePaths -BasePath $BasePath)
        if ($historySourcePaths.Count -gt 0) {
            foreach ($sourcePath in $historySourcePaths) {
                if (Test-Path -LiteralPath $sourcePath -PathType Leaf) {
                    $files.Add((Get-Item -LiteralPath $sourcePath))
                }
            }
        }
        else {
            foreach ($legacyMachineFile in @(Get-ChildItem -Path $BasePath -Filter 'Machines_*.json' -File -ErrorAction SilentlyContinue | Where-Object { Test-IsLegacyMachineSnapshotFileName -Name $_.Name } | Sort-Object Name -Descending)) {
                $files.Add($legacyMachineFile)
            }
        }
    }

    return [System.IO.FileInfo[]]$files.ToArray()
}

function Get-AdvancedHuntingFingerprintSourceFileSet {
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo[]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    $files = [System.Collections.Generic.List[System.IO.FileInfo]]::new()
    $currentPath = Get-AdvancedHuntingCurrentPath -BasePath $BasePath
    $legacyCurrentPath = Get-LegacyCanonicalPath -Path $currentPath

    if ((-not (Test-Path -LiteralPath $currentPath -PathType Leaf)) -and (Test-Path -LiteralPath $legacyCurrentPath -PathType Leaf)) {
        $currentPath = $legacyCurrentPath
    }

    if (Test-Path -LiteralPath $currentPath -PathType Leaf) {
        $files.Add((Get-Item -LiteralPath $currentPath))
    }
    else {
        foreach ($legacyAhFile in @(Get-ChildItem -Path $BasePath -Filter 'AdvancedHunting_*.json' -File -ErrorAction SilentlyContinue |
                Where-Object { Test-IsLegacyAdvancedHuntingSnapshotFileName -Name $_.Name } |
                Sort-Object Name -Descending)) {
            $files.Add($legacyAhFile)
        }
    }

    return [System.IO.FileInfo[]]$files.ToArray()
}

function Get-NvdCveFingerprintSourceFileSet {
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo[]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath
    )

    $currentPath = Get-NvdCveCurrentPath -BasePath $BasePath
    if (-not (Test-Path -LiteralPath $currentPath -PathType Leaf)) {
        return @()
    }

    return [System.IO.FileInfo[]]@((Get-Item -LiteralPath $currentPath))
}

function Get-DashboardSourceFileSummary {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [System.IO.FileInfo[]]$Files
    )

    $sourceFiles = @($Files | Where-Object { $null -ne $_ } | Sort-Object FullName)
    $latestFile = @($sourceFiles | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1)
    $latestLastWriteTimeUtc = if ($latestFile.Count -gt 0) { $latestFile[0].LastWriteTimeUtc.ToUniversalTime() } else { $null }
    $ageSeconds = if ($null -ne $latestLastWriteTimeUtc) {
        [math]::Max(0, [int][math]::Round(((Get-Date).ToUniversalTime() - $latestLastWriteTimeUtc).TotalSeconds, 0))
    }
    else {
        $null
    }

    return [PSCustomObject]@{
        Present = ($sourceFiles.Count -gt 0)
        FileCount = [int]$sourceFiles.Count
        LatestLastWriteTimeUtc = if ($null -ne $latestLastWriteTimeUtc) { $latestLastWriteTimeUtc.ToString('o') } else { $null }
        AgeSeconds = $ageSeconds
        Files = @($sourceFiles | ForEach-Object {
                [PSCustomObject]@{
                    Name = $_.Name
                    Length = [long]$_.Length
                    LastWriteTimeUtc = $_.LastWriteTimeUtc.ToUniversalTime().ToString('o')
                }
            })
    }
}

function Get-DashboardSourceSummary {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [int]$MachineCount = 0,

        [Parameter(Mandatory = $false)]
        [int]$AdvancedHuntingCveCount = 0,

        [Parameter(Mandatory = $false)]
        [int]$AdvancedHuntingDeviceUserCount = 0,

        [Parameter(Mandatory = $false)]
        [int]$AdvancedHuntingInventoryTupleCount = 0,

        [Parameter(Mandatory = $false)]
        [int]$NvdCveCount = 0,

        [Parameter(Mandatory = $false)]
        [string]$NormalizationMode = 'unknown',

        [Parameter(Mandatory = $false)]
        [switch]$SkipObservedWindowMerge
    )

    return [PSCustomObject]@{
        Version = 'dashboard-source-metadata-v1'
        GeneratedOnUtc = (Get-Date).ToUniversalTime().ToString('o')
        NormalizationMode = $NormalizationMode
        SkipObservedWindowMerge = ($SkipObservedWindowMerge -eq $true)
        MachineData = [PSCustomObject]@{
            RecordCount = [int]$MachineCount
            Source = Get-DashboardSourceFileSummary -Files (Get-MachineFingerprintSourceFileSet -BasePath $BasePath)
        }
        AdvancedHunting = [PSCustomObject]@{
            CveCount = [int]$AdvancedHuntingCveCount
            DeviceUserCount = [int]$AdvancedHuntingDeviceUserCount
            InventoryTupleCount = [int]$AdvancedHuntingInventoryTupleCount
            Source = Get-DashboardSourceFileSummary -Files (Get-AdvancedHuntingFingerprintSourceFileSet -BasePath $BasePath)
        }
        NvdCve = [PSCustomObject]@{
            RecordCount = [int]$NvdCveCount
            Source = Get-DashboardSourceFileSummary -Files (Get-NvdCveFingerprintSourceFileSet -BasePath $BasePath)
        }
    }
}

function Get-VulnerabilityPayloadFingerprintSourceFileSet {
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo[]])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [switch]$SkipObservedWindowMerge
    )

    $effectiveSkipObservedWindowMerge = ($SkipObservedWindowMerge -or (Test-IsSyntheticDataset -BasePath $BasePath))
    $files = [System.Collections.Generic.List[System.IO.FileInfo]]::new()

    $contentStoreExists = Sync-VulnContentStoreSidecar -BasePath $BasePath
    if ((Test-VulnStoreExistence -BasePath $BasePath) -or $contentStoreExists) {
        if ($effectiveSkipObservedWindowMerge) {
            if ($contentStoreExists) {
                foreach ($path in @(
                        (Get-VulnContentDictionaryPath -BasePath $BasePath)
                        (Get-VulnCurrentRefsPath -BasePath $BasePath)
                    )) {
                    if (Test-Path -LiteralPath $path -PathType Leaf) {
                        $files.Add((Get-Item -LiteralPath $path))
                    }
                }

                foreach ($historyRefsFile in @(Get-ChildItem -Path $BasePath -Filter 'VulnHistoryRefs_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
                    $files.Add($historyRefsFile)
                }
            }
            else {
                $currentPath = Get-VulnCurrentPath -BasePath $BasePath
                if (Test-Path -LiteralPath $currentPath -PathType Leaf) {
                    $files.Add((Get-Item -LiteralPath $currentPath))
                }

                foreach ($historyRowsFile in @(Get-ChildItem -Path $BasePath -Filter 'VulnHistoryRows_*.json.gz' -File -ErrorAction SilentlyContinue | Sort-Object Name)) {
                    $files.Add($historyRowsFile)
                }
            }
        }
        else {
            $observedWindowCachePath = Publish-VulnObservedWindowCache -BasePath $BasePath
            if (-not [string]::IsNullOrWhiteSpace($observedWindowCachePath) -and (Test-Path -LiteralPath $observedWindowCachePath -PathType Leaf)) {
                $files.Add((Get-Item -LiteralPath $observedWindowCachePath))
            }
        }
    }
    else {
        foreach ($legacyFile in @(Get-VulnLegacySnapshotFile -BasePath $BasePath)) {
            if ($legacyFile -and (Test-Path -LiteralPath $legacyFile.FullName -PathType Leaf)) {
                $files.Add((Get-Item -LiteralPath $legacyFile.FullName))
            }
        }
    }

    return [System.IO.FileInfo[]]$files.ToArray()
}

function Get-NormalizedVulnColumnCacheFingerprint {
        [CmdletBinding()]
        [OutputType([string])]
        param(
            [Parameter(Mandatory = $true)]
            [string]$BasePath,

            [Parameter(Mandatory = $false)]
            [switch]$SkipObservedWindowMerge
        )

        if (-not (Sync-VulnContentStoreSidecar -BasePath $BasePath)) {
            return $null
        }

        $files = [System.Collections.Generic.List[System.IO.FileInfo]]::new()
        foreach ($file in @(Get-VulnerabilityPayloadFingerprintSourceFileSet -BasePath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge)) {
            if ($null -ne $file) {
                $files.Add($file)
            }
        }

        if ($files.Count -eq 0) {
            return $null
        }

        return (Get-FileSetFingerprint -Version 'dashboard-vuln-column-cache-v1' -Files @($files) -MetadataLines @(
                ('SkipObservedWindowMerge=' + ($SkipObservedWindowMerge -eq $true))
            ))
}

function Get-NormalizedVulnColumnCacheDirectoryPath {
        [CmdletBinding()]
        [OutputType([string])]
        param(
            [Parameter(Mandatory = $true)]
            [string]$BasePath,

            [Parameter(Mandatory = $true)]
            [string]$Fingerprint,

            [Parameter(Mandatory = $false)]
            [switch]$Create
        )

    $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'vuln-columns' -Create:$Create
    return Join-Path $cacheDirectory ("columns-{0}" -f $Fingerprint)
}

function Get-NormalizedVulnColumnCacheManifestPath {
        [CmdletBinding()]
        [OutputType([string])]
        param(
            [Parameter(Mandatory = $true)]
            [string]$BasePath,

            [Parameter(Mandatory = $true)]
            [string]$Fingerprint,

            [Parameter(Mandatory = $false)]
            [switch]$Create
        )

    $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'vuln-columns' -Create:$Create
    return Join-Path $cacheDirectory ("columns-{0}.json" -f $Fingerprint)
}

function Get-NormalizedVulnColumnCacheColumnPaths {
        [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '', Justification = 'Internal helper intentionally returns the full set of normalized vulnerability column paths.')]
        [CmdletBinding()]
        [OutputType([hashtable])]
        param(
            [Parameter(Mandatory = $true)]
            [string]$DirectoryPath
        )

        $paths = [ordered]@{}
        foreach ($columnName in @('d', 'c', 's', 'v', 'f', 'l', 'ua', 'u', 'dp', 'rp', 'iv')) {
            $paths[$columnName] = Join-Path $DirectoryPath ($columnName + '.json')
        }

    return $paths
}

function Clear-StaleNormalizedVulnColumnCache {
        [CmdletBinding()]
        param(
            [Parameter(Mandatory = $true)]
            [string]$BasePath,

            [Parameter(Mandatory = $false)]
            [string[]]$KeepPaths = @()
        )

        $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'vuln-columns'
        if (-not (Test-Path -LiteralPath $cacheDirectory -PathType Container)) {
            return
        }

        $normalizedKeepPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($keepPath in @($KeepPaths)) {
            if (-not [string]::IsNullOrWhiteSpace($keepPath)) {
                [void]$normalizedKeepPaths.Add([System.IO.Path]::GetFullPath($keepPath))
            }
        }

    foreach ($cacheItem in @(Get-ChildItem -Path $cacheDirectory -Force -ErrorAction SilentlyContinue)) {
        if ($normalizedKeepPaths.Contains($cacheItem.FullName)) {
            continue
        }

        Remove-Item -LiteralPath $cacheItem.FullName -Recurse -Force -ErrorAction SilentlyContinue
    }
}

function Get-NormalizedVulnColumnCacheEntry {
        [CmdletBinding()]
        [OutputType([pscustomobject])]
        param(
            [Parameter(Mandatory = $true)]
            [string]$BasePath,

            [Parameter(Mandatory = $false)]
            [switch]$SkipObservedWindowMerge
        )

        $fingerprint = Get-NormalizedVulnColumnCacheFingerprint -BasePath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge
        if ([string]::IsNullOrWhiteSpace($fingerprint)) {
            return $null
        }

        $columnDirectoryPath = Get-NormalizedVulnColumnCacheDirectoryPath -BasePath $BasePath -Fingerprint $fingerprint -Create
        $manifestPath = Get-NormalizedVulnColumnCacheManifestPath -BasePath $BasePath -Fingerprint $fingerprint -Create
        if ((-not (Test-Path -LiteralPath $columnDirectoryPath -PathType Container)) -or (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf))) {
            return $null
        }

        $columnPaths = Get-NormalizedVulnColumnCacheColumnPaths -DirectoryPath $columnDirectoryPath
        foreach ($columnPath in $columnPaths.Values) {
            if (-not (Test-Path -LiteralPath ([string]$columnPath) -PathType Leaf)) {
                return $null
            }
        }

        $manifest = Read-NormalizedPayloadManifest -Path $manifestPath
        if ($null -eq $manifest) {
            return $null
        }

        if ([string]$manifest.Fingerprint -ne $fingerprint) {
            return $null
        }

    Clear-StaleNormalizedVulnColumnCache -BasePath $BasePath -KeepPaths @($columnDirectoryPath, $manifestPath)
    return [PSCustomObject]@{
        Fingerprint = $fingerprint
        ColumnDirectoryPath = $columnDirectoryPath
        ColumnPaths = $columnPaths
        ManifestPath = $manifestPath
        Manifest = $manifest
    }
}

function Publish-NormalizedVulnColumnCache {
        [CmdletBinding()]
        [OutputType([pscustomobject])]
        param(
            [Parameter(Mandatory = $true)]
            [string]$BasePath,

            [Parameter(Mandatory = $true)]
            [hashtable]$VulnColumnPaths,

            [Parameter(Mandatory = $true)]
            [int]$VulnCount,

            [Parameter(Mandatory = $true)]
            [object[]]$Dates,

            [Parameter(Mandatory = $false)]
            [object]$Quality,

            [Parameter(Mandatory = $false)]
            [switch]$SkipObservedWindowMerge,

            [Parameter(Mandatory = $false)]
            [int]$InventoryTupleCount = 0
        )

        $fingerprint = Get-NormalizedVulnColumnCacheFingerprint -BasePath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge
        if ([string]::IsNullOrWhiteSpace($fingerprint)) {
            return $null
        }

        $columnDirectoryPath = Get-NormalizedVulnColumnCacheDirectoryPath -BasePath $BasePath -Fingerprint $fingerprint -Create
        $manifestPath = Get-NormalizedVulnColumnCacheManifestPath -BasePath $BasePath -Fingerprint $fingerprint -Create
        $existingEntry = Get-NormalizedVulnColumnCacheEntry -BasePath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge
        if ($existingEntry -and ([string]$existingEntry.Fingerprint -eq $fingerprint)) {
            return $existingEntry
        }

        if (-not (Test-Path -LiteralPath $columnDirectoryPath -PathType Container)) {
            [void](New-Item -Path $columnDirectoryPath -ItemType Directory -Force)
        }

        $cacheColumnPaths = Get-NormalizedVulnColumnCacheColumnPaths -DirectoryPath $columnDirectoryPath
        foreach ($columnName in @($cacheColumnPaths.Keys)) {
            $sourcePath = [string]$VulnColumnPaths[$columnName]
            $destinationPath = [string]$cacheColumnPaths[$columnName]
            if ([string]::IsNullOrWhiteSpace($sourcePath) -or -not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) {
                return $null
            }

            Copy-Item -LiteralPath $sourcePath -Destination $destinationPath -Force
        }

        $manifest = [ordered]@{
            Version = 'dashboard-vuln-column-cache-v1'
            Fingerprint = $fingerprint
            GeneratedOnUtc = (Get-Date).ToUniversalTime().ToString('o')
            VulnCount = $VulnCount
            Dates = @($Dates)
            Quality = $Quality
            SkipObservedWindowMerge = ($SkipObservedWindowMerge -eq $true)
            InventoryTupleCount = $InventoryTupleCount
        }
        Write-NormalizedPayloadManifest -Path $manifestPath -Manifest $manifest | Out-Null

    Clear-StaleNormalizedVulnColumnCache -BasePath $BasePath -KeepPaths @($columnDirectoryPath, $manifestPath)
    return [PSCustomObject]@{
        Fingerprint = $fingerprint
        ColumnDirectoryPath = $columnDirectoryPath
        ColumnPaths = $cacheColumnPaths
        ManifestPath = $manifestPath
        Manifest = [PSCustomObject]$manifest
    }
}

function Get-DashboardPayloadCacheFingerprint {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [switch]$SkipObservedWindowMerge
    )

    $files = [System.Collections.Generic.List[System.IO.FileInfo]]::new()
    foreach ($file in @(Get-VulnerabilityPayloadFingerprintSourceFileSet -BasePath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge)) {
        if ($null -ne $file) { $files.Add($file) }
    }
    foreach ($file in @(Get-MachineFingerprintSourceFileSet -BasePath $BasePath)) {
        if ($null -ne $file) { $files.Add($file) }
    }
    foreach ($file in @(Get-AdvancedHuntingFingerprintSourceFileSet -BasePath $BasePath)) {
        if ($null -ne $file) { $files.Add($file) }
    }
    foreach ($file in @(Get-NvdCveFingerprintSourceFileSet -BasePath $BasePath)) {
        if ($null -ne $file) { $files.Add($file) }
    }

    if ($files.Count -eq 0) {
        return $null
    }

    return (Get-FileSetFingerprint -Version 'dashboard-payload-cache-v5' -Files @($files) -MetadataLines @(
            ('SkipObservedWindowMerge=' + ($SkipObservedWindowMerge -eq $true))
        ))
}

function Get-NormalizedPayloadCachePath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $true)]
        [string]$Fingerprint,

        [Parameter(Mandatory = $false)]
        [switch]$Create
    )

    $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'payloads' -Create:$Create
    return Join-Path $cacheDirectory ("payload-{0}.json.gz" -f $Fingerprint)
}

function Get-NormalizedPayloadCacheManifestPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $true)]
        [string]$Fingerprint,

        [Parameter(Mandatory = $false)]
        [switch]$Create
    )

    $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'payloads' -Create:$Create
    return Join-Path $cacheDirectory ("payload-{0}.json" -f $Fingerprint)
}

function Get-NormalizedPayloadSiblingManifestPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$PayloadPath
    )

    $resolvedPayloadPath = [System.IO.Path]::GetFullPath($PayloadPath)
    if ($resolvedPayloadPath.EndsWith('.json.gz', [System.StringComparison]::OrdinalIgnoreCase)) {
        return ($resolvedPayloadPath.Substring(0, $resolvedPayloadPath.Length - '.gz'.Length))
    }

    return ($resolvedPayloadPath + '.json')
}

function Write-CombinedPayloadGzipFallback {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        $Lookups,

        [Parameter(Mandatory = $true)]
        [string]$VulnsPath,

        [Parameter(Mandatory = $true)]
        [string]$OutputPath
    )

    $payload = [ordered]@{
        lookups = $Lookups
        vulnsFormat = 'rows-v1'
        vulns = (Get-Content -Path $VulnsPath -Raw | ConvertFrom-Json -Depth 20)
    }
    $json = $payload | ConvertTo-Json -Compress -Depth 100

    $fileStream = [System.IO.File]::Create($OutputPath)
    try {
        $gzip = [System.IO.Compression.GZipStream]::new($fileStream, [System.IO.Compression.CompressionLevel]::Fastest)
        try {
            $writer = [System.IO.StreamWriter]::new($gzip, [System.Text.UTF8Encoding]::new($false))
            try {
                $writer.Write($json)
            }
            finally {
                $writer.Dispose()
            }
        }
        finally {
            $gzip.Dispose()
        }
    }
    finally {
        $fileStream.Dispose()
    }
}

function Resolve-NormalizedPayloadManifestPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$PayloadPath,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$ManifestPath
    )

    if (-not [string]::IsNullOrWhiteSpace($ManifestPath)) {
        return [System.IO.Path]::GetFullPath($ManifestPath)
    }

    if (-not [string]::IsNullOrWhiteSpace($PayloadPath)) {
        return (Get-NormalizedPayloadSiblingManifestPath -PayloadPath $PayloadPath)
    }

    return $null
}

function ConvertTo-NormalizedPayloadManifestRecord {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        $Manifest
    )

    $record = [ordered]@{}
    if ($Manifest -is [System.Collections.IDictionary]) {
        foreach ($key in $Manifest.Keys) {
            $record[[string]$key] = $Manifest[$key]
        }
    }
    else {
        foreach ($property in $Manifest.PSObject.Properties) {
            $record[$property.Name] = $property.Value
        }
    }

    return $record
}

function Confirm-NormalizedPayloadManifestPayloadSha {
    [CmdletBinding()]
    [OutputType([hashtable])]
    param(
        [Parameter(Mandatory = $true)]
        $Manifest,

        [Parameter(Mandatory = $true)]
        [string]$PayloadPath,

        [Parameter(Mandatory = $false)]
        [switch]$ThrowOnMismatch
    )

    $manifestRecord = ConvertTo-NormalizedPayloadManifestRecord -Manifest $Manifest
    $actualPayloadSha256 = Get-FileSha256Hex -Path $PayloadPath
    $manifestPayloadSha256 = if ($manifestRecord.Contains('PayloadSha256')) { [string]$manifestRecord.PayloadSha256 } else { '' }

    if (
        -not [string]::IsNullOrWhiteSpace($manifestPayloadSha256) -and
        -not [System.StringComparer]::OrdinalIgnoreCase.Equals($manifestPayloadSha256, $actualPayloadSha256)
    ) {
        $message = "Normalized payload hash mismatch for '$PayloadPath'. Manifest has '$manifestPayloadSha256' but file is '$actualPayloadSha256'."
        if ($ThrowOnMismatch) {
            throw $message
        }

        Write-Warning $message
        return $null
    }

    $manifestRecord.PayloadSha256 = $actualPayloadSha256
    return $manifestRecord
}

function Export-NormalizedPayloadArtifacts {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseSingularNouns', '', Justification = 'Internal helper optionally writes both payload and manifest outputs as one operation.')]
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$PayloadPath,

        [Parameter(Mandatory = $true)]
        $PayloadManifest,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$OutputPayloadPath,

        [Parameter(Mandatory = $false)]
        [AllowEmptyString()]
        [string]$OutputManifestPath
    )

    $resolvedOutputPayloadPath = if (-not [string]::IsNullOrWhiteSpace($OutputPayloadPath)) { [System.IO.Path]::GetFullPath($OutputPayloadPath) } else { $null }
    $resolvedOutputManifestPath = Resolve-NormalizedPayloadManifestPath -PayloadPath $resolvedOutputPayloadPath -ManifestPath $OutputManifestPath

    if (-not [string]::IsNullOrWhiteSpace($resolvedOutputPayloadPath)) {
        $payloadDirectory = Split-Path -Path $resolvedOutputPayloadPath -Parent
        if (-not [string]::IsNullOrWhiteSpace($payloadDirectory) -and -not (Test-Path -LiteralPath $payloadDirectory -PathType Container)) {
            [void](New-Item -Path $payloadDirectory -ItemType Directory -Force)
        }

        Copy-Item -LiteralPath $PayloadPath -Destination $resolvedOutputPayloadPath -Force
    }

    if (-not [string]::IsNullOrWhiteSpace($resolvedOutputManifestPath)) {
        Write-NormalizedPayloadManifest -Path $resolvedOutputManifestPath -Manifest $PayloadManifest | Out-Null
    }

    return [PSCustomObject]@{
        PayloadPath = $resolvedOutputPayloadPath
        ManifestPath = $resolvedOutputManifestPath
    }
}

function Read-NormalizedPayloadManifest {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        return $null
    }

    return (Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json -Depth 30)
}

function Write-NormalizedPayloadManifest {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,

        [Parameter(Mandatory = $true)]
        $Manifest
    )

    $resolvedPath = [System.IO.Path]::GetFullPath($Path)
    $directoryPath = Split-Path -Path $resolvedPath -Parent
    if (-not [string]::IsNullOrWhiteSpace($directoryPath) -and -not (Test-Path -LiteralPath $directoryPath -PathType Container)) {
        [void](New-Item -Path $directoryPath -ItemType Directory -Force)
    }

    $tempPath = Join-Path $directoryPath ('.tmp-' + [System.Guid]::NewGuid().ToString('N') + '.json')
    [System.IO.File]::WriteAllText($tempPath, ($Manifest | ConvertTo-Json -Compress -Depth 30), [System.Text.UTF8Encoding]::new($false))
    Move-Item -LiteralPath $tempPath -Destination $resolvedPath -Force
    return $resolvedPath
}

function Get-DashboardSemanticValidationLogicVersion {
    [CmdletBinding()]
    [OutputType([string])]
    param()

    return 'streaming-large-dataset-v3'
}

function Set-NormalizedPayloadSemanticValidationAttestation {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Internal helper only rewrites a local cache manifest during scripted validation flow.')]
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ManifestPath,

        [Parameter(Mandatory = $true)]
        [string]$ExpectedFingerprint,

        [Parameter(Mandatory = $true)]
        $Attestation
    )

    $manifest = Read-NormalizedPayloadManifest -Path $ManifestPath
    if ($null -eq $manifest) {
        return $null
    }

    if ([string]$manifest.Fingerprint -ne $ExpectedFingerprint) {
        return $null
    }

    $manifestRecord = [ordered]@{}
    foreach ($property in $manifest.PSObject.Properties) {
        $manifestRecord[$property.Name] = $property.Value
    }

    $manifestRecord.SemanticValidationAttestation = $Attestation
    Write-NormalizedPayloadManifest -Path $ManifestPath -Manifest $manifestRecord | Out-Null
    return ([pscustomobject]$manifestRecord)
}

function Get-DashboardValidationSidecarPath {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath
    )

    return ([System.IO.Path]::GetFullPath($HtmlPath) + '.validation.json')
}

function Read-DashboardValidationSidecar {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath
    )

    $sidecarPath = Get-DashboardValidationSidecarPath -HtmlPath $HtmlPath
    if (-not (Test-Path -LiteralPath $sidecarPath -PathType Leaf)) {
        return $null
    }

    return (Get-Content -LiteralPath $sidecarPath -Raw | ConvertFrom-Json -Depth 30)
}

function Write-DashboardValidationSidecar {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath,

        [Parameter(Mandatory = $true)]
        $PayloadManifest,

        [Parameter(Mandatory = $true)]
        [string]$DashboardPayloadSha256,

        [Parameter(Mandatory = $true)]
        [int]$DashboardPayloadRowCount
    )

    $resolvedHtmlPath = [System.IO.Path]::GetFullPath($HtmlPath)
    $sidecarPath = Get-DashboardValidationSidecarPath -HtmlPath $resolvedHtmlPath
    $payloadSha256 = if ($PayloadManifest.PSObject.Properties['PayloadSha256'] -and -not [string]::IsNullOrWhiteSpace([string]$PayloadManifest.PayloadSha256)) {
        [string]$PayloadManifest.PayloadSha256
    }
    else {
        $null
    }

    $sidecar = [ordered]@{
        Version = 'dashboard-validation-sidecar-v1'
        HtmlPath = $resolvedHtmlPath
        GeneratedOnUtc = (Get-Date).ToUniversalTime().ToString('o')
        SourceFingerprint = [string]$PayloadManifest.Fingerprint
        PayloadSha256 = $payloadSha256
        PayloadRowCount = [int]$PayloadManifest.VulnCount
        DeviceCount = [int]$PayloadManifest.DeviceCount
        CveCount = [int]$PayloadManifest.CveCount
        Quality = $PayloadManifest.Quality
        SourceMetadata = if ($PayloadManifest.PSObject.Properties['SourceMetadata']) { $PayloadManifest.SourceMetadata } else { $null }
        SkipObservedWindowMerge = [bool]($PayloadManifest.PSObject.Properties['SkipObservedWindowMerge'] -and $PayloadManifest.SkipObservedWindowMerge)
        DashboardPayloadSha256 = $DashboardPayloadSha256
        DashboardPayloadRowCount = $DashboardPayloadRowCount
        DashboardPayloadMatchesNormalizedPayload = (($DashboardPayloadSha256 -eq $payloadSha256) -and ($DashboardPayloadRowCount -eq [int]$PayloadManifest.VulnCount))
        SemanticValidationAttestation = if ($PayloadManifest.PSObject.Properties['SemanticValidationAttestation']) { $PayloadManifest.SemanticValidationAttestation } else { $null }
    }

    Write-NormalizedPayloadManifest -Path $sidecarPath -Manifest $sidecar | Out-Null
    return $sidecarPath
}

function Set-DashboardValidationSidecarSemanticAttestation {
    [Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseShouldProcessForStateChangingFunctions', '', Justification = 'Internal helper only rewrites a local validation sidecar during scripted validation flow.')]
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$HtmlPath,

        [Parameter(Mandatory = $true)]
        $Attestation
    )

    $sidecarPath = Get-DashboardValidationSidecarPath -HtmlPath $HtmlPath
    $sidecar = Read-DashboardValidationSidecar -HtmlPath $HtmlPath
    if ($null -eq $sidecar) {
        return $null
    }

    $sidecarRecord = [ordered]@{}
    foreach ($property in $sidecar.PSObject.Properties) {
        $sidecarRecord[$property.Name] = $property.Value
    }

    $sidecarRecord.SemanticValidationAttestation = $Attestation
    Write-NormalizedPayloadManifest -Path $sidecarPath -Manifest $sidecarRecord | Out-Null
    return ([pscustomobject]$sidecarRecord)
}

function Clear-StaleNormalizedPayloadCache {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [string[]]$KeepPaths = @()
    )

    $cacheDirectory = Get-DashboardCacheDirectory -BasePath $BasePath -ChildPath 'payloads'
    if (-not (Test-Path -LiteralPath $cacheDirectory -PathType Container)) {
        return
    }

    $normalizedKeepPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($keepPath in @($KeepPaths)) {
        if (-not [string]::IsNullOrWhiteSpace($keepPath)) {
            [void]$normalizedKeepPaths.Add([System.IO.Path]::GetFullPath($keepPath))
        }
    }

    foreach ($cacheFile in @(Get-ChildItem -Path $cacheDirectory -File -ErrorAction SilentlyContinue)) {
        if ($normalizedKeepPaths.Contains($cacheFile.FullName)) {
            continue
        }

        Remove-Item -LiteralPath $cacheFile.FullName -Force -ErrorAction SilentlyContinue
    }
}

function Get-NormalizedPayloadCacheEntry {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $false)]
        [switch]$SkipObservedWindowMerge
    )

    $fingerprint = Get-DashboardPayloadCacheFingerprint -BasePath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge
    if ([string]::IsNullOrWhiteSpace($fingerprint)) {
        return $null
    }

    $payloadPath = Get-NormalizedPayloadCachePath -BasePath $BasePath -Fingerprint $fingerprint -Create
    $manifestPath = Get-NormalizedPayloadCacheManifestPath -BasePath $BasePath -Fingerprint $fingerprint -Create
    if ((-not (Test-Path -LiteralPath $payloadPath -PathType Leaf)) -or (-not (Test-Path -LiteralPath $manifestPath -PathType Leaf))) {
        return $null
    }

    $manifest = Read-NormalizedPayloadManifest -Path $manifestPath
    if ([string]$manifest.Fingerprint -ne $fingerprint) {
        return $null
    }

    $manifestRecord = Confirm-NormalizedPayloadManifestPayloadSha -Manifest $manifest -PayloadPath $payloadPath
    if ($null -eq $manifestRecord) {
        return $null
    }

    $manifest = [PSCustomObject]$manifestRecord

    Clear-StaleNormalizedPayloadCache -BasePath $BasePath -KeepPaths @($payloadPath, $manifestPath)
    return [PSCustomObject]@{
        Fingerprint = $fingerprint
        PayloadPath = $payloadPath
        ManifestPath = $manifestPath
        Manifest = $manifest
    }
}

function Publish-NormalizedPayloadCache {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory = $true)]
        [string]$BasePath,

        [Parameter(Mandatory = $true)]
        [string]$PayloadPath,

        [Parameter(Mandatory = $true)]
        [int]$VulnCount,

        [Parameter(Mandatory = $true)]
        [int]$DeviceCount,

        [Parameter(Mandatory = $true)]
        [int]$CveCount,

        [Parameter(Mandatory = $false)]
        [object]$Quality,

        [Parameter(Mandatory = $false)]
        [object]$SourceMetadata,

        [Parameter(Mandatory = $false)]
        [switch]$SkipObservedWindowMerge
    )

    $fingerprint = Get-DashboardPayloadCacheFingerprint -BasePath $BasePath -SkipObservedWindowMerge:$SkipObservedWindowMerge
    if ([string]::IsNullOrWhiteSpace($fingerprint)) {
        return $null
    }

    $cachePayloadPath = Get-NormalizedPayloadCachePath -BasePath $BasePath -Fingerprint $fingerprint -Create
    $cacheManifestPath = Get-NormalizedPayloadCacheManifestPath -BasePath $BasePath -Fingerprint $fingerprint -Create
    $tempPayloadPath = Join-Path (Split-Path -Parent $cachePayloadPath) ('.tmp-' + [System.Guid]::NewGuid().ToString('N') + '.json.gz')
    $payloadSha256 = Get-FileSha256Hex -Path $PayloadPath

    Copy-Item -LiteralPath $PayloadPath -Destination $tempPayloadPath -Force
    $manifest = [ordered]@{
        Version = 'dashboard-payload-cache-v6'
        Fingerprint = $fingerprint
        GeneratedOnUtc = (Get-Date).ToUniversalTime().ToString('o')
        PayloadSha256 = $payloadSha256
        VulnCount = $VulnCount
        DeviceCount = $DeviceCount
        CveCount = $CveCount
        Quality = $Quality
        SourceMetadata = $SourceMetadata
        SkipObservedWindowMerge = ($SkipObservedWindowMerge -eq $true)
        SemanticValidationAttestation = $null
    }
    Write-NormalizedPayloadManifest -Path $cacheManifestPath -Manifest $manifest | Out-Null

    Move-Item -LiteralPath $tempPayloadPath -Destination $cachePayloadPath -Force
    Clear-StaleNormalizedPayloadCache -BasePath $BasePath -KeepPaths @($cachePayloadPath, $cacheManifestPath)

    return [PSCustomObject]@{
        Fingerprint = $fingerprint
        PayloadPath = $cachePayloadPath
        ManifestPath = $cacheManifestPath
        Manifest = [PSCustomObject]$manifest
    }
}

function Convert-CveUrl {
    [CmdletBinding()]
    [OutputType([string])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        [AllowEmptyString()]
        [string]$Url
    )

    if ([string]::IsNullOrWhiteSpace($Url)) {
        return $Url
    }

    if ($Url -match '^https://(?:portal\.)?msrc\.microsoft\.com/en-US/security-guidance/advisory/(CVE-\d{4}-\d+)') {
        $cveId = $Matches[1]
        return "https://msrc.microsoft.com/update-guide/vulnerability/$cveId"
    }

    return $Url
}

function Get-GzipLine {
    param([string]$Path)
    $fs = [System.IO.File]::OpenRead($Path)
    $gs = [System.IO.Compression.GZipStream]::new($fs, [System.IO.Compression.CompressionMode]::Decompress)
    $lr = [System.IO.StreamReader]::new($gs, [System.Text.Encoding]::UTF8)
    try {
        while (-not $lr.EndOfStream) { $lr.ReadLine() }
    }
    finally { $lr.Dispose() }
}

function Get-OrCreateIndex {
    param($value, $list, $indexMap)
    if ($null -eq $value -or $value -eq '') { return -1 }
    $key = if ($value -is [string]) { $value } else { $value.ToString() }
    if (-not $indexMap.ContainsKey($key)) {
        $indexMap[$key] = $list.Count
        $list.Add($key)
    }
    return $indexMap[$key]
}

